pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: residuals too small to be useful are heavily penalized.
    // Anything below the minimum item size (1) is impossible, but small gaps
    // (< ~20) are unlikely to be filled by typical items; penalize quadratically.
    if post_residual < 20 {
        score += 40.0 * (20.0 - post_residual as f64);
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally how well next item fills the gap.
            let fill = next_item_size as f64 / post_residual as f64;
            if fill > 0.7 {
                score -= 20.0 * fill;
            }
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < 60 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing bins
    // (penalize the new-bin candidate and discourage spreading).
    let open_pressure = open_bins_count as f64 / (1.0 + bin_capacity as f64 / 10.0);
    score += open_pressure * 3.0;

    // New-bin candidate handling: opening a new bin should only win when the
    // current placement creates large dead space or bins are very fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // More attractive if existing bins are fragmented (high mean residual
        // relative to capacity means poor consolidation).
        score -= 40.0 * (mean_residual / bin_capacity as f64);
        // Early in stream, opening bins is cheaper (room to plan).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    }

    // Mild preference for placing into bins whose residual deviates from mean
    // (consolidate toward tighter bins).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are unusable "dead space" -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gap: partially usable, moderate penalty scaled by how dead it is.
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual that still stays usable).
    if post_residual > 0 && post_residual >= 10 {
        score -= 12.0 / post_residual as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // reward leaving that gap; penalize if the gap is just barely too small.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 25.0; // sets up a near-perfect fit for next item
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // gap blocks the next item
        }
    }

    // Open-bins pressure: discourage scattering across many open bins,
    // but only mildly, so tight fits still dominate.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (unless dead space would result).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when this
    // bin would leave a large, wasteful residual or dead space.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; slightly above a good fit,
        // below a wasteful placement.
        score = 45.0 + open_bins_count as f64 * 0.3;
        // If the current bin would be nearly empty after placement anyway,
        // opening a fresh bin is fine.
        if post_residual > 60 {
            score -= 20.0;
        }
        // Reserve fresh bins for large items.
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (bin_residual as f64 - post_residual as f64) * 0.05;
    score -= progress * 5.0;

    // Mean-residual coupling: if this bin is far below the mean residual,
    // filling it is cheap; if it's the fullest bin, slight penalty.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be usable
    // later are heavily penalized. Anything below the minimum item size (1)
    // is perfect; residuals in a "dead zone" (too small for typical items)
    // are punished super-linearly.
    let dead_threshold = 10.0; // smallest historical item size
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Non-linear penalty on mid-range dead space: residuals that few item
    // sizes can fill are worse than large residuals that remain flexible.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 30.0 {
        score += (30.0 - pr) * (30.0 - pr) * 0.05;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Open-bins pressure: discourage spreading across many bins when
        // alternatives exist.
        score += open_bins_count as f64 * 0.8;
    }

    // Prefer bins whose residual is below the mean (consolidating fullness).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward leaving that gap; otherwise penalize blocking the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: an empty bin has high residual; make it
    // moderately attractive only when the current fit would create large
    // dead space or when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
        score = pr + 20.0 - congestion * 2.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pairing lookahead items in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 10 classes.
    let class = (post_residual * 10) / bin_capacity.max(1);
    let class_center = (class as f64 + 0.5) * (cap / 10.0);

    // Reward leftover space that sits close to a harmonic class center
    // (predictable, reusable residue), penalize odd in-between leftovers.
    let deviation = (post_residual as f64 - class_center).abs();
    score += 0.8 * deviation;

    // Dead-space penalty: residuals that cannot host any plausible item
    // (very small leftovers) are heavily penalized, but exact-zero is perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Modulo arithmetic on next_item_size: does the next item divide the
    // leftover cleanly? If next_item_size > 0 and post_residual % next == 0
    // with next <= post_residual, this bin is a perfect two-step chain.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next_item_size <= post_residual {
            if post_residual % next_item_size == 0 {
                score -= 12.0;
            } else {
                // fractional waste if next item goes here
                let waste = post_residual % next_item_size;
                score += waste as f64 * 0.5;
            }
            // reward if next item fits tightly
            score -= (next / cap) * 6.0;
        } else {
            // next item cannot use this bin: leftover is final -> penalize
            score += 4.0 + (next / cap) * 3.0;
        }
    }

    // Integer-division threshold on item_size: big items (half capacity or
    // more) should prefer tight bins, small items tolerate loose fits.
    if item_size * 2 >= bin_capacity {
        score -= 5.0 * (1.0 - (post_residual as f64) / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate: only attractive when residuals are fragmented or
    // the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = item_size as f64 / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap as f64 * 0.35
            + 10.0 * pressure
            + 6.0 * progress
            - (open_bins_count as f64) * 0.3;
        if fragmentation > cap * 0.4 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is ideal.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - diff / (bin_capacity as f64));
            // bonus if next item still leaves a plausibly reusable remainder
            score -= 5.0 * (post_residual as f64 - nxt) / bin_capacity as f64;
        } else {
            // next item cannot follow into this bin: penalize proportionally to wasted space
            score += 10.0 + 0.5 * (nxt - post_residual as f64);
        }
        // if next item would perfectly fill bin_residual now, prefer leaving that shape
        if bin_residual as u32 == next_item_size && post_residual > 0 {
            score += 25.0;
        }
    } else {
        // last item: strongly prefer tightest fill
        score -= 30.0;
    }

    // Reward fitting into scarce bins (last chance before opening a new bin)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize creating small unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Coupling with mean residual: prefer bins below average residual (tighter bins)
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when few/no good fits or lookahead mismatch is severe
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let early = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 30.0 * pressure - 20.0 * (1.0 - early);
        if next_item_size > 0 && (bin_residual as u32 >= next_item_size + item_size) {
            score -= 10.0; // fresh bin can chain both items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post / cap;

    // smooth polynomial coupling of post_residual with stream progress
    let p_norm = post / cap;
    let coupling = p_norm * p_norm * (1.0 - progress) + p_norm * progress * (1.0 - p_norm);
    score += 3.0 * coupling;

    // penalize last-chance bins less (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 1.5 * (nxt / cap) * (1.0 - post / cap);
        } else {
            score += 1.0 * (1.0 - post / cap);
        }
    }

    // slight preference for bins tighter than the mean residual
    score += 0.5 * ((post - mean_residual) / cap);

    // new-bin candidate: prefer it only when post_residual would be very small
    if bin_residual == bin_capacity {
        score = 0.5 + 0.5 * (1.0 - progress) - (item_size as f64 / cap) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 15.0;
    }

    // Reward residuals that can still host a typical next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.2;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 - open_bins_count as f64 * 0.3 - progress * 3.0;
    } else {
        // New-bin candidate: only attractive if mean residual across open bins is small.
        score += 20.0 + mean_residual * 0.5;
    }

    // Prefer bins tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Reward post-residuals divisible by small harmonic steps (5,10,20,25)
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Penalize dead-space classes: tiny unusable leftovers
        if pr < 10 {
            score += (10 - pr) as f64 * 1.5;
        }
        // Integer-division threshold: leftover in [10, 25] can host small items
        if pr >= 10 && pr <= 25 {
            score -= 4.0;
        }
    } else {
        // Perfect fit
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let gap = (pr - next_item_size) as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        if pr == next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // New-bin candidate handling: make fresh bins attractive only when the
    // item fills a large harmonic fraction of the bin.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill >= 0.5 {
            score -= 10.0 + 10.0 * fill;
        } else {
            score += 15.0 * (1.0 - fill);
        }
        // Fewer open bins -> fresh bin cheaper
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer tighter bins relative to mean residual
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // Late in the stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below ~min item size 10)
    // are heavily penalized; a perfect or near-perfect fill is rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 400.0;
    } else if post_residual < 20 {
        score += 120.0; // awkward gap: neither full nor usable by small items
    } else {
        // Usable residual: mild reward proportional to how well it matches
        // typical item granularity, slightly favoring larger usable space.
        score -= (post_residual as f64 / bin_capacity as f64) * 30.0;
    }

    // Reward tight fits: item filling a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 80.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but relax as the stream progresses (early consolidation matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (6.0 - 4.0 * progress);

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably (below mean) so we drain smaller leftover spaces first.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: penalize creating stranded space.
        score += 60.0 + post_residual as f64 * 0.5;
    }

    // New-bin candidate bias: only prefer a fresh bin when all open bins
    // would create bad dead space (handled above); otherwise make the new bin
    // slightly unattractive to promote packing into open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain fit
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 150.0; // next item fits with small slack
            } else {
                // penalize large leftover after next item would fit
                let post2 = post_residual - next_item_size;
                score += post2 as f64 * 0.5;
                score -= 40.0;
            }
        } else {
            // next item does not fit this bin after placement: mild penalty
            score += 30.0;
        }
    }

    // Compare post_residual to mean residual: avoid leaving more slack than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is large
    // and no tight fit exists; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (step_index as f64 + 1.0);
        let mut new_bin_bonus = -20.0 + pressure * 50.0 + progress * 20.0;
        if item_size >= 50 {
            new_bin_bonus += 10.0; // large items pair well with fresh capacity
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_bin_bonus -= 60.0; // room to chain next item in fresh bin
        }
        score += new_bin_bonus;
    }

    // Mild penalty for very large dead space that few future items can use.
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 1.5;
    }

    // Slight preference for bins that are already well filled.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // Next item fits in post_residual: mild reward proportional to tightness
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Next item would NOT fit here: penalize leaving a gap next item can't use
    if next_item_size > 0 && next_item_size > post_residual {
        score += 40.0;
    }

    // Penalize small unusable dead space relative to mean residual
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score += 30.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // Early stream: prefer keeping residuals large (flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (post_residual as f64) * 0.5;

