    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: tighter fit preferred (already via post_residual).

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that is hard to reuse for typical items (>= ~10)
        if post_residual < 10 {
            score += 25.0;
        }
        // Reward residual that could still fit a plausible future item
        score -= (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead need
        score += 8.0;
    }

    // Last chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate logic: prefer opening a fresh bin when current fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Fresh bin baseline: attractive if existing fit is very loose
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio < 0.55 {
            score -= 55.0 * (0.55 - fit_ratio);
        } else {
            // Discard new bin when a decent fit exists elsewhere
            score += 30.0 + fit_ratio * 40.0;
        }
        // Early in stream, new bins are cheap; late, prefer consolidation
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += t * 15.0;
    }

    // Prefer bins below mean residual (keeps residuals balanced, avoids fragmentation)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.35;

    // Slight preference for using already-open bins over creating more
    if !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: modulo-10 classes relative to capacity
    let pr = post_residual;
    let class = pr % 10;
    // Residuals in {0,1,2} are near-perfect fits -> strong reward
    if pr == 0 {
        score -= 1000.0; // perfect closure, always take
    } else if class <= 2 {
        score -= 60.0;
    } else if class >= 8 {
        // residual close to next multiple of 10: dead space likely unusable
        score += 25.0;
    }

    // Integer-division thresholds: can a typical next item (<= 80) ever fit?
    if pr > 0 && pr < 10 {
        score += 40.0; // guaranteed dead space for items >= 10
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0; // perfect two-item chain
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.8;
        } else {
            // next item cannot fit here: penalize large leftover less strongly
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are bad
    if bin_residual == bin_capacity {
        // new empty bin: attractive if all open residuals are fragmented
        let frag = (mean_residual - post_residual as f64).abs();
        score -= 90.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 40.0; // big next item: fresh bin is valuable
        }
        if frag < 8.0 && mean_residual > 40.0 {
            score += 150.0; // open bins still roomy -> don't open new one
        }
        // discourage hoarding bins late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild penalty for wasting a very roomy bin on a tiny item
    if item_size * 4 < bin_residual {
        score += 10.0;
    }

    // Prefer filling bins with larger mean residual (balance across bins)
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item size (1)
    // are only "dead" if they can't fit the lookahead item or typical items.
    // Penalize small unusable gaps heavily.
    let min_useful = 1u32;
    if post_residual < min_useful {
        score += 1000.0; // perfect fit, extremely desirable (post_residual == 0)
    } else {
        // Gap smaller than next item and smaller than a mid-size item = likely dead space
        let next = if next_item_size == 0 { 30 } else { next_item_size };
        if post_residual < next {
            score += (next - post_residual) as f64 * 2.0;
        }
        // Very small gaps (<10) are almost always dead
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 5.0;
        }
    }

    // Reward tight fits (small waste relative to item)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over opening new ones; when few bins are open, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 0.5;

    // New-bin candidate: make it moderately attractive only when residuals
    // across open bins are large (existing bins are wasteful targets) or
    // the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let huge_item = (item_size as f64) > mean_r * 0.85;
        if huge_item {
            score -= 10.0;
        } else {
            score += 12.0 + mean_r * 0.1;
        }
    }

    // Slight preference for bins whose residual is close to item (best-fit core)
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

