    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bins pressure: mildly discourage spreading across many bins unless residual is large.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residual tighter than the mean (good fits), discourage outliers.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when nothing fits well (large item, poor fits elsewhere).
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (bin_residual as f64 - item_size as f64) > mean_residual + 20.0;
        if poor_fit {
            score -= 120.0;
        } else {
