    // Penalize small dead space more as stream advances (non-quadratic shaping)
    let dead_space_penalty = (norm_pr * norm_pr) * (1.0 + 3.0 * progress * progress) * 20.0;

    // Reward tight fits: item filling most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let tight_fit_bonus = fill_ratio * fill_ratio * 15.0 * (1.0 + progress);

    // Lookahead: if next item fits into post_residual, reward this placement
    let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
        let nfit = next_item_size as f64 / (pr + 1.0);
        nfit * nfit * 12.0
    } else if next_item_size > post_residual {
        6.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Last-chance bin: strongly favor using it to avoid opening new bins
    let last_chance = if fitting_bins_count == 1 { -10.0 * (1.0 + progress) } else { 0.0 };

    // Deviation from mean residual: prefer bins whose residual deviates (chunkier packing)
    let mean_dev = (bin_residual as f64 - mean_residual) / cap;
    let dev_term = mean_dev * mean_dev * 8.0 * (1.0 - progress);

    let mut score = progress_coupling * 30.0 + dead_space_penalty
        - tight_fit_bonus - lookahead_bonus + last_chance + dev_term;

    // New-bin candidate: make it moderately attractive only when fits are poor
    if bin_residual == bin_capacity {
        score = pr + 5.0 - tight_fit_bonus * 0.2 + dead_space_penalty * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled by capacity fraction.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;
    score = post_frac * 100.0;

    // Harmonic class of post_residual: residuals divisible by small moduli
    // are more reusable by future items.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 8.0; // round residuals highly reusable
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
        // Dead-space penalty: residuals below 10 are nearly useless.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        }
    } else {
        score -= 15.0; // perfect closure
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0; // keeps chain alive
            // integer-division class match: residual class of next item
            let cls = (pr / next_item_size.max(1)) as f64;
            score -= cls.min(3.0) * 2.0;
        } else {
            score += (next_item_size - pr) as f64 * 0.3; // wasted lookahead fit
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: discourage spreading; prefer consolidating into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    // Mean residual context: if this bin is much emptier than average, penalize slightly.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 5.0;

    // New-bin candidate: only open a new bin when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        // Opening a bin is penalized; tight fits elsewhere (post_residual small) win.
        score = 60.0 + item_size as f64 * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host the next item too
        }
        if fitting_bins_count == 0 {
            score -= 80.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are unusable dead space; the smaller the usable gap, the worse.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Penalize small non-zero post residuals heavily (dead space zones).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // guaranteed dead space
        } else if post_residual < 20 {
            score += 25.0; // likely dead space
        } else if post_residual < 30 {
            score += 8.0;
        }
    }

    // Reward tight fits: post_residual close to 0 is excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward using bins that would otherwise be nearly full (large item_size relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening new ones.
    score += 2.5 * open_bins_count as f64;

    // New-bin candidate: empty bin. Only attractive when no good fit exists
    // (few fitting bins) or the current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 35.0 + 6.0 * open_bins_count as f64;
        // But if this is the last-chance situation (only 1 fitting bin) and the fit
        // is poor, opening a fresh bin is reasonable.
        if fitting_bins_count <= 1 && post_residual < 20 && bin_residual != bin_capacity {
            score -= 30.0;
        }
        // Early stream: fewer bins open, opening is cheaper.
        score -= 15.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 18.0;
        } else {
            score -= 6.0;
        }
    }
    // Penalize if next item would be stranded by this placement's dead space.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Slight preference toward bins with residuals close to the item (mean alignment).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: how well does post_residual match next_item_size?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        if post_residual >= next_item_size {
            // Slack after the follow-up item would fit here next round:
            let slack = post - nxt;
            // Reward tight two-step packing: slack near 0 is ideal.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            // Extra bonus for an exact two-step fill.
            if slack == 0.0 {
                score -= 40.0;
            }
        } else {
            // post_residual cannot host next item: dead space risk grows
            // the closer post_residual is to (but below) next_item_size.
            let gap = nxt - post;
            score += 0.8 * gap;
            // Harsh penalty for leaving a nearly-matching but unusable sliver.
            if gap <= 5.0 {
                score += 15.0;
            }
        }
    }

    // Prefer bins whose residual is below mean (denser bins) for tight fits.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate rather than spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: only attractive when it enables a clean
    // two-step sequence (item + next item exactly fills it).
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 20.0;
        } else {
            score += 35.0; // discourage gratuitous bin opening
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize large dead space: residual too small for smallest future items
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits in post_residual, reward this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 4.0;
        }
        // If next item exactly fits post residual, strong bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, favor it heavily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early
    // or when mean residual across open bins is still large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_r = mean_residual;
        // Opening new bin is worse when existing bins have plenty of room
        score += 18.0 + mean_r * 0.15 - progress * 6.0;
        // Late in stream with fragmented bins, new bin slightly more acceptable
        if open_bins_count > 6 && mean_r < 25.0 {
            score -= 5.0;
        }
    }

    // Mild preference for filling bins with larger residuals when many bins open
    if open_bins_count > 3 {
        score -= (bin_residual as f64 - post_residual as f64) * 0.05;
    }

    // Global balance: discourage draining bins far below mean residual
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), normalized
    let mut score = pr / cap;

    // Non-linear coupling: post_residual^2 scaled by progress.
    // Early in the stream, large residuals are tolerable (future items can fill them);
    // late in the stream, dead space is nearly worthless, so penalize quadratically.
    let dead_space = (pr / cap) * (pr / cap);
    score += dead_space * (0.5 + 1.5 * progress);

    // Smooth reward for exact/near-exact fills using a saturating exponential
    let tightness = (1.0 - pr / cap).max(0.0);
    score -= tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.8;
    }

    // Penalize opening a new bin, more so as the stream progresses
    // (consolidation becomes more valuable over time)
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 0.6 + 0.4 * progress;
    }

    // Lookahead: if the next item fits into the post residual, reward leaving
    // that space; otherwise the residual is less valuable late in the stream.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 0.15 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 0.05 + 0.10 * progress;
    }

    // Coupling with mean residual: if this bin's post-residual deviates strongly
    // above the mean, it wastes capacity relative to the fleet; smooth quadratic.
    let dev = pr - mean_residual;
    score += 0.002 * dev * dev * (0.5 + progress);

    // Slight preference for bins with less residual overall (fill fuller bins first)
    score += 0.1 * (bin_residual as f64 / cap) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify by integer division thresholds
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Class A: perfect fit (post_residual is a harmonic residue near 0)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0; // near-perfect: dead space minimal
    } else if post_residual <= 20 {
        score -= 120.0;
    } else if post_residual <= 35 {
        score -= 40.0;
    }

    // Modulo arithmetic on post_residual: residues that combine well with
    // common item sizes (multiples of 5, 10) are more reusable.
    let mod10 = post_residual % 10;
    let mod5 = post_residual % 5;
    if mod10 == 0 {
        score -= 25.0;
    } else if mod5 == 0 {
        score -= 12.0;
    } else if mod10 <= 2 || mod10 >= 8 {
        score -= 4.0;
    } else {
        score += 6.0; // awkward residue (3,4,6,7)
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact or near-exact lookahead match is highly desirable
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 400.0;
            } else if slack <= 10 {
                score -= 150.0;
            } else {
                score -= (slack as f64).min(60.0) * 0.5;
            }
        } else {
            // next item cannot follow here; penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.6;
        }
    } else {
        // last item: any placement is fine, prefer tight fit
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // New-bin candidate handling: fresh empty bin should only win when no
    // open bin fits well. Penalize it mildly so good existing fits win,
    // but reward it when all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        let base = 60.0;
        // If current item is small relative to capacity, a new bin is cheap
        let size_frac = item_size as f64 / cap;
        score = base + size_frac * 40.0;
        // If many fitting bins exist, opening a new bin is wasteful
        if fitting_bins_count > 1 {
            score += 80.0;
        }
        // If next item is large, keeping current bins' residuals flexible helps
        if next_item_size > 60 {
            score -= 20.0;
        }
        // Late in the stream, avoid bin proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Global pressure: when mean residual is high, prefer filling bins well
    score -= mean_residual.min(100.0) * 0.05;

    // Slight preference to use more-open-bins states efficiently
    if open_bins_count > 5 {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps that cannot fit the lookahead item but could fit smaller items:
    // moderate penalty scaled by how "wasted" the gap is.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }
    // Perfect fit: zero residual is ideal -> strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward tight fits relative to current residual.
    score -= 0.5 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, allow opening new ones when fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.8 + 0.4 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if it beats filling a bad gap.
        score += pressure;
        if post_residual >= 0 && item_size >= 60 {
            score -= 10.0; // big items start fresh bins happily
        }
    } else {
        score += 0.15 * pressure;
    }

    // Mild alignment with mean residual: prefer bins near the mean state.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain fit
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 150.0; // next item fits with small slack
            } else {
                // penalize large leftover after next item would fit
                let post2 = post_residual - next_item_size;
                score += post2 as f64 * 0.5;
                score -= 40.0;
            }
        } else {
            // next item does not fit this bin after placement: mild penalty
            score += 30.0;
        }
    }

    // Compare post_residual to mean residual: avoid leaving more slack than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is large
    // and no tight fit exists; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (step_index as f64 + 1.0);
        let mut new_bin_bonus = -20.0 + pressure * 50.0 + progress * 20.0;
        if item_size >= 50 {
            new_bin_bonus += 10.0; // large items pair well with fresh capacity
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_bin_bonus -= 60.0; // room to chain next item in fresh bin
        }
        score += new_bin_bonus;
    }

    // Mild penalty for very large dead space that few future items can use.
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 1.5;
    }

    // Slight preference for bins that are already well filled.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is already the base score.
    // Penalize leaving dead space that is too small for typical future items.
    let dead_zone = 15.0;
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 1.5;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 + (post_residual - next_item_size) as f64 * -0.5;
        }
        // If next item cannot fit in post_residual, mild penalty for fragmenting.
        if (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
        if post_residual as f64 > bin_capacity as f64 * 0.5 {
            score += 10.0; // wasteful use of last chance
        }
    }

    // New-bin candidate handling: empty bin gets a baseline so it's chosen only
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity && bin_capacity == 100 {
        score += 20.0 + open_bins_count as f64 * 0.5;
        // Late in stream, opening new bins is cheap-ish; early on, prefer filling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Prefer bins with residual close to item_size relative to global mean residual:
    // using bins that deviate below mean residual conserves spread-out space.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.3;

    // Slight preference for bins already below mean residual (consolidating small leftovers)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Mild penalty for spreading across many open bins early on.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) coupling
    let mut score = pr * (1.0 + 0.8 * norm_pr + 0.6 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: tight packing matters more later in the stream
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward filling bins well: smooth bell-shaped reward around small post_residual
    let fill_quality = (-norm_pr * 4.0).exp();
    score -= 6.0 * fill_quality * norm_item;

    // Penalize dead space that no small item can use: cubic in norm_pr
    score += 2.0 * norm_pr * norm_pr * norm_pr * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward if next item can fit into post_residual smoothly
    if next_item_size > 0 {
        let next_fit = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 3.0 * (-next_fit * 5.0).exp();
        // penalize post_residual slightly too large for next item (wasted gap)
        if next_item_size as f64 > pr {
            score += 1.5;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.15 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins that are outliers (nearly full or distinct)
    let dev = (pr - mean_residual) / cap;
    score -= 2.0 * dev * dev;

    // New-bin candidate: smooth sigmoid gate — open a new bin only when item is large
    // relative to residual and progress is early (future items may need this space)
    if bin_residual == bin_capacity {
        let open_bias = 1.0 / (1.0 + (-8.0 * (norm_item - 0.5)).exp());
        score = pr + 4.0 * open_bias + 3.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 20.0; // never open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual (tight fit), with extra discount on exact
    // harmonic subdivisions of capacity (50, 25, 20, 10, 5, 0).
    let harmonic: [u32; 7] = [0, 5, 10, 20, 25, 50, 100];
    if harmonic.contains(&post_residual) {
        score -= 12.0;
    }

    // Dead-space penalty: leftovers that no typical item can use.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Integer-division threshold on post_residual: usable slabs of size >= next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: reward proportional to fit quality.
            let next_fit = (next_item_size as f64) / (post_residual as f64);
            score -= 10.0 * next_fit;
        } else {
            score += 6.0;
        }
        // Modulo arithmetic: leftover compatible with next item's harmonic class.
        if next_item_size <= 100 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 8.0;
        }
    } else {
        // Last item: strongly prefer the tightest possible placement.
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // and no open bin fits well.
    if bin_residual == bin_capacity {
        let frac = (item_size as f64) / cap;
        score = cap as f64 * (1.0 - frac) - 5.0;
        if fitting_bins_count == 0 {
            score -= 10.0;
        } else if fitting_bins_count > 2 {
            score += 8.0;
        }
    }

    // Late-stream consolidation: prefer reusing bins as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - pr / cap);

    // Mild pressure to spread across many open bins early (keeps flexibility),
    // and to consolidate when mean residual is high.
    if (mean_residual - pr).abs() < 1.0 {
        score -= 2.0;
    }
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small leftover gaps (1..=10) are almost unusable for future items (sizes >= 1,
    // but in practice tiny slivers waste capacity). Penalize them quadratically.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64) * (11.0 - post_residual as f64) / 10.0;
    }

    // Dead space that cannot even hold the lookahead item is worse than a gap
    // that the next item could still fill.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // --- Reward tight fits ---
    // Fill ratio of the bin after placement: the fuller, the better.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // --- Open-bin pressure ---
    // When many bins are open, prefer consolidating into existing ones;
    // when few are open, tolerate spreading to keep residuals usable.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 8.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // --- Last-chance bin ---
    // If this is the only bin that fits the item, avoid forcing a bad placement:
    // opening a new bin may be better when the fit leaves a tiny dead gap.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual <= 10 || (next_item_size > 0 && post_residual < next_item_size) {
            score += 45.0;
        } else {
            score -= 15.0; // decent fit into the only option: keep it
        }
    }

    // --- New-bin candidate bias ---
    // An empty bin has bin_residual == bin_capacity. Only prefer it when the
    // current stream is early (many items left to use fresh capacity) or the
    // fit here would create dead space. Otherwise make the new bin expensive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 30.0 * progress;
    }

    // Mild preference toward bins already below mean residual (rebalance gaps).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial lookahead match: next item still fits in the residual after placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // Penalize very small dead space (unusable slivers) unless it's a perfect match.
    if post_residual > 0 && post_residual < 10 && !(next_item_size > 0 && post_residual == next_item_size) {
        score += 25.0;
    }

    // Reward tight fits: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Compare against mean residual: placing in a bin with above-average residual
    // keeps tighter bins available for later items.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    } else if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Late in the stream, prefer closing out bins (reduce open bin count spread).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && post_residual < 20 {
        score -= 8.0;
    }

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for future items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: penalize if the next item cannot use the post-residual.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) < ni {
            score += 8.0 + 0.25 * ni;
        } else if (post_residual as f64) >= ni {
            score -= 10.0; // next item can stack here
        }
        // Reward residual that leaves room for next item but not too much slack.
        let gap = post_residual as f64 - ni;
        if gap >= 0.0 && gap < 10.0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: if mean residual is high, prefer filling existing bins.
    let mean_res_norm = mean_residual / cap;
    score += 15.0 * (mean_res_norm - 0.3) * (post_residual as f64) / cap;

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Discourage opening new bins when many bins are already open and one fits well.
    if bin_residual == bin_capacity {
        score += 35.0 - 10.0 * mean_res_norm;
    } else {
        score -= 5.0;
    }

    // Mild penalty on very large current item filling a mostly-full bin poorly.
    let fill = item_size as f64 / cap;
    score -= 5.0 * fill * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = if cap > 0.0 { pr / cap } else { 0.0 };

    // Non-linear coupling: wasted fraction penalized more strongly as stream progresses
    let waste_penalty = fit_frac * fit_frac * (1.0 + 3.0 * progress);
    score += 4.0 * waste_penalty;

    // Perfect-fit reward, amplified by polynomial in progress
    let perfect = (pr == 0) as i32 as f64;
    score -= 10.0 * perfect * (1.0 + progress * progress * 2.0);

    // Reward tight fits (small post_residual) with saturating non-linearity
    score -= 6.0 * (1.0 - fit_frac) * (1.0 - fit_frac);

    // Lookahead: bonus if next item fits the post-residual exactly or well
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        let ns = next_item_size as f64;
        let tight = (ns / cap) * (1.0 - slack / cap);
        score -= 8.0 * tight * (1.0 + 2.0 * progress);
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize residual that is too small to be useful
        let ns = next_item_size as f64;
        let gap = (ns - pr) / cap;
        score += 3.0 * gap * gap;
    }

    // Last-chance bin: strong incentive to use it before opening a new one
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * progress;
    }

    // Mild penalty for spreading across many open bins; smooth in count
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near the mean (smooth coupling)
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate: make empty bin moderately attractive only for large items
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score += 6.0 * (1.0 - big) * (1.0 - big) - 4.0 * big * big * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into 5 classes of 20.
    let class = (post_residual / 20) as f64;
    // Class 0 (residual < 20) is dead space -> strong penalty; class 1 (20..40) also weak.
    score -= (4.0 - class) * 6.0; // lower class => lower score => favored

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does post_residual class match next item's harmonic class?
    if next_item_size > 0 {
        let next_class = (next_item_size / 20) as f64;
        // reward if post_residual is large enough to host next item (or next item's class)
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // modulo harmony: post_residual % 20 close to next_item_size % 20 means a
        // chain of same-class items packs nicely
        let pr_mod = (post_residual % 20) as f64;
        let ni_mod = (next_item_size % 20) as f64;
        score -= (20.0 - (pr_mod - ni_mod).abs()) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and few bins are open (early stream / consolidation phase)
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > 60 && open_bins_count < 3 {
            score -= 45.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 20.0; // late stream: prefer closing out open bins
        }
    }

    // Prefer tighter bins relative to the mean residual
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Mild preference for keeping few open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to the residual being consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.8;

    // Lookahead: favor bins whose leftover could host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Progress pressure: later in the stream, be more frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if really unattractive elsewhere.
        score += 25.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward for current item
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to how snugly
            score -= 150.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item does not fit here: mild penalty scaled by overshoot
            score += 40.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening a brand-new bin when decent fits exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 80.0;
        // but allow new bin if current item is huge and would leave dead space anyway
        if item_size >= 70 {
            score -= 90.0;
        }
    }

    // Early stream: slight preference to consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * (item_size as f64) * 0.5;

    // Penalize dead space: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item would be stranded by this placement,
    // reward if this placement still leaves room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Prefer bins with below-average residual (concentrate packing into tighter bins).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Mild penalty for opening a new bin, growing with stream progress and open-bin count.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 20.0 * progress + (open_bins_count as f64) * 0.5;
    }

    // Slight preference for filling larger-residual bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (pr / cap); // 1.0 = perfect fit
    score -= 12.0 * tightness * tightness * cap * 0.1;

    // Penalize unusable dead space: post_residual too small for typical future items.
    // Smooth polynomial penalty that grows as pr shrinks below ~20.
    let dead = ((20.0 - pr) / 20.0).max(0.0);
    score += 15.0 * dead * dead;

    // Non-linear coupling: dead-space penalty is amplified later in the stream
    // (fewer chances to fill leftovers), smoothed via progress^2.
    score += 10.0 * dead * dead * progress * progress;

    // Early in stream, prefer spreading across bins (keep residuals flexible);
    // late in stream, prefer filling existing bins tightly.
    score += (1.0 - progress) * 4.0 * (pr / cap);
    score -= progress * 3.0 * (item_size as f64 / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward leaving that gap.
    if next_item_size > 0 {
        let nz = next_item_size as f64;
        if nz <= pr {
            let fit_quality = 1.0 - ((pr - nz) / cap);
            score -= 6.0 * fit_quality * fit_quality;
        } else {
            // Post residual can't hold next item: slight penalty, stronger late.
            score += 2.0 * progress;
        }
    }

    // Mild penalty for bins far below mean residual (keeps bin balance smooth).
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let post = post_residual as u32;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty: residuals below eighth are nearly unusable.
    if post < eighth {
        score += 30.0 * (eighth - post) as f64 / cap;
    } else if post < quarter {
        // Half-dead zone: mild penalty.
        score += 8.0 * (quarter - post) as f64 / cap;
    }

    // Perfect fit bonus (exact or near-exact residual).
    if post == 0 {
        score -= 25.0;
    } else if post <= 2 {
        score -= 12.0;
    }

    // Harmonic class: post_residual divisible by common item-size strides
    // (10, 20, 25, 50) means future items can tile it exactly.
    let harmonic_div: [u32; 4] = [10, 20, 25, 50];
    let mut div_bonus = 0.0;
    for d in harmonic_div.iter() {
        if post > 0 && post % *d == 0 {
            div_bonus += 6.0 * (*d as f64 / 10.0);
        }
    }
    score -= div_bonus.min(18.0);

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0;
        } else if next_item_size < post {
            let nxt_post = post - next_item_size;
            if nxt_post < eighth {
                score += 10.0; // would create new dead space
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's remainder: slight penalty
            score += 3.0 * (next_item_size - post).min(50) as f64 / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless residual is tiny).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post >= quarter {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin gets a mild exploration cost
    // so it is only chosen when open bins have bad residuals.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Spread control: prefer bins whose residual deviates favorably from mean.
    score += 0.5 * (mean_residual - bin_residual as f64).abs() / cap;

    // Tie-break: prefer tighter fills among many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the minimum item (1) are pure waste,
    // but gaps too small for typical items are near-waste. Penalize small residuals hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 25.0;
    }
    // If next item cannot fit here but fits elsewhere, mild penalty.
    if next_item_size > post_residual {
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // favor filling existing ones (a new empty bin has bin_residual == capacity, large post_residual,
    // so subtracting a pressure term based on open_bins_count from real bins biases toward them).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (2.0 + 3.0 * progress);
    if bin_residual < bin_capacity {
        score -= pressure.min(30.0);
    } else {
        // Brand-new bin candidate: penalize unless current bins are quite full on average.
        score += 8.0 + pressure * 0.5 - (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Slight preference for bins below mean residual (balancing) when residuals are similar.
    if bin_residual < bin_capacity {
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += diff * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect 2-step match: post_residual exactly fits the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward proportional to how close post_residual is to next item.
        score -= 60.0 * (1.0 - diff / 100.0).max(0.0);

        // Penalize dead space that cannot fit the next item.
        if post_residual < next_item_size {
            score += 25.0 + (next_item_size - post_residual) as f64;
        }

        // Slight penalty if post_residual is small but nonzero and unusable.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Prefer tighter fits generally: penalize large post_residual relative to mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless residuals of open bins are all poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If next item is large relative to post_residual of a fresh bin (i.e. plenty of room),
        // opening a new bin is more attractive when few alternatives exist.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Core: penalize leftover space (best-fit core), with superlinear waste penalty.
    let mut score = post * (1.0 + 0.01 * post / cap);

    // Perfect-fit bonus: strongly reward filling the bin exactly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 30.0; // chain of perfect fits
        } else {
            score -= 10.0 * (1.0 - slack_after_next / cap);
        }
    }
    // Penalize if next item would NOT fit here but would fit a roomier bin.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0 * (next_item_size - post_residual) as f64 / cap;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * item;
    }

    // New-bin candidate handling: opening a new bin is attractive for large items
    // or when all open fits are poor (high post_residual relative to mean residual).
    if bin_residual == bin_capacity {
        // Base new-bin score: mildly worse than a good existing fit.
        let mut nb = 25.0 + 0.5 * (cap - item);
        // Attractive early in the stream (future items can share the fresh bin).
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb -= 20.0 * (1.0 - progress);
        // Attractive when existing bins are fragmented (mean residual low).
        nb -= 0.3 * mean_residual;
        // Attractive when the item is big relative to capacity.
        nb -= 0.4 * item;
        // Unattractive when many bins already open (consolidation pressure).
        nb += 2.0 * open_bins_count as f64;
        // If next item is large, a fresh bin gives it room.
        if nxt >= 0.6 * cap {
            nb -= 15.0;
        }
        score = nb;
    }

    // Small global pressure: prefer consolidating into bins below mean residual.
    if bin_residual != bin_capacity {
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize wasted residual, with a mild convexity so small residuals are tolerated.
    let norm_pr = pr / cap;
    let mut score = 1.0 - (1.0 - norm_pr) * (1.0 - norm_pr);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); late, tolerate residual less.
    let coupling = norm_pr * (0.5 + 1.5 * progress * progress);
    score += 2.0 * coupling;

    // Smooth dead-space term: residuals too small for the smallest plausible item are waste.
    let dead = (norm_pr * (1.0 - norm_pr)).max(0.0);
    score -= 0.3 * dead;

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 1.5 * last_chance * (1.0 - progress);

    // Lookahead: reward if next item can use the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = (pr - nxt) / cap;
            score -= 0.8 * (1.0 - fit_quality * fit_quality);
        } else {
            score += 0.5 * ((nxt - pr) / cap);
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.2 * (open_bins_count as f64 / (1.0 + progress * 10.0)) * norm_pr;

    // Relative residual vs mean: prefer bins below mean residual (tighter fills).
    score += 0.4 * ((pr - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that form "nice" fill
    // classes (multiples of 10, or small enough to be likely dead space)
    // are treated differently from awkward mid-range residuals.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual as capacity fraction

    // Integer-division thresholds on post_residual
    let class = post_residual / 10; // harmonic class bucket (0..=10)
    let is_multiple_of_10 = post_residual % 10 == 0;
    let awkward = post_residual > 0 && post_residual < 10; // tiny dead space

    // Reward round residuals (likely to be reusable by future items)
    if is_multiple_of_10 && post_residual > 0 {
        score -= 6.0;
    }
    // Penalize unusable slivers
    if awkward {
        score += 12.0;
    }
    // Penalize mid-range awkward classes (residuals in 11..49 are hard to fill
    // with items of size >= 10 unless exactly matching)
    if post_residual >= 11 && post_residual <= 49 {
        score += 3.0 + 0.1 * (49 - post_residual) as f64;
    }
    // Perfect fit is best
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item cannot use this bin's remainder; penalize proportionally
            score += 0.05 * next_item_size as f64;
        }
        // Harmonic modulo check: next_item_size and post_residual share class
        if post_residual >= next_item_size && (post_residual % next_item_size.max(1)) == 0 {
            score -= 4.0;
        }
    }

    // New-bin candidate handling: an empty bin is a strategic reserve.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress
        // and how crowded the current bins are.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.35 * cap + 15.0 * (1.0 - progress);
        // If existing bins are crowded (low mean residual), new bin is fine
        if mean_residual < 0.25 * cap {
            score -= 10.0;
        }
        // If this is a large item and few bins fit it, new bin is reasonable
        if item_size > 50 && fitting_bins_count <= 1 {
            score -= 8.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere:
        // that is handled by the -50 on post_residual == 0 elsewhere.
        return score;
    }

    // Mild preference for tighter (fuller) bins among open candidates
    score -= 0.05 * (1.0 - frac) * cap;

    // Slight penalty for spreading across too many bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size ~1..100, treat < 15 as dead)
    // are heavily penalized; medium gaps are mildly penalized.
    if post_residual > 0 {
        if post_residual < 15 {
            score += 40.0 * (1.0 - post / 15.0); // unusable sliver
        } else {
            score += 4.0; // any leftover is a mild waste
        }
    } else {
        score -= 25.0; // perfect fill is excellent
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / cap;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make the empty bin attractive only when the item is
    // large relative to capacity or no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 18.0; // base cost of opening a new bin
        if fill_ratio > 0.6 {
            score -= 22.0; // large items deserve fresh bins
        }
        if post_residual > 0 && post_residual < 15 {
            score += 30.0; // never open a bin for a sliver-leaving fit
        }
    }

    // Lookahead: if the next item would fit exactly in the resulting residual,
    // reward this placement; if it would be blocked, penalize slightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 3.0;
            if (post_residual as f64 - nxt).abs() < 1e-9 {
                score -= 10.0;
            }
        } else if post_residual > 0 {
            score += 2.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step chain: bin will be exactly refilled
        } else if post_residual >= next_item_size {
            // reward tight fits that still allow the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.3;
        } else {
            // next item cannot follow: penalize proportionally to wasted chain potential
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Penalize large dead space relative to mean residual (fragmentation risk).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.25;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item is huge
    // relative to residual (poor fit everywhere) — a fresh bin is worth it for
    // big items that would leave awkward leftovers elsewhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 1.15;
        if fill_ratio > 0.6 || (poor_fit_elsewhere && fitting_bins_count <= 1) {
            score -= 25.0; // opening fresh is good for big items
        } else {
            score += 30.0; // otherwise prefer existing bins
        }
    }

    // Slight preference for tighter fits as the stream progresses (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 14.0 / (1.0 + gap);
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            score += 0.08 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is expensive; make the empty bin
    // attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_spread = (mean_residual - post_residual as f64).abs();
        score += 30.0                      // base cost of a new bin
               - 22.0 * fit_pressure       // no open bin fits => new bin is fine
               - 6.0 * progress            // late in stream, consolidation matters less
               - 0.5 * poor_spread.min(20.0);
    } else {
        // Slight preference for filling already-open bins, more so when many are open.
        score += 0.02 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean (balance fragmentation).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled by a smooth non-linear progress coupling.
    // Later in the stream, residual waste matters more -> amplify polynomial terms.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Quadratic/cubic non-linear penalty on normalized residual, modulated by progress.
    let poly = norm_pr * norm_pr * (2.0 - 1.5 * progress) - norm_pr.powi(3) * (1.0 + progress);
    score += 10.0 * poly;

    // Coupling with mean residual: bins far from mean residual get smoothed penalty.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Reward bins that leave room for the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        // Perfect fit for next item -> big reward; poor fit -> mild penalty.
        let fit_term = 1.0 - fit_gap / cap;
        score -= 12.0 * fit_term * fit_term * (1.0 - progress);
        // Penalize leaving a residual that is awkwardly small relative to typical items.
        if pr < 10.0 {
            score += 8.0 * (10.0 - pr) as f64;
        }
    }

    // Mild penalty for opening a new bin when many bins already fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space (dead-space classes) ---
    // Residuals in 1..=10 are nearly unusable (min item size is 1, but in
    // practice small leftovers waste capacity). Penalize them heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }
    // Modulo-10 harmonic class: leftovers divisible by 10 are "clean" classes.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 4.0;
    }
    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Integer-division threshold: classify the fill ratio of the bin.
    let fill_class = (bin_capacity - post_residual) / (bin_capacity / 4); // 0..=4 quarters
    score -= fill_class as f64 * 2.0; // favor fuller bins

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The leftover can host the next item: reward this bin.
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 10.0; // near-perfect chain placement
            } else {
                score -= 3.0;
            }
            // Harmonic bonus if leftover class matches next item class
            if (post_residual % 10) == (next_item_size % 10) {
                score -= 2.0;
            }
        } else if post_residual > 0 {
            // Leftover becomes dead space after next item arrives
            score += 5.0;
        }
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only bin that fits: strongly prefer it over new bin.
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: post_residual here = capacity - item_size.
        // Penalize so a new bin only wins when open bins have terrible fits.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + 8.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
        // If nothing else fits, the last-chance subtraction above won't apply
        // to open bins either; make new bin acceptable but not preferred
        // when open bins have decent fits (post_residual small there).
    }

    // Slight pull toward the mean residual: keep bin residuals balanced.
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // fit the minimum item size (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bonus: using the only bin that fits avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; opening new bins is discouraged.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 2.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow.
        score += 20.0 + pressure;
    } else {
        score -= pressure * 0.3;
    }

    // Slight preference for bins with below-average residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        score += 0.6 * diff;
        if post_residual as u32 == next_item_size {
            score -= 45.0;
        }
        // penalize leaving residual too small for next item (dead space)
        if (post_residual as u32) < next_item_size {
            score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: prefer leaving
    // residuals near the mean (balanced bins), penalize outliers.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when
    // open bins fit poorly, but reward it early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 14.0 * progress;
    }

    // Prefer using already-open bins when many are open
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small leftover space.
    let pr = post_residual as f64;
    score -= 40.0 * ((1.0 - pr / bin_capacity as f64).powi(3));

    // Penalize unusable dead space: leftover smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item fills the remaining space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * fill;
        } else {
            // Next item cannot follow into this bin: mild penalty scaled by wasted potential.
            let waste = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 12.0 * waste;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless current fit is bad
    // or few bins are open (early stream, exploration phase).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = (post_residual as f64) > (bin_capacity as f64 - item_size as f64) * 0.0 + 55.0;
        if bad_fit && open_bins_count > 0 && progress > 0.05 {
            score -= 25.0; // prefer fresh bin over fragmenting an open one
        } else {
            score += 70.0; // otherwise strongly prefer reusing open bins
        }
    }

    // Global-state coupling: when mean residual is high, prefer bins that reduce dispersion
    // (bring their residual toward the mean) to keep a balanced pool.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Slight penalty per open bin to encourage consolidation over sprawl.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothly warped by stream progress
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Non-linear coupling: penalize large residuals early, reward tight fits late
    score += 20.0 * norm_pr * norm_pr * (1.0 - progress);

    // Fit quality: reward when post_residual matches the next item smoothly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 15.0 * (-20.0 * diff * diff).exp() * (0.5 + 0.5 * progress);
        // Penalize post-residual that is unusable (too small for next item)
        if pr < next_item_size as f64 {
            score += 10.0 * (1.0 - pr / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter fits
        score += 3.0 * (fitting_bins_count as f64).ln() * norm_pr;
    }

    // Deviation from mean residual: prefer bins that keep residuals balanced
    score += 2.0 * (pr - mean_residual).abs() / cap;

    // Prefer filling bins when many bins are open (consolidation pressure)
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0.0 .. 1.0

    // Dead-space penalty: residuals that no future item (min size 1) can
    // efficiently reuse. Classify via integer division thresholds.
    if post_residual == 0 {
        score -= 50.0; // perfect fit: strongly favored
    } else if post_residual <= 5 {
        score -= 20.0; // near-perfect
    } else if post_residual <= 15 {
        score -= 8.0;
    } else if post_residual <= 30 {
        score += 3.0;
    } else if post_residual <= 50 {
        score += 8.0;
    } else {
        score += 15.0; // large residual wasted on a small item
    }

    // Modulo arithmetic on capacity: residuals in "harmonic" slots
    // (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else if pr % 2 == 0 {
        score -= 1.0;
    } else {
        score += 2.0;
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 + 4.0 * (1.0 - slack / cap); // tight-but-fitting is great
        } else {
            score += 6.0; // next item won't fit here
        }
        // Harmonic pairing: post_residual exactly next_item_size or a
        // multiple-threshold companion.
        if post_residual == next_item_size {
            score -= 10.0;
        }
        if next_item_size <= post_residual && post_residual <= next_item_size * 2 {
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing residuals
    // are all poor fits for the item (relative waste measure).
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        score = waste * 1.2 + 10.0;
        // If many bins already open and mean residual is small, opening is fine.
        if mean_residual < item_size as f64 * 0.6 {
            score -= 15.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Slight preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 / cap) * 2.0;

    // Mild tie-breaker toward bins below mean residual (consolidation).
    score += (post_residual as f64 - mean_residual).clamp(-20.0, 20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidation when many bins open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would exactly fill post-residual, extra reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins would leave dead space
    // or no open bin is a good fit.
    if bin_residual == bin_capacity {
        let dead_space_if_forced = if post_residual < 10 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 * 0.5
            + open_bins_count as f64 * 2.0
            - dead_space_if_forced * 30.0
            + (item_size as f64 / bin_capacity as f64) * 10.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * frac * frac; // superlinear penalty on wasted space

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64); // good follow-up fit
        } else {
            // next item won't fit here; penalize leaving medium dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.25 * dead; // unusable-for-next dead space penalty
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 3.0 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // penalize opening a new bin mildly; aggressive lookahead may override
        score += 8.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // fresh bin can chain the next item
        }
    }

    // Slight progression adaptation: later in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that nothing (not even the smallest item) can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // bonus if residual after both placements is tight
            let double_res = post_residual - next_item_size;
            if double_res < 10 { score -= 8.0; }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 0.5;
    score += pressure * (post_residual as f64) * 0.05 * (1.0 - progress * 0.5);

    // Mean residual coupling: if this bin is far from mean residual, mild penalty
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // New-bin candidate logic: only attractive when item is huge relative to mean
    // residual of open bins (i.e., existing bins are too fragmented)
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (bin_capacity as f64);
        let big_item = (item_size as f64) / (bin_capacity as f64);
        // penalize opening new bin generally, discount when open bins are fragmented
        score += 18.0 - 15.0 * fragmentation * fragmentation + 5.0 * big_item;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // fresh bin can host pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: waste after placement, softly penalized with progress
    let mut score = x * (1.0 + 0.8 * progress);

    // Non-linear polynomial coupling: dead-space blowup for small residuals
    score += (1.0 - x).powi(4) * x * 2.0;
    score += x * x * (0.5 + 1.5 * progress * (1.0 - progress) * 4.0);

    // Lookahead: reward if next item fits snugly in post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 1.5 * snug * (1.0 + progress);
    } else if next_item_size > post_residual {
        score += 0.6 * progress;
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Mildly prefer bins below mean residual (keep large holes open)
    score += 0.3 * (x - mean_residual / cap);

    // New-bin candidate: penalize slightly, but relax as residuals shrink
    if bin_residual == bin_capacity {
        score += 1.2 - 0.6 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 10 classes.
    let class = (post_residual * 10) / bin_capacity.max(1);
    let class_center = (class as f64 + 0.5) * (cap / 10.0);

    // Reward leftover space that sits close to a harmonic class center
    // (predictable, reusable residue), penalize odd in-between leftovers.
    let deviation = (post_residual as f64 - class_center).abs();
    score += 0.8 * deviation;

    // Dead-space penalty: residuals that cannot host any plausible item
    // (very small leftovers) are heavily penalized, but exact-zero is perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Modulo arithmetic on next_item_size: does the next item divide the
    // leftover cleanly? If next_item_size > 0 and post_residual % next == 0
    // with next <= post_residual, this bin is a perfect two-step chain.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next_item_size <= post_residual {
            if post_residual % next_item_size == 0 {
                score -= 12.0;
            } else {
                // fractional waste if next item goes here
                let waste = post_residual % next_item_size;
                score += waste as f64 * 0.5;
            }
            // reward if next item fits tightly
            score -= (next / cap) * 6.0;
        } else {
            // next item cannot use this bin: leftover is final -> penalize
            score += 4.0 + (next / cap) * 3.0;
        }
    }

    // Integer-division threshold on item_size: big items (half capacity or
    // more) should prefer tight bins, small items tolerate loose fits.
    if item_size * 2 >= bin_capacity {
        score -= 5.0 * (1.0 - (post_residual as f64) / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate: only attractive when residuals are fragmented or
    // the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = item_size as f64 / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap as f64 * 0.35
            + 10.0 * pressure
            + 6.0 * progress
            - (open_bins_count as f64) * 0.3;
        if fragmentation > cap * 0.4 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can never be filled by
    // typical items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // hard-to-fill dead zone
    } else if post_residual >= 20 && post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 15.0 + 6.0 * open_bins_count as f64;
        // Late in the stream, opening a fresh bin is more acceptable
        // (future items can still fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If the best alternative leaves a large dead gap, new bin wins.
        if post_residual as f64 > 0.0 && item_size >= 50 {
            score -= 5.0;
        }
    } else {
        // Placing into an existing bin slightly reduces open-bin sprawl.
        score -= 2.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual cannot host the next item: mild penalty scaled
        // by wasted capacity.
        score += (post_residual as f64) * 0.3;
    }

    // Bias toward bins with residuals near the mean (keeps bin states uniform).
    score += ((bin_residual as f64 - mean_residual) / (bin_capacity as f64)).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // reward small |post_residual - next_item_size|
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // exact match bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // penalize leaving dead space that next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // last item: just minimize waste
        score += 5.0;
    }

    // Last chance: only bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (dead space below min item size 1..10 range)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer bins with residual below mean residual (tighter packing first)
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Mild preference to fill existing bins rather than open new ones as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses, unless it enables perfect lookahead fit
        let mut penalty = 10.0 + 20.0 * progress;
        if next_item_size > 0 && post_residual == next_item_size {
            penalty = 0.0;
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.8 {
        score -= 25.0 * (fit_ratio - 0.8);
    } else if fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }

    // Penalize large dead space, especially small residuals that become unusable
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; slight penalty for wasting perfect fit potential
            score += 3.0;
        }
    }

    // Prefer filling bins with large residuals when mean residual is high (spread waste)
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Early in stream: mildly encourage consolidation into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 3 {
        score -= 2.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let open_pressure = if fitting_bins_count == 0 { 0.0 } else { 8.0 };
        score = 55.0 + open_pressure - 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, mildly discounted by stream progress (tighter packing later)
    let mut score = pr * (1.0 - 0.35 * progress);

    // Non-linear penalty for unusable dead space: residual too small for typical items
    let dead = (1.0 - norm_pr).powi(6);
    score += 40.0 * dead * norm_pr.powi(2) * (1.0 + progress);

    // Smooth polynomial coupling of item size with progress: prefer big items early in tight bins
    score -= 12.0 * norm_item * (1.0 - norm_item) * (1.0 + progress * progress);

    // Lookahead: reward if next item fits the post-residual (smooth wedge)
    if next_item_size > 0 {
        let fit_next = (norm_pr - norm_next).max(0.0);
        score -= 15.0 * fit_next * (1.0 - (norm_pr - norm_next).abs().min(1.0));
    }

    // Last-chance bonus: smooth reward when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64).powi(2);
    score -= 10.0 * scarcity * (1.0 - norm_item);

    // Mean-residual coupling: penalize bins far from mean residual (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless residual is large
    if (bin_residual as f64 - cap).abs() < 1e-9 {
        score += 25.0 * (1.0 - progress) + 10.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space thresholds.
    // Small leftovers (<10) are nearly dead space; penalize lightly.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    // Class: leftover in [10,20) can host small items — mild penalty.
    else if post_residual < 20 {
        score += 3.0;
    }
    // Class: leftover >= 40 is flexible — reward.
    else if post_residual >= 40 {
        score -= 4.0;
    }

    // Integer division classes: post_residual / 10 quantization.
    let leftover_class = post_residual / 10;
    score += (leftover_class % 3) as f64 * 1.5;

    // Lookahead coupling: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        // Even better: next item fills leftover almost exactly.
        let gap = post_residual.saturating_sub(next_item_size);
        if gap < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item would need another bin; prefer leaving large usable leftover here.
        if post_residual >= 30 {
            score -= 2.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 60.0;
        // If the item is large relative to capacity, new bin is more attractive.
        score -= (item_size as f64) * 0.3;
        // Few fitting bins -> opening new bin less wasteful.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Prefer fuller bins: residual below mean is good.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Progression: late in stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A post_residual that is too small for the smallest conceivable item (1)
    // is already dead; gaps below the typical minimum item size are near-dead.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0; // near-dead gap penalty
    } else {
        // Mild superadditive penalty on leftover space to prefer tight fits.
        let pr = post_residual as f64;
        score += 0.02 * pr * pr;
    }

    // Bonus if the leftover gap can exactly host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // gap still usable for the next item
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading into a new
    // empty bin; consolidation gets favored when open_bins_count is high.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins count.
        score += 30.0 + (open_bins_count as f64).sqrt() * 8.0;
        // Late in the stream, opening new bins is even less attractive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    } else {
        // Reward using existing bins more strongly when many are open.
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // leaving larger-residual bins flexible for future items.
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
