    // Near-match bonus: quadratic penalty on distance to next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let d = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + d * d * 0.05);
    }

    // Dead space penalty: small residuals (<10, min item size) are unusable.
    if post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
