        }
        // Early in the stream, keep bins consolidated.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * (1.0 - progress);
        // If open bins are already quite full on average, a new bin is reasonable.
        if mean_residual < (item_size as f64) {
            score -= 12.0;
        }
    }

    // Slight preference for tighter bins relative to the mean residual.
    score += 0.1 * ((post_residual as f64) - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 {
        // Usable residual is good, but diminishing.
        score -= 4.0 * (post_residual as f64).ln();
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0; // chains a perfect fit next step
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    let open_pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).sqrt());
    score += 6.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Global mean residual coupling: if mean residual is high, prefer bins
    // that reduce dispersion (post_residual near mean).
    let disp = (post_residual as f64 - mean_residual).abs();
    score += 2.5 * disp / bin_capacity as f64;

    // Time horizon: early in stream, be conservative (favor tight fits more);
    // late in stream, just close bins out.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - t);

    // New-bin candidate handling: an empty bin is a fallback. Prefer it only
    // when no open bin offers a decent fit (post_residual large relative to
    // item and few fitting bins). Give it a mild penalty so real bins win
    // unless they waste a lot of space.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If the current item is large relative to capacity, opening fresh is cheaper.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins are open and mean residual is fragmented, opening fresh helps.
        if mean_residual < item_size as f64 {
            score -= 6.0;
        }
    }

    // Small tie-breaker toward bins with less residual overall (denser bins).
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post / cap; // normalized post residual
    let fit_ratio = if open_bins_count > 0 { fitting_bins_count as f64 / open_bins_count as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post residual with stream progress
    let mut score = post * (1.0 + 0.9 * progress * pr * pr) + 12.0 * pr * pr * (1.0 + progress);

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= 20.0 * (1.0 - pr) * (1.0 - pr) * (0.4 + 0.6 * progress);

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins with residual far below mean (fragmented dead space), smoothly
    score += 0.08 * (mean_residual - post).abs() * (1.0 + progress);

    // Lookahead: reward leaving space for the next item, penalize near-misses smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 6.0 * (gap / cap) * (1.0 - (gap / cap)) * (1.0 + progress);
        } else {
            score += 3.0 * (-gap / cap) * (1.0 - pr);
        }
    }

    // Mild pressure against opening new bins when many are open
    score += 0.02 * open_bins_count as f64 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

