    // Harmonic classes: leftover in (0,10] is dead space (penalize heavily),
    // leftover in (10,33] can host small items, (33,50] medium, (50,100] flexible.
    if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score += 30.0; // dead space: unusable for items >= 10
    } else if post_residual <= 33 {
        score += 8.0;
    } else if post_residual <= 50 {
        score -= 4.0;
    } else {
        score -= 10.0; // half-full or better: very flexible
    }

    // Modulo arithmetic on post_residual vs common item-size classes.
    // Items arrive in 1..=100; residue classes mod 10 capture common alignments.
    let pr_mod = post_residual % 10;
    if pr_mod == 0 && post_residual > 0 {
        score -= 6.0; // divisible-by-10 leftover aligns with typical sizes
    } else if pr_mod < 3 {
        score += 5.0; // awkward sliver just above a multiple of 10
    }

    // Lookahead coupling: reward leaving space that fits the next item exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 20.0; // sets up a perfect fit for the next item
            } else if slack <= 10 {
                score -= 10.0;
            } else {
                score -= (slack as f64).sqrt();
            }
        } else {
            score += 12.0; // next item won't fit here; this bin becomes dead
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if mean residual across open bins is small, a new bin is fine.
        score -= (mean_residual / cap) * 20.0;
    }

    // Prefer tight residual bins generally (best-fit flavor) with harmonic weighting.
    score += (cap / (pr + 1.0)) * 0.5;

    // Late in the stream, consolidate: favor filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
