        }
    }

    // Tight-fit bonus relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Late-stream consolidation: prefer filling bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);

