    // Coupling with mean residual: bins with residual far below the mean
    // are "wasted" bins; placing here balances residual distribution.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Encourage filling bins that are already quite full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 100.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to capacity
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize if post_residual can't hold the next item (dead space)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0; // bin remains usable for lookahead item
        } else {
            score += 0.05 * (post_residual as f64); // dead-space penalty
        }
        // Bonus if post residual exactly matches next item
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: make opening a new bin attractive only when
    // existing fits are poor (large post_residual) or many bins already fit.
    if bin_residual == bin_capacity {
        // Base new-bin cost; scale with stream progression (more conservative late)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // slight attraction if next item is large
            score -= 0.1 * (next_item_size as f64);
        }
    }

    // Prefer bins with residual close to item (best-fit flavor) when many bins fit
    if fitting_bins_count > 1 {
        score += 0.02 * (bin_residual as f64 - item_size as f64).abs();
    }

    // Global state coupling: if mean residual is low, conserve tight fits
    if (bin_residual as f64) > mean_residual {
        score += 1.5;
    } else {
        score -= 0.5;
    }

    // Mild penalty for wasting very large residual bins on small items
    if item_size < bin_residual / 3 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / c; // normalized post residual in [0,1]

    // Smooth polynomial coupling: base term on post residual, modulated by progress
    let mut score = pr * (1.0 + 0.8 * progress);

    // Quadratic penalty for medium dead space, smooth in progress
    let dead = norm_pr * (1.0 - norm_pr); // peaks at 0.5 residual (unusable-ish zone)
    score += 40.0 * dead * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 15.0 * (0.3 + progress);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = if ns <= pr { 1.0 - (pr - ns) / c } else { 0.0 };
        score -= 12.0 * fit_next * (0.5 + 0.5 * progress);
        // Penalize post residual that is just barely below next item size (near-miss dead space)
        if ns > pr {
            score += 10.0 * (1.0 - (ns - pr) / c) * (1.0 + progress);
        }
    }

    // Mild dispersion penalty: avoid bins far from mean residual (keeps bin pool homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs() / c;
    score += 8.0 * dev * dev;

    // New-bin candidate: make empty bin attractive only when current fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = if pr >= 0.0 && norm_pr > 0.6 { 1.0 } else { norm_pr / 0.6 };
        score += 25.0 * (1.0 - poor_fit) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into residue classes
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left

    // Penalize leftovers that fall into "dead" harmonic classes (hard to fill: 1..=9)
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * 25.0;

    // Reward exact fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo-class logic on post_residual: classes of 10 (decades)
    let decade = post_residual / 10;
    score += (decade as f64) * 1.5;

    // Odd/even harmonic coupling: small odd residuals are less usable
    if post_residual % 2 == 1 && post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward partial compatibility scaled by how much slack remains after next item
            let next_post = post_residual - next_item_size;
            score -= 10.0 * (1.0 - (next_post as f64) / cap);
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 6.0 * frac;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should win only when current bins fit poorly
    if bin_residual == bin_capacity {
        // neutral-ish base; add mild pressure so tight fits in open bins win
        score += 8.0 + mean_residual * 0.05;
        if post_residual == bin_capacity {
            // truly empty candidate for this item
            score += 5.0;
        }
    }

    // Progress-aware tightening: late in the stream, prefer compacting residual space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * (5.0 + 10.0 * progress);

    // Coupling with mean residual: bins far below mean residual are "wasted" targets
    score += (mean_residual - (bin_residual as f64)).max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // New-bin candidate: baseline score = residual (100). Encourage reuse unless fit is poor.
    let is_new_bin = bin_residual == bin_capacity;

    // Core: reward tight packing. post_residual == 0 is perfect.
    let pr = post_residual as f64;
    score += pr;

    // Strict dead-space avoidance: small unusable gaps (< min item size ~10) are worst.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // risky gap, only large items could use it
    }

    // Reward near-perfect fills extra.
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer reusing existing bins over new ones.
    let pressure = open_bins_count as f64;
    if is_new_bin {
        score += pressure * 2.5;
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item cannot use this bin's leftover: penalize leftover more
            score += pr * 0.3;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good squeeze target.
    let residual = bin_residual as f64;
    score += (mean_residual - residual) * 0.3;

    // Late in stream: consolidate, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += progress * 30.0;
    }

    // Prefer filling emptier bins when many options exist.
    if !is_new_bin {
        score += (bin_capacity as f64 - residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.13;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual penalizes wasted space superlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 12.0 + 0.25 * nx;
        } else {
            // Dead space relative to next item: penalize unusable remainder.
            let waste = nx - post_residual as f64;
            score += 0.35 * waste;
        }
    } else {
        // Last item: prioritize perfect closure.
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty so crowded competition prefers the best-fit bin anyway.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: prefer filling bins when many are open (consolidation).
    let openness = open_bins_count as f64;
    score -= 0.6 * openness * (item_size as f64 / bin_capacity as f64);

    // Mean residual coupling: bins below mean residual are already tight; reward further.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.4 * (mean_residual - res);
    } else {
        score += 0.25 * (res - mean_residual);
    }

    // Time horizon: early on, be liberal about spreading (favor roomy bins);
    // late, minimize waste aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 0.15 * (post_residual as f64);
    score -= t * 0.5 * (post_residual as f64);

    // New-bin candidate: opening a new bin is only attractive when the item is large
    // relative to typical residuals or nothing fits well.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score += 25.0; // keep existing bins for the next item pairing
        }
        if big_item || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 10.0 + 0.3 * openness;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual

    // Base: minimize wasted space, with non-linear polynomial shaping.
    let mut score = post;

    // Non-linear polynomial coupling with stream progress:
    // early in the stream, tolerate larger residuals (favor spreading);
    // late in the stream, aggressively punish residual waste.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * post * (x * x);

    // Cubic term: heavily penalize large dead space as the stream advances.
    score += 40.0 * progress * x * x * x * cap;

    // Reward tight fits (small post_residual) with a smooth bonus.
    score -= (1.0 - x) * (1.0 - x) * item_size as f64;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if it cannot fit, penalize creating residual that blocks it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            let fit_gap = (post_residual as f64 - nxt) / cap;
            score -= 25.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
        } else {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Mean residual coupling: prefer bins whose residual differs from the mean
    // (keeps a portfolio of bin sizes), smoothly scaled.
    score += 0.1 * (post - mean_residual).abs();

    // Mild pressure against opening too many bins when a fit exists.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division thresholds
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let class = pr / 10; // decile class of leftover space

    // Reward tight fits: dead space below 10 is excellent
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr < 10 {
        score -= 60.0;
    }

    // Penalize mid-range leftovers that few future items can use
    // items are 1..=100, but small leftovers only fit tiny items
    let dead_penalty = match class {
        0 => 0.0,                       // 1..9: nearly full
        1 => 4.0,                       // 10..19
        2 => 10.0,                      // 20..29
        3 => 14.0,                      // 30..39
        4 => 12.0,                      // 40..49
        5 => 9.0,                       // 50..59
        _ => 0.0,                       // large residual is fine
    };
    score += dead_penalty;

    // Modulo arithmetic: leftover divisible by common item sizes is reusable
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0) {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        score -= 5.0 + (pr - next_item_size) as f64 * 0.1;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin; cheaper when stream is early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 25.0 * progress;
        // if mean residual across open bins is large, discourage new bin further
        score += mean_residual * 0.15;
    } else {
        // slight preference for fuller bins (best-fit bias)
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Many open bins: prefer consolidating into existing ones
    if open_bins_count > 4 {
        score += 3.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit a plausible future item
    // (anything below the minimum realistic item size band) are toxic.
    let min_item = 1u32;
    if post_residual < min_item.max(item_size.min(10)) {
        score += 50.0; // unusable sliver
    }
    // Penalize gaps that are too small for the lookahead item but nonzero
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.25 * (post_residual as f64);
    }

    // Reward perfect or near-perfect packing strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward tight fit relative to bin capacity (small waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when bins are few (early) or many bins
        // already exist with usable mean residual.
        score += 30.0 + 10.0 * (1.0 - progress) + 2.0 * pressure;
        if mean_residual > item_size as f64 {
            score += 5.0; // existing bins have room; don't open new
        }
    } else {
        // Slight preference for filling bins with larger residuals when pressure high.
        score -= 0.05 * pressure * (bin_residual as f64 - post_residual as f64);
    }

    // Coupling: prefer bins whose residual is close to item size (snug fit).
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * snug;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: if the next item exactly fills the post-residual, strongly favor
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits here too, mild bonus proportional to how well it fills
            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - fill_after_next / bin_capacity as f64);
        } else {
            // next item cannot use the leftover; penalize dead space relative to next size
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(post_residual as f64);
        }
    }

    // Relative to mean residual: bins tighter than average are better targets
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when other bins fit fine
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0 + mean_residual * 0.5;
    }

    // Slight preference for tight fits late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a super-linear bonus.
    let fit_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // tiny unusable sliver
        } else if dead < item_size as f64 {
            score += 8.0; // smaller than current item — hard to reuse
        }
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot follow into this bin; mild penalty scaled by how close it is.
        let gap = (next_item_size as f64 - post_residual as f64).min(50.0);
        score += 0.1 * gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer bins with smaller residuals (best-fit pressure).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Time horizon: early in the stream, be more conservative about fragmenting bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    // Many open bins: discourage spreading; reward consolidating into fuller bins.
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Global residual context: if mean residual is large, prefer bins below the mean (fuller).
    score += 0.08 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early with expected many future items.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let item_heavy = item_size as f64 / bin_capacity as f64;
        score = 15.0 + 0.5 * item_size as f64
            - desperation * 60.0
            - progress * 10.0
            + (1.0 - item_heavy) * 5.0;
        // If the next item is small, a fresh bin keeps room for it.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with non-linear tightening as stream progresses
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear penalty for small unusable post residual (dead space)
    score += 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_pr * norm_pr;

    // Smooth interaction: prefer tight fits more strongly later in the stream
    score -= 8.0 * progress * norm_pr * (1.0 - norm_pr);

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 6.0 * (gap / cap) * (gap / cap) - 4.0 * (1.0 - (gap / cap).min(1.0));
    }

    // Penalize spreading across many open bins mildly, scaled by deviation from mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make empty bins moderately attractive only for large items / early stream
    if bin_residual == bin_capacity {
        score -= 3.0 * (1.0 - progress) + 2.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common
    // item sizes (10, 20, 25, 50) are far more reusable than odd remnants.
    let pr = post_residual;
    let mut reusability = 0.0;
    if pr % 50 == 0 { reusability += 6.0; }
    if pr % 25 == 0 { reusability += 3.0; }
    if pr % 20 == 0 { reusability += 2.0; }
    if pr % 10 == 0 { reusability += 1.5; }
    score -= reusability;

    // Perfect fit is golden.
    if pr == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: tiny unusable leftovers (below min item size 1..10 band)
    let prf = pr as f64;
    if pr > 0 && pr < 10 {
        score += 12.0; // dead space, nothing can ever go in
    } else if pr < 20 {
        score += 4.0;  // only very small items fit
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual
    // (or into a harmonic class of it), reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item fits: bonus scaled by how snugly
            let snug = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 8.0 * snug;
        } else {
            // next item cannot fit here: mild penalty if we leave a big gap
            score += 2.0 * (prf / cap);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing bins are nearly full or the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize new bins mildly, more early when open bins are roomy
        score += 8.0 + 6.0 * (1.0 - progress) - 0.3 * mean_residual.max(0.0).min(20.0);
        // large items with no good home benefit from a fresh bin
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // reward tighter fits among open bins
        score -= 3.0 * (1.0 - prf / cap);
    }

    // Prefer bins whose residual is below the mean (consolidating waste)
    if prf < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (< 10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling: dead space severity scales with how full the bin already is.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: discourage spreading across many bins, but allow
    // opening a new bin when the fit is poor in all existing bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when the item leaves a
    // large, reusable residual; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity / 2 {
            score -= 20.0; // big item deserves a fresh bin
        } else {
            score += 30.0; // small item should go into an existing bin
        }
        // Early in the stream, opening bins is cheap; late, it is costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Mean-residual coupling: when open bins are already loose, prefer using them.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain fits
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits perfectly after this placement
            let chain_waste = post_residual - next_item_size;
            score -= 12.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
            if chain_waste == 0 {
                score -= 25.0; // perfect 2-chain
            }
        } else {
            // Next item won't fit here; penalize leaving awkward residue
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize dead space relative to mean residual of open bins
    let waste = post_residual as f64 - mean_residual;
    if waste > 0.0 {
        score += waste * 0.15;
    } else {
        score += waste * 0.05; // mild reward for keeping bin tighter than average
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual - post_residual) as f64 * 0.1;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 30.0 } else if next_item_size > 0 && post_residual >= next_item_size { -40.0 } else { 10.0 };
        score += desperation + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize large dead space, especially small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty if we waste the residual.
        score += 6.0;
    }

    // Time horizon: early in stream, prefer opening new bins less (pack tighter);
    // late in stream, favor filling existing bins to close them out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Global state: many open bins -> discourage opening another.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But early on with few bins, a fresh bin is fine.
        score -= (1.0 - progress) * 10.0;
    }

    // Mean residual coupling: if this bin is below-mean residual (fragmented), penalize.
    let dev = mean_residual - bin_residual as f64;
    score += 0.2 * dev;

    // Prefer bins whose fill ratio is already high (close them out).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Mild preference for fewer open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits (small post_residual), with a quadratic
    // non-linear coupling to stream progress: late in the stream we
    // punish leftover space more aggressively.
    let mut score = post_norm * (1.0 + 2.0 * progress * progress);

    // Dead-space penalty: residuals too small to host a typical item
    // are quadratic-penalized, modulated by progress.
    let dead_zone = 0.15f64;
    let dead = if post_norm < dead_zone { (dead_zone - post_norm).powi(2) } else { 0.0 };
    score += dead * (6.0 + 8.0 * progress);

    // Smooth reward for exact-ish fits (post_residual near zero) using
    // an exponential coupling.
    score -= (-post_norm * 12.0).exp() * (1.5 + 2.5 * progress);

    // Lookahead coupling: reward bins whose post_residual can host the
    // next item, penalize bins that would strand the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let nxt_norm = nxt / cap;
        if post >= next_item_size {
            // next item fits here: reward proportionally to tightness of that fit
            let second_fit = (post - nxt) / cap;
            score -= 1.2 * (-second_fit * 8.0).exp() * (0.5 + progress);
        } else {
            // next item won't fit here: mild penalty scaled by how close we were
            score += 0.8 * nxt_norm * (1.0 - (post / nxt).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly
    // reward using it (avoid opening a new bin), smoothly scaled by
    // how well the item actually fits.
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 2.0 + 3.0 * tightness * (1.0 + progress);
    }

    // Crowding term: many open bins -> prefer consolidating into
    // below-mean-residual bins (smooth interaction).
    let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += crowd * (mean_residual - post) / cap * 0.6;

    // New-bin candidate: an empty bin should be chosen only when the
    // item is large relative to capacity or all fits are poor; give it
    // a smooth handicap otherwise.
    if bin_residual == bin_capacity {
        let size_norm = item_size as f64 / cap;
        score += 2.5 * (1.0 - size_norm) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: classify post_residual by capacity fractions (C=100).
    // Classes: [0..10) excellent (near-perfect fill), [10..25) good,
    // [25..50) mediocre, [50..100] poor (half-empty bin).
    let class_penalty: f64 = if post_residual < 10 {
        -40.0
    } else if post_residual < 25 {
        -15.0
    } else if post_residual < 50 {
        5.0
    } else {
        25.0
    };
    score += class_penalty;

    // Integer-division harmonic band: post_residual / 10 gives 10 discrete
    // levels; reward low bands nonlinearly (quadratic in band index).
    let band = (post_residual / 10) as f64;
    score += band * band * 0.8;

    // Exact-fit bonus: post_residual in a "dead" harmonic class (small and
    // hard to reuse for items >= 10) gets extra reward.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0;
    }
    if post_residual == 0 {
        score -= 60.0; // perfect packing
    }

    // Lookahead: does the next item fit the post-residual harmonic class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can reuse this bin: strong reward, scaled by tightness.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 + 18.0 * tightness;
        } else {
            // Next item cannot fit: penalize, worse for larger leftover gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + gap * 0.15;
        }
        // Modulo-coupling: if next item would land in the excellent class
        // (next post-residual < 10), big reward.
        if next_item_size <= post_residual && (post_residual - next_item_size) < 10 {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.2 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // in the stream or when the item badly fragments any existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (post_residual as f64 / bin_capacity as f64) * 100.0;
        // New bin starts with residual 100 - item; penalize more as stream advances.
        score += 8.0 + 30.0 * progress + fragmentation * 0.2;
        // But if no open bin fits well (this call is compared against bad fits),
        // allow new bin when item is large (leaves small residual).
        if item_size >= 70 {
            score -= 35.0;
        }
    }

    // Mild preference for filling fuller bins among ties (mean residual context).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Scale-aware tiebreak: exact fraction classes of capacity.
    let frac = (post_residual as f64) / (bin_capacity as f64);
    score += frac * frac * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can never host the smallest
    // possible item (1..10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the lookahead item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Perfect fit is the gold standard.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing ones; few open bins -> tolerate new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.5);
    score += 0.15 * pressure * (0.5 + progress);

    // New-bin candidate (empty bin): make it attractive only when the
    // item is large or the current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.7 * bin_capacity as f64;
        let bad_gap = post_residual > 0 && post_residual < 10;
        if big_item || bad_gap || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 45.0;
        }
    }

    // Mild bonus for leaving room that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover space exactly matches the next item (2-step lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // perfect 2-step chain: both items packed with zero waste
        } else if post_residual >= next_item_size {
            // leftover after next placement; penalize large unusable remainder
            let rem_after_next = post_residual - next_item_size;
            score -= 50.0 - (rem_after_next as f64).min(50.0);
        } else {
            // next item won't fit here: penalize proportionally to the shortfall
            let shortfall = next_item_size - post_residual;
            score += 10.0 + shortfall as f64;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // placing into an already-low-residual bin (tight fit) is good.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny dead space that no item (min size 1..100 range) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Prefer filling bins tightly as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    // Mild penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (waste minimization is the core objective).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize residual space that becomes "dead": nothing in typical range (1..=100)
    // can use tiny leftovers, but mid-range residuals are reusable.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 1.5;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // reward this bin (chain-friendly placement).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack = post_residual as f64 - nxt;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual cannot host next item: mild penalty scaled by wasted potential.
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: when many bins are open with high mean residual, prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64 * (0.5 + progress);
        score -= 0.10 * mean_residual.min(50.0);
    }

    // New-bin candidate handling: make empty bins moderately attractive only when
    // existing fits are poor (large post_residual elsewhere) or few bins fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases late in the stream.
        let mut new_bin_score = 45.0 - 10.0 * progress;
        // If the item is huge relative to capacity, a fresh bin is often wise.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_score -= 15.0;
        }
        // If the next item is also large, opening fresh space helps.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_score -= 10.0;
        }
        // If many bins already fit the item, discourage opening a new one.
        new_bin_score += 4.0 * fitting_bins_count as f64;
        // If open bins have lots of residual room, discourage new bins.
        new_bin_score += 0.2 * mean_residual.min(60.0);
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear base: penalize large dead space quadratically
    let mut score = pr as f64;
    score += 8.0 * x * x * cap;
    score -= 6.0 * x * x * x * cap;

    // Coupling with stream progress: later in stream, value tight fits more
    let prog_term = (1.0 - progress) * (1.0 - progress);
    score += 20.0 * x * prog_term;

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 10.0 * (1.0 - (fit_ratio - 0.5) * (fit_ratio - 0.5) * 4.0);
    } else if next_item_size > 0 {
        score += 5.0; // next item can't use this space
    }

    // Last-chance bonus: only bin that fits should be strongly favored
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize spreading when many bins open with high mean residual
    score += 0.5 * (mean_residual - pr) * (mean_residual - pr) / cap;

    // New-bin candidate: prefer it only when it yields large usable space early
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress) * x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10.
    // Leftovers that are "harmonically compatible" with common small item sizes
    // (multiples of 10) are less wasteful than odd remainders.
    let pr = post_residual;
    let harmonic_class = pr % 10;
    // Penalize awkward remainders (1..9 not divisible into deciles)
    if harmonic_class != 0 && pr > 0 {
        score += 3.0;
    }
    // Perfect zero leftover is ideal
    if pr == 0 {
        score -= 50.0;
    }
    // Small dead space (< 10) is nearly useless since min item is 1..100 range
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Integer division thresholds: bins whose post_residual falls into a
    // "usable band" (>= next item) are rewarded.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 5.0;
            // Extra reward if it exactly accommodates the next item
            if pr == next_item_size {
                score -= 10.0;
            }
        } else {
            score += 4.0;
        }
        // Harmonic pairing: post_residual and next_item_size sharing a class mod 10
        if next_item_size > 0 && pr % 10 == next_item_size % 10 && pr >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are bad,
    // but reward it when open bins are crowded (many bins, high mean residual usage).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score = 25.0 - 10.0 * crowdedness - 5.0 * progress;
        // If current item is large relative to capacity, new bin is natural
        if item_size * 2 > bin_capacity {
            score -= 6.0;
        }
    }

    // Capacity-fraction coupling: reward placements that leave residuals near
    // friendly fractions of capacity (25, 50, 75).
    let frac_bonus = |x: u32| -> f64 {
        let d25 = (x as i32 - 25).abs();
        let d50 = (x as i32 - 50).abs();
        let d75 = (x as i32 - 75).abs();
        -(d25.min(d50).min(d75)) as f64 * 0.05
    };
    score += frac_bonus(pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: very low post_residual is excellent.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Dead-space penalty: small but nonzero gaps are unusable for future
    // items (min item size is 1, but typical items are larger). Penalize
    // gaps below the plausible next-item threshold nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item leaves a good residual for the lookahead item, or
    // when open-bin pressure is low.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its post_residual is large, so it
        // naturally scores high; add open-bin pressure so that with many
        // open bins we prefer filling existing ones.
        score += 40.0 + 5.0 * open_bins_count as f64;
        // If lookahead fits nicely in the new bin's post_residual, reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 180.0;
            } else if slack <= 30 {
                score -= 60.0;
            }
        }
    } else {
        // Open bin: reward if lookahead item fits the post_residual well.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 90.0;
            } else if slack <= 30 {
                score -= 25.0;
            }
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Lookahead won't fit here; penalize mildly to prefer bins
            // that chain well, unless it's the last chance.
            score += 20.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (i.e., fuller bins) to keep many high-residual bins available.
    let residual_diff = mean_residual - bin_residual as f64;
    score += 0.3 * residual_diff;

    // Open-bins pressure: with many open bins, favor tighter packing.
    score += 0.2 * open_bins_count as f64;

    // Stream progression: late in the stream, be more aggressive about
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    } else {
        score += 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Post residual can still hold the next item: strong reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 20.0 + 40.0 * tightness;
    }
    // Post residual falls into awkward gap: cannot fit next item but large dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Reward bins tighter than average residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize opening a new bin when plenty of open bins fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 15.0 + 5.0 * open_bins_count as f64;
    }

    // Early in stream: prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness: reward small post residuals non-linearly
        let tight = (post_residual as f64) / (bin_capacity as f64);
        score += tight * tight * 60.0;
    }

    // Lookahead coupling: penalize leaving residual that next item could use poorly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // next item could fit here: reward residual close to next size
            let gap = (pr - nxt).abs();
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space relative to next item
            score += (nxt - pr).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded/fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { (mean_residual / bin_capacity as f64) } else { 1.0 };
        // penalize opening new bins normally
        score += 150.0;
        // but if existing bins are fragmented (high mean residual = poor fits) and item is small, allow
        if fragmentation > 0.5 && (item_size as f64) < 0.35 * bin_capacity as f64 {
            score -= 120.0 * fragmentation * (0.5 + progress);
        }
    }

    // Prefer filling more-fragmented bins when many bins are open
    if bin_residual < bin_capacity {
        let res_gap = (post_residual as f64 - mean_residual).abs();
        score += res_gap * 0.5;
        // mild load balancing: spread across many open bins
        score += open_bins_count as f64 * 0.3;
    }

    // Time horizon: later in stream, be greedier (minimize residual hard)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Penalize unusable slivers (< smallest plausible item ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = r / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = x * (1.0 - x) * (1.0 + progress * (x - 0.5));
    let mut score = r - 40.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - x;
    score -= progress * 30.0 * tightness * tightness;

    // Penalize dead space relative to mean residual across open bins
    score += 0.15 * (r - mean_residual).abs();

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: penalize leaving residual that cannot host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if r >= nx {
            score -= 8.0 * (1.0 - (nx / cap));
        } else {
            score += 6.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate penalty unless residual is genuinely unusable
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * x * (1.0 - progress);
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse residue classes
    // Small post_residual classes (near-perfect fit) are strongly rewarded.
    let pr = post_residual;
    let class_bonus = match pr {
        0 => 40.0,
        1..=5 => 25.0,
        6..=10 => 15.0,
        11..=20 => 8.0,
        21..=30 => 3.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: dead space in "unusable" bands gets penalized.
    // Residuals that no typical item (1..=100) can use well: tiny slivers or huge voids.
    if pr > 0 && pr < 10 {
        score += 6.0; // sliver, likely dead space
    }
    if pr > 50 {
        score += (pr as f64 - 50.0) * 0.5; // large void, but new-bin comparison matters
    }

    // Modulo arithmetic on capacity fractions: bins whose residual is a "nice" multiple
    // of common item sizes are more likely to be closed later.
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead: does the next item fit exactly / well in the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chained fit
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - slack * 0.2;
        } else {
            // next item won't fit here; slight penalty unless residual is tiny anyway
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make an empty bin moderately attractive so it wins
    // only when existing bins have bad fits (high post_residual / dead space).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream
        // and when many bins are open (consolidation pressure).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_cost = 55.0 - 15.0 * progress - (open_bins_count as f64).min(10.0) * 1.5;
        // Empty bin score = its raw residual minus cost; item will leave residual 100-size.
        score = (bin_capacity - item_size) as f64 - new_bin_cost + 8.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Mild consolidation: prefer bins tighter than the mean residual.
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Slight preference for fuller bins overall (post_residual already does this),
    // tie-break by item size ratio filling the bin.
    score -= (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: residuals below the minimum item size (1..10)
    // are worthless, residuals in 10..20 can only take tiny items.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) * 0.6;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (empty-bin candidate has bin_residual == bin_capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + (open_bins_count as f64) * 1.5;
    } else {
        // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Reward using bins whose residual is already small (consolidation).
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Mild time normalization to keep scales stable across stream length.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    // Slight penalty when this bin's residual deviates far above mean residual
    // (prefer bins closer to average fill to balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // perfect chain fit
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 30.0 - slack as f64; // tight chain fit
            } else {
                score += slack as f64 * 0.3; // wasteful leftover after chain
            }
        } else {
            // next item cannot fit here: post_residual is likely dead space
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Penalize residual far below mean residual (creating fragmented space).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // this item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // Cheaper to open a new bin early in the stream (more future items
        // can use its space).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 15.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 40.0;
        }
        // If it is a last-chance situation, new bin should lose.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
        // Perfect fit available in an existing bin means new bin is bad.
        if next_item_size > 0 && post_residual == 0 {
            score += 60.0;
        }
    }

    // Mild penalty for very large unusable residuals relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 0.5; // tiny dead slivers are bad
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual relative to capacity quadratically.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0; // small dead space is nearly perfect
    }

    // Large dead space penalty: residuals below typical item sizes are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing ones; few open bins: allow new bins.
    let openness = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += openness * 3.0;

    // Compare post_residual against mean residual: avoid creating outliers.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // penalize leaving space too small for the next item
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
        // chain fit: item + next item exactly fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Late in the stream: be more conservative, prefer tight packing of existing bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += progress * 4.0 * fit_ratio;

    // New-bin candidate: make it moderately attractive only when the item is small
    // relative to residuals or no good fit exists; penalize opening new bins otherwise.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            // opening a new bin wastes the residual of the best alternative
            score += 10.0 + 0.3 * mean_residual;
        }
    }

    // Mild preference for bins with larger residual when item is large.
    if item_size > 60 {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear tightness coupling: reward small post_residual quadratically
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness;

    // Polynomial interaction of post_residual with stream progress:
    // early in stream, mild preference to fill bins; later, stronger packing pressure
    let prog_term = progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score -= 8.0 * prog_term * (1.0 - tightness);
    score += 6.0 * progress * tightness * tightness;

    // Reward tight fit relative to item size (waste ratio coupling)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: only one bin fits -> strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize leaving residual that barely fails next item,
    // reward residual that can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (nxt / cap);
        } else {
            let gap = nxt - pr;
            score += 4.0 * (gap / cap) * (gap / cap);
        }
    }

    // Penalize bins deviating from mean residual (encourage balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin, more so late in stream
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * progress;
    }

    // Mild penalty when many bins already open (prefer consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded,
    // tiny dead-space residues (<10, unusable for min item) heavily penalized.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 15.0;
    } else {
        // reward residues that are "harmonically friendly" (multiples of 10/20)
        let m10 = post_residual % 10 == 0;
        let m20 = post_residual % 20 == 0;
        if m20 {
            score -= 12.0;
        } else if m10 {
            score -= 6.0;
        }
    }

    // Coupling with lookahead item: reward if next item fits exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post < 10 {
                score -= 20.0;
            } else {
                score -= (nxt_post as f64) * 0.1;
            }
        } else {
            // next item cannot fit here: mild penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.05;
        }
    }

    // Last-chance bin before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    // or few bins are open (early stream) or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual < 10 && post_residual > 0;
        let big_item = item_size >= 60;
        if open_bins_count >= 2 && !poor_fit && !(big_item && progress > 0.3) {
            score += 40.0;
        }
        if mean_residual > 40.0 && open_bins_count >= 3 {
            score += 30.0; // plenty of slack spread around; don't open more
        }
    }

    // Tight-packing bonus: bins whose residual is close to capacity get a
    // slight preference so large holes stay available for large items.
    if post_residual >= 40 {
        score += (post_residual as f64 - 40.0) * 0.15;
    }

    // Integer-division threshold: bins at "half-full or better" are preferred.
    if post_residual <= bin_capacity / 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize "unusable" small gaps: gaps that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap is dead space for the lookahead item; penalize proportionally.
        score += 0.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap remains usable by the next item; reward.
        score -= 0.3 * next_item_size as f64;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += 0.05 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild step decay: later in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // Prefer bins tighter than the mean residual (good fills).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - lookahead_waste / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 150.0; // chain of perfect fits
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize dead space relative to its size
        score += 0.5 * (next_item_size as f64).min(post_residual as f64);
    }

    // Penalize small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // and current residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if item_size >= 60 && fragmentation > 20.0 {
            score -= 30.0; // big item into fresh bin when others are fragmented
        } else {
            score += 80.0; // default: prefer existing bins
        }
    }

    // Late in stream: be more conservative, keep residuals usable
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual), nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        if next_item_size > 0 && next_item_size <= post_residual {
            // Next item can still fit here: reward keeping this bin viable.
            score -= 8.0;
        } else if next_item_size > post_residual {
            // Lookahead item cannot use leftover: penalize waste.
            score += 0.35 * (post_residual as f64 - fit_ratio * bin_capacity as f64).max(0.0) + 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in stream, tolerate opening bins; late, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when fits exist.
        score += 18.0 + 30.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Opening a fresh bin early is cheap; also good if mean residual is large.
        score -= 0.05 * mean_residual;
    } else {
        // Slight preference for bins whose residual is closest below next item.
        if next_item_size > 0 && bin_residual >= next_item_size {
            score -= 3.0;
        }
        // Penalize bins much emptier than the mean (keeps residuals uniform).
        score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Small global load balancing: many open bins -> discourage spreading.
    score += 0.4 * (open_bins_count as f64 / (1.0 + progress * 10.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear penalty on small dead space
    let mut score = pr as f64;
    score += 18.0 * norm_pr * (1.0 - norm_pr); // smooth hump: penalize mid residuals

    // Polynomial coupling of post_residual with stream progress
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 10.0 * prog_poly * norm_pr * norm_pr;

    // Favor tight fits more strongly later in the stream
    score -= 12.0 * fit_ratio * (1.0 + prog_poly);

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - pr / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 4.0 * ((next_item_size as f64) - pr) / cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild regularization via mean residual and open bins count
    score += 0.05 * (open_bins_count as f64);
    score += 2.0 * (mean_residual / cap - norm_pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // ---- New-bin candidate ----
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin: high, but softened when
        // this item has no other home or fits nowhere gracefully.
        let mut s = cap * 1.10;
        if fitting_bins_count == 0 {
            s -= cap; // forced open: essentially free choice
        } else {
            // Only attractive if every fitting bin would leave a bad class.
            s -= (fitting_bins_count as f64) * 2.0;
        }
        // Slightly cheaper to open bins early in the stream.
        s -= (1.0 - progress) * 10.0;
        return s;
    }

    // ---- Existing bin ----
    let mut score = post_residual as f64;

    // Harmonic class of post_residual via integer division on quarter bins.
    let cls = post_residual / quarter;
    match cls {
        0 => {
            // Tight fit: post_residual < C/4 -> excellent packing density.
            score -= 45.0;
            if post_residual == 0 {
                score -= 60.0; // perfect closure
            } else if post_residual < 10 {
                score -= 20.0; // near-perfect, tiny unusable crumb
            }
        }
        1 => {
            // Quarter-to-half leftover: mediocre, mild penalty.
            score += 12.0;
        }
        2 => {
            // Half-to-three-quarter leftover: still quite usable.
            score -= 8.0;
        }
        _ => {
            // Large leftover: wasteful use of an open bin.
            score += 25.0;
        }
    }

    // Modulo harmonic: post_residual congruent to small multiples of 10
    // pairs well with typical item sizes; reward clean alignment.
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0;
    } else if m >= 7 {
        score += 4.0; // awkward non-aligned residue
    }

    // Lookahead coupling (k=2): does the next item fit here afterwards?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0; // chain placement possible
            if post_residual - next_item_size < quarter {
                score -= 8.0; // chain leaves a tight class again
            }
        } else {
            // This placement strands the bin relative to the next item.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance rescue: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // Prefer bins below mean residual (consolidate emptier bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: post_residual in the "dead zone" (1..=9)
    // is nearly worthless since items are >= 1 but typically much larger.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 - (post_residual as f64) * 2.0;
    }
    // Slightly unusable mid gaps (10..=19) can only accept small items; mild penalty.
    else if post_residual >= 10 && post_residual <= 19 {
        score += 8.0;
    }

    // Reward tight fits: perfect or near-perfect fills get a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: apply pressure plus a lookahead penalty if the
        // next item could have fit in an existing bin instead.
        score += 30.0 + pressure;
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score += 10.0;
        }
    } else {
        // Existing-bin bonus scaled by pressure so crowded states favor reuse.
        score -= pressure * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item fits in post_residual, mild reward; otherwise mild penalty
    // for leaving a gap the future cannot use.
    else if next_item_size > 0 {
        if next_item_size < post_residual {
            score -= 5.0;
        } else {
            score += 6.0;
        }
    }

    // Stream progression: early on, be slightly more willing to open new bins
    // (spread items); late in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (bin_residual != bin_capacity) as i32 as f64;
    score += (1.0 - progress) * 3.0 * (bin_residual == bin_capacity) as i32 as f64;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already tight — reward using it; if far above mean, mild penalty
    // for leaving it wide open.
    let resid_diff = (bin_residual as f64) - mean_residual;
    score += resid_diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Next item fits into post_residual: mild reward proportional to tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.3 * tightness;
    }
    // Next item cannot use post_residual: penalize dead space, worse for tiny leftovers.
    else if next_item_size > 0 {
        let waste = post_residual as f64;
        if waste > 0.0 && waste < 10.0 {
            score += 25.0 - 2.5 * waste; // tiny unusable slivers are bad
        }
    }

    // Compare post_residual against mean residual: leaving bin below-average residual
    // means we consumed more of the "rich" bins first; reward that.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless current
    // residuals are all poor fits. Empty bin has raw residual = capacity, so add
    // a fixed surcharge that lookahead rewards must overcome.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if no open bin fits (fitting_bins_count==0 semantics handled by caller),
        // still allow: reduce surcharge when item is large relative to capacity.
        score -= 0.2 * item_size as f64;
    }

    // Late in the stream: prefer tighter packing, less bin sprawl.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits with a superlinear waste penalty.
    let waste = post_residual as f64;
    score += 0.35 * (waste * waste) / bin_capacity as f64;

    // Reward small post-residual that can still hold typical future items.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 6.0;
    }
    // Penalize dead space that no item can ever fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if the next item fits the post-residual exactly well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; slight penalty.
            score += 3.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 {
        score -= 2.0 * mean_residual / bin_capacity as f64;
    }
    // Early in the stream, opening new bins is cheaper; later, consolidation matters more.
    score += 8.0 * progress;

    // New-bin candidate handling: make an empty bin attractive only when the fit
    // is large relative to capacity (avoid opening bins for tiny items).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 12.0 * fill_ratio;
        } else {
            score += 20.0 * (1.0 - fill_ratio);
        }
        // Late in the stream, opening a fresh bin is less desirable if others fit.
        if fitting_bins_count > 0 {
            score += 15.0 * progress;
        }
    }

    // Mild preference for bins whose residual is close to mean (balance residuals).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but dampen late in the stream (dead space matters more early).
    let mut score = pr * (1.0 - 0.35 * progress * (1.0 - norm_pr));

    // Smooth polynomial coupling: penalize mid-range residuals (awkward gaps),
    // reward near-zero and reward large residuals (still reusable).
    let x = norm_pr;
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep in [0,1]
    score += 18.0 * (1.0 - poly) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless it enables a very tight pack
    // or no good alternative exists (few fitting bins).
    if bin_residual == bin_capacity {
        let tight_next = if next_item_size > 0 {
            (cap - (item_size as f64 + next_item_size as f64)) / cap
        } else {
            1.0
        };
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 30.0 * (1.0 - scarcity) - 20.0 * (1.0 - tight_next.abs().min(1.0)) * progress;
        score += 6.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: reward leaving residual close to next item size (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / cap) * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (balance load across bins).
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and small remainders are prized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: remainders that no item (>=1) can use are worst-case,
    // remainders below the minimum item size are dead.
    if post_residual < 10 {
        score += 50.0 * (10.0 - pr);
    }

    // Modulo-class logic on post_residual w.r.t. capacity fractions.
    // Residuals matching common item-size classes (multiples of 5/10/20)
    // are more reusable.
    let reusable = (post_residual % 5 == 0) as f64 * 15.0
                 + (post_residual % 10 == 0) as f64 * 10.0
                 + (post_residual % 20 == 0) as f64 * 5.0;
    score -= reusable;

    // Lookahead coupling: reward if next item fits the post residual,
    // scaled by harmonic compatibility of (post_residual - next_item_size).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let after_next = post_residual - next_item_size;
            score -= 30.0;
            score -= (after_next % 10 == 0) as f64 * 20.0;
            score -= (after_next % 5 == 0) as f64 * 8.0;
            if after_next < 10 && after_next > 0 {
                score += 10.0; // creates tiny dead space
            }
        } else {
            // Next item won't fit here; penalize mildly, more if this is a tight fit anyway.
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current item leaves bad residue
    // everywhere or stream is early and we want fresh capacity.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 60.0;
        // Early in the stream or few bins: fresh bin more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        // If item is large relative to capacity, a fresh bin keeps it clean.
        score += (item_size as f64 / cap) * 10.0;
    }

    // Prefer bins whose residual is below the mean (tight packing),
    // with a non-linear coupling.
    let tight = (mean_residual - pr).max(0.0);
    score -= tight * 0.5;

    // Slight penalty for proliferating bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "unusable" if it's too small for typical items (say < 10)
    // or too small for the lookahead item.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny dead space is nearly worthless
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0; // gap can't fit the next item
        } else {
            // usable gap: mild reward proportional to its utility
            score -= 5.0;
        }
    } else {
        // perfect fill
        score -= 25.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins; penalize spreading items thin.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item.
    // Only allow opening a new bin when existing fits are poor (large post_residual)
    // and mean residual across open bins is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let existing_poor = mean_residual > 45.0 && post_residual < 25.0;
        if existing_poor {
            score -= 20.0 + 10.0 * progress;
        } else {
            score += 35.0; // discourage opening new bins when fits exist
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly (sets up a perfect second fill).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (fill the emptier-relative bins to keep the pool tidy).
    let bin_res_f = bin_residual as f64;
    if bin_res_f > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // Next item fits in post_residual: mild reward proportional to tightness
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Next item would NOT fit here: penalize leaving a gap next item can't use
    if next_item_size > 0 && next_item_size > post_residual {
        score += 40.0;
    }

    // Penalize small unusable dead space relative to mean residual
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score += 30.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // Early stream: prefer keeping residuals large (flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (post_residual as f64) * 0.5;

    // Slight preference for filling already-open bins vs opening new ones
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Bonus if next item almost exactly fills the remaining space.
        let next_waste = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - next_waste / bin_capacity as f64);
    }
    // Penalize if next item is slightly too big for post_residual (near-miss creates dead space).
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        let miss = (next_item_size - post_residual) as f64;
        if miss < 10.0 {
            score += 5.0 * (1.0 - miss / 10.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize when many bins are open and residuals are high (fragmentation pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual as f64 > mean_residual {
        score += 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64 * (1.0 + progress);
    } else {
        score -= 1.5 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Early in the stream: allow opening new bins for large items (better long-term packing).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline score; attractive early, penalized late.
        score = score.max(0.0) + 20.0 * progress - 10.0 * (1.0 - progress);
        if item_size > 60 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Mild penalty for very tiny residuals that can never fit future items (min size 1).
    if post_residual < 4 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post / cap;

    // smooth polynomial coupling of post_residual with stream progress
    let p_norm = post / cap;
    let coupling = p_norm * p_norm * (1.0 - progress) + p_norm * progress * (1.0 - p_norm);
    score += 3.0 * coupling;

    // penalize last-chance bins less (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 1.5 * (nxt / cap) * (1.0 - post / cap);
        } else {
            score += 1.0 * (1.0 - post / cap);
        }
    }

    // slight preference for bins tighter than the mean residual
    score += 0.5 * ((post - mean_residual) / cap);

    // new-bin candidate: prefer it only when post_residual would be very small
    if bin_residual == bin_capacity {
        score = 0.5 + 0.5 * (1.0 - progress) - (item_size as f64 / cap) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into bands.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if pr <= 5 {
        score -= 35.0;
    } else if pr <= 10 {
        score -= 20.0;
    } else {
        // Dead-space penalty grows faster for residuals in awkward bands.
        // Harmonic classes: residuals that are multiples of common item sizes
        // (10, 20, 25, 50) are reusable; others are penalized.
        let reusable = pr % 10 == 0 || pr % 25 == 0;
        if reusable {
            score -= 8.0;
        } else {
            score += (pr as f64) * 0.35;
        }
        // Very small unusable slivers (1..5) are dead space unless item was tiny.
        if pr < 5 && item_size > 50 {
            score += 12.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward leaving space that exactly accommodates the next item.
            let slack = (pr - next_item_size) as f64;
            score -= 18.0 - slack * 0.25;
            if pr == next_item_size {
                score -= 15.0; // perfect lookahead match
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overflow gap.
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.12;
            // If this bin is the last chance for the current item, weight it heavily.
            if fitting_bins_count == 1 {
                score -= 40.0;
            }
        }
    }

    // Last-chance bin logic: if only this bin fits the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity elsewhere.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin, scaled by how many bins are open
        // and the mean residual available across them.
        let mut new_bin_score = 30.0 + (open_bins_count as f64) * 2.0;
        if mean_residual >= item_size as f64 {
            // There exists space on average; new bin is less attractive.
            new_bin_score += 10.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 15.0;
        // Large items relative to capacity justify a fresh bin.
        if item_size > 70 {
            new_bin_score -= 20.0;
        }
        // If next item is huge and current item is large, a fresh bin keeps
        // flexibility for the pair.
        if next_item_size > 60 && item_size > 50 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score + (pr as f64) * 0.1;
    }

    // Harmonic class of the item itself: items near half-capacity are flexible;
    // placing them into tight residuals wastes their flexibility.
    let half = bin_capacity / 2;
    if item_size >= half.saturating_sub(5) && item_size <= half + 5 {
        // Half-class items prefer bins whose residual is close to item size.
        let mismatch = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
        score += mismatch * 0.15;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor with coupling).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Integer-division threshold: reward bins whose residual divided by item
    // size allows multiple future copies of this item class.
    if item_size > 0 && bin_residual / item_size >= 2 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that no plausible item can use (too small relative to stream) is dead space.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // This placement strands the next item: penalize proportionally.
            score += (next_item_size as f64) * 0.6;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage filling
    // existing bins when the count is high.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins tighter than the mean residual (best-fit flavor with mean coupling).
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // New-bin candidate handling: only attractive late in the stream or when the
    // current fit leaves a large dead gap in every open bin.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        score += 5.0; // slight default penalty: prefer using open bins when reasonable
        if item_size as f64 > mean_residual.max(1.0) * 0.9 {
            score -= 15.0; // item barely fits open bins on average -> fresh bin is fine
        }
    }

    // Mild stream-phase modulation: early on, keep bins flexible (larger post residuals OK);
    // late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the leftover space exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Soft reward for near-match with the lookahead item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 15.0 * (1.0 - diff / 50.0).max(0.0);
    }

    // Reward tight fits (small dead space) more aggressively.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize creating dead space below the minimum item size (unusable gap).
    if next_item_size > 0 && post_residual < next_item_size.min(10).max(1) {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but penalize tiny unusable slivers.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    if post > 0.0 && post < 10.0 {
        score += 8.0 * (10.0 - post); // dead-space penalty for slivers
    }

    // Lookahead: if the next item fits into the post_residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty proportional to the gap.
        score += 0.05 * (next_item_size as f64 - post);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with residual already below mean (consolidating space).
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: cost grows with progress and with number of open bins.
        score = cap - progress * 15.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 25.0; // never open a new bin when a last-chance bin exists
        }
        if next_item_size > 0 && item_size + next_item_size as u32 <= bin_capacity {
            // Pairing current+next item in a fresh bin is attractive early.
            score -= (1.0 - progress) * 10.0;
        }
    } else {
        // Existing bin: late stream rewards filling more aggressively.
        score -= progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of bin consumed by this placement
    let fill_frac = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer small post_residual (tight packing) strongly; later,
    // relax slightly since residual space has less future value.
    let progress_weight = 0.6 * (1.0 - progress) + 0.2;
    score += progress_weight * (post_frac * post_frac) * cap * 0.5;

    // Reward tight fits (small post_residual) with a smooth cubic term
    let tightness = 1.0 - post_frac;
    score -= (tightness * tightness * tightness) * 12.0;

    // Penalize dead space: post_residual that is too small for typical items
    // smooth logistic-like penalty around unusable residuals
    let dead = post_frac * 4.0;
    score += 8.0 / (1.0 + (dead * dead * 3.0).exp());

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 6.0;
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty scaled by how close it is
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0) / cap;
        score += gap * 5.0;
    }

    // New-bin candidate handling: brand-new empty bin
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when few bins fit the item or
        // existing residuals are small (poor fits everywhere)
        let scarcity = 1.0 / (fitting_bins_count as f64);
        let poor_fits = (mean_residual - item_size as f64).max(0.0) / cap;
        score -= scarcity * 15.0 + poor_fits * 20.0;
        // Early in the stream, slightly discourage hoarding new bins
        score += progress * 4.0;
    }

    // Mild penalty for proliferating open bins with large mean residual
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - progress);

    // Keep mean residual coupling: prefer bins whose residual is near the mean
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small dead space" classes (residual < smallest item, or tiny remainders)
    // are penalized to avoid fragmenting bins.
    let min_item = 1u32;
    if post_residual < 10 {
        // dead space that likely can never be reused
        score += 6.0;
    } else if post_residual < 25 {
        score += 2.5;
    } else {
        score -= 1.5;
    }

    // Modulo-10 harmonic class: residuals divisible by 10 align well with
    // item sizes drawn from decade grids -> reward them.
    if post_residual % 10 == 0 {
        score -= 2.0;
    } else if post_residual % 5 == 0 {
        score -= 1.0;
    }

    // Integer division thresholds: leftover that can host the next item is great.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
            // exact pairing: post_residual == next_item_size is a perfect fill
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else {
            // leftover too small for lookahead item: mild penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    } else {
        // last item: prefer tightest fill overall
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // New-bin candidate handling: empty bins should only win when no open bin
    // offers a good fit. Penalize the fresh bin via its large residual, but
    // allow it when mean residual across open bins is fragmented.
    if bin_residual == bin_capacity {
        score += 12.0;
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Progress coupling: early in stream, be frugal with new bins; late in
    // stream, consolidation matters more, reward tight fits further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 1.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below mean residual (denser bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are unusable "dead space" -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gap: partially usable, moderate penalty scaled by how dead it is.
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual that still stays usable).
    if post_residual > 0 && post_residual >= 10 {
        score -= 12.0 / post_residual as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // reward leaving that gap; penalize if the gap is just barely too small.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 25.0; // sets up a near-perfect fit for next item
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // gap blocks the next item
        }
    }

    // Open-bins pressure: discourage scattering across many open bins,
    // but only mildly, so tight fits still dominate.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (unless dead space would result).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when this
    // bin would leave a large, wasteful residual or dead space.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; slightly above a good fit,
        // below a wasteful placement.
        score = 45.0 + open_bins_count as f64 * 0.3;
        // If the current bin would be nearly empty after placement anyway,
        // opening a fresh bin is fine.
        if post_residual > 60 {
            score -= 20.0;
        }
        // Reserve fresh bins for large items.
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (bin_residual as f64 - post_residual as f64) * 0.05;
    score -= progress * 5.0;

    // Mean-residual coupling: if this bin is far below the mean residual,
    // filling it is cheap; if it's the fullest bin, slight penalty.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual large enough for the next item: mild reward scaled by slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.05 * (post_residual - next_item_size) as f64;
    }

    // Dead space: post_residual too small for next item (and too small for min item ~1),
    // penalize proportionally to how "wasted" it is relative to mean residual.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Compare post_residual against mean residual: leaving more than average is good
    // (bin stays flexible), leaving less than average is bad.
    score -= 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Penalize opening a new bin when reasonable open bins exist, unless item is large
    // and no bin fits well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced when stream is late or many bins open.
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin suits a big follow-up item
        }
        if open_bins_count > 0 && item_size <= 30 {
            score += 20.0; // small items should go into open bins
        }
    }

    // Late-stream pressure: consolidate as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward bins whose residual closely matches the item (tight fit).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Lookahead coupling: if the next item can also fit in the leftover space,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= next_item_size as f64 * 0.6;
        } else {
            // leftover likely dead space relative to next item
            score += next_item_size as f64 * 0.15;
        }
    }

    // Last-chance bonus: this is the only open bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin, but less
    // so for large items (which would leave a clean, useful residual).
    if bin_residual == bin_capacity {
        score += 22.0 - item_size as f64 * 0.2;
    }

    // Prefer bins that are "tighter" than the average open bin.
    score += (mean_residual - bin_residual as f64) * 0.1;

    // As the stream progresses, favor consolidating into existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 6.0;

    // Mild penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;

    // Base: prefer minimal post-residual, with smooth non-linear emphasis.
    let mut score = pr + 18.0 * (pr / cap).powi(2) * (0.6 + 0.8 * progress);

    // Dead-space penalty: residuals too small for any plausible item are waste.
    let dead = ((20.0 - pr) / 20.0).max(0.0);
    score += 30.0 * dead * dead;

    // Fullness reward: encourage filling bins tightly.
    score -= 25.0 * fit * fit * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a fresh bin, unless residuals are large
    // and current item leaves a big usable gap (smooth interaction).
    if bin_residual == bin_capacity {
        score += 40.0 + 25.0 * progress;
        // Allow new bin when item is large and mean residual is already fragmented.
        score -= 20.0 * fit * (mean_residual / cap).min(1.0);
    }

    // Lookahead: reward placements that still accommodate the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 12.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 6.0 * ((ni - pr) / cap);
        }
    }

    // Mild dispersion pressure: keep open-bin count lean.
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // for common item sizes (multiples of 10 and small remainders).
    let mod10 = post_residual % 10;
    if mod10 == 0 && post_residual > 0 {
        score -= 6.0; // perfectly aligned residual, highly reusable
    } else {
        score += mod10 as f64 * 0.5; // penalize misaligned dead space
    }

    // Integer division thresholds: residual classes by capacity fraction
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 8.0; // nearly-full bin: good, but only if it closes
    } else if frac < 0.3 {
        score -= 2.0; // small but usable gap
    } else if frac > 0.6 {
        score += 3.0; // wasting a mostly-empty bin
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0; // perfect chain placement
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
        // Harmonic class match: next item fits a mod-10 aligned residual
        if next_item_size % 10 == 0 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are bad
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // big item followed by bigger: maybe worth a fresh bin
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Tie-break by mean residual alignment
    if (post_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are wasted forever.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure is ideal
    } else if post_residual <= 20 {
        score += 12.0; // very tight gap, risky
    } else if post_residual >= 50 {
        score += 5.0; // large leftover is fine, mild penalty to prefer tighter fits
    }

    // Reward filling a bin that is the item's only option (avoid opening bins needlessly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from open bin count: prefer already-open bins over new ones when crowded.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening bins, more so when many are open or mean residual is high.
        score += 35.0 + 3.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // If the next item is large and this bin would leave a good residual, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Reward tight fits relative to bin residual.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * fill_ratio;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 4.0; // next item can't use this gap
    }

    // Early in the stream, be slightly more willing to spread out (build diverse residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the lookahead item fits exactly / well into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.8; // perfect chain match gets biggest bonus
    } else if next_item_size > 0 {
        // next item cannot follow here: penalize mildly, more if we leave big dead space
        score += 5.0 + post_residual as f64 * 0.05;
    }

    // Penalize dead space relative to mean residual: leaving much more free space
    // than average means this bin was a poor fit target
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.10;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discard tiny unusable residuals (dead space creation)
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // New-bin candidate: only attractive when current bins are crowded / bad fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        let bad_fit = item_size as f64 / bin_capacity as f64;
        // penalize new bin generally, relax penalty late in stream or when fits are scarce
        score += 55.0 - 20.0 * progress - 10.0 * bad_fit - 6.0 * (crowded - 1.0).min(3.0);
        // if next item is large and won't fit a typical residual, new bin slightly better
        if next_item_size > 60 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space (small but nonzero post residual).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * next_fit;
        } else {
            // Next item won't fit here; penalize bins that strand lots of space.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Perfect fill jackpot.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Global state coupling: when mean residual across open bins is low,
    // prefer packing into existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.3 * mean_residual * (1.0 - progress);

    // Early in the stream, slightly favor opening new bins to build diversity;
    // later, consolidate.
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / cap);

    // Discourage using nearly-full bins when many alternatives exist.
    let residual_frac = bin_residual as f64 / cap;
    if residual_frac < 0.15 && fitting_bins_count > 2 {
        score += 10.0;
    }

    // Mild penalty for large open-bin counts (encourage consolidation).
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on post-residual (dead space)
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling: residual waste matters more as stream progresses
    let progress_coupling = norm_pr * norm_pr * (progress * (1.0 - progress) * 4.0 + 0.5);
    score += 40.0 * progress_coupling;

    // Cubic interaction between item size and remaining space
    score -= 25.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Reward tight fits: small post_residual relative to item size
    score -= 15.0 / (1.0 + pr);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // penalize leaving space too small for the known next item
        score += 8.0 * (1.0 - pr / next_item_size as f64).max(0.0);
    }

    // Mean residual context: penalize bins far from mean residual (fragmentation)
    score += 5.0 * (pr - mean_residual).abs() / cap;

    // Prefer reusing bins when many are open
    score += 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * norm_pr;

    // New-bin candidate: penalize opening a new bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let tightness = 1.0 / (1.0 + mean_residual / cap);
        score += 20.0 * (1.0 - progress) * tightness + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    // Post-residuals that are "nice" (divisible by 4 or 8, or equal to 0) are
    // reusable slots for common item sizes, so reward them.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if post_residual % 8 == 0 {
        score -= 12.0;
    } else if post_residual % 4 == 0 {
        score -= 6.0;
    } else if post_residual % 2 == 0 {
        score -= 2.0;
    } else {
        score += 4.0; // odd residual is awkward
    }

    // Dead-space penalty: small unusable leftovers (harmonic classes 1..=9)
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Integer-division threshold: how many "typical" items (size ~25) still fit?
    let slots = post_residual / 25;
    score -= 5.0 * slots as f64;

    // Next-item lookahead coupling: does the next item land exactly in the
    // post-residual (harmonic match)?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) % 4 == 0 {
            score -= 10.0;
        } else if post_residual < next_item_size && next_item_size <= bin_residual {
            // next item would need another bin anyway; slight penalty for
            // leaving a gap the next item cannot use
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless post-residual is truly dead space.
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual < 10 && post_residual > 0 {
            score += 12.0; // but not if it creates a tiny useless remainder
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Give empty bins a baseline near the mean residual so
    // that tight fits in open bins beat it.
    if bin_residual == bin_capacity {
        // Empty-bin score: mildly above a good fit, below a terrible fit.
        score = (bin_capacity as f64) * 0.55 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere: new bin is mandatory
        }
        return score;
    }

    // Tightness reward: fraction of the bin's space consumed now.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Stream progression: late in the stream, consolidate harder (avoid many
    // half-empty bins at the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: when open bins are generally full, prefer
    // squeezing into existing ones rather than opening new ones.
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small for the smallest plausible item are wasted.
    let min_useful = 12.0;
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += 60.0 * (min_useful - post_residual as f64) / min_useful;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins already open.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits the post-residual, reward leaving useful space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Prefer bins with residuals close to item size (good packing density).
    score += 0.3 * (bin_residual as f64 - item_size as f64);

    // Mild stream progression pressure to close out bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual matches next item size closely.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here afterwards: penalize proportionally.
        let overflow = (next_item_size - post_residual) as f64;
        score += 0.5 * overflow;
    }

    // Penalize small dead space that no item (min size ~1) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer filling bins with above-average residual.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if only one bin fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly or few exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        let penalty = 70.0 + 60.0 * (1.0 - progress) + 30.0 * (open_bins_count as f64).ln().max(0.0);
        score += penalty - 55.0 * poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact fills are highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(3));
    }

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (sets up a chain of perfect fills).
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        let pr = post_residual as f64;
        if nd == pr {
            score -= 400.0;
        } else if nd <= pr {
            score -= 60.0 * (nd / pr);
        } else {
            // Next item won't fit here; mild penalty proportional to wasted potential.
            score += 10.0 * ((nd - pr) / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // is large and no open bin offers a good fit. Penalize opening new bins
    // mildly by default, scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        let base_penalty = 40.0 + 5.0 * open_bins_count as f64;
        score += base_penalty;
        // Large items are more "wasteful" to stuff into partially filled bins,
        // so give new bins a discount when item is big.
        score -= 0.6 * item_size as f64;
        // Early in the stream, new bins are cheaper; later, prefer consolidation.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * t;
    }

    // Global state: if mean residual across open bins is high, there is plenty
    // of slack — encourage using existing bins (reward this bin more).
    score -= 0.15 * mean_residual;

    // Prefer bins whose residual is close to the item (best-fit style, nonlinear).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * fit_gap;

    // Slight preference for bins with larger current residual when item is small
    // (preserve tight bins for tight items).
    if item_size < 30 {
        score -= 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residual_norm = pr / cap;
    let fit_norm = (item_size as f64) / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic waste penalty growing with progress
    score += 8.0 * residual_norm * residual_norm * (0.5 + progress);

    // Reward tight fits (small post_residual) with cubic discount
    score -= 12.0 * (1.0 - residual_norm).powi(3) * fit_norm;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Discard spreading when many bins are open relative to mean residual
    let mean_norm = mean_residual / cap;
    score += 4.0 * residual_norm * mean_norm * (open_bins_count as f64).ln().max(1.0) / (1.0 + progress);

    // Lookahead: penalize blocking the next item, reward leaving usable space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 6.0 * (nxt / cap) * (1.0 - residual_norm);
        } else {
            score += 5.0 * (1.0 - nxt / cap) * residual_norm * (1.0 + progress);
        }
    } else {
        // Last item: minimize waste entirely
        score += 10.0 * residual_norm;
    }

    // New-bin candidate: make empty bin mildly attractive only when current fits are bad
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 10.0 * progress * fit_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: post_residual small relative to capacity.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 25.0 * tight * tight;

    // Harmonic class of post_residual: waste buckets via integer division.
    // Residuals 1..10 are near-dead space; 11..20 poor; >20 more usable.
    let dead_class = post_residual / 10; // 0 = dead, 1 = poor, ...
    score += match dead_class {
        0 => 30.0,
        1 => 12.0,
        2 => 4.0,
        _ => 0.0,
    };

    // Exact fill bonus (perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if next_item_size fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            // harmonic compatibility: how well next item divides the leftover
            let compat = (post_residual % next_item_size.max(1)) as f64;
            score -= 8.0 * (1.0 - compat / cap);
        } else {
            // next item cannot use this leftover: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly, but allow if all open bins would leave
    // large dead space (item much larger than mean residual).
    if bin_residual == bin_capacity {
        score += 45.0;
        if (item_size as f64) > mean_residual + 15.0 && open_bins_count > 0 {
            score -= 50.0;
        }
    }

    // Prefer denser bins early (mean_residual coupling): favor bins below mean residual.
    score += 3.0 * ((post_residual as f64) - mean_residual).max(-20.0).min(20.0) * 0.1;

    // Late-stream consolidation: fewer open bins preferred as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64).log2().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly unusable.
    let dead_zone_max: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) <= dead_zone_max {
        score += (dead_zone_max - post_residual as f64 + 1.0) * 18.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small residual that still fits the lookahead item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * tightness;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit here: leftover is likely dead space.
        score += 15.0;
    }

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when fit is mediocre.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + progress * 20.0);
    if post_residual > 0 {
        score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64).min(50.0) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual).min(50.0) * 0.3;
    }

    // New-bin candidate: attractive early or when item barely fits anywhere,
    // otherwise keep it slightly worse than a decent existing fit.
    if bin_residual == bin_capacity {
        let scarce = (fitting_bins_count as f64).max(1.0);
        let scarcity_bonus = 30.0 / scarce;
        score = score * 0.0 + (bin_capacity as f64 - item_size as f64)
            - scarcity_bonus
            - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with a little slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.8;
        // Extra reward if slack is small relative to mean residual
        if slack < mean_residual * 0.25 {
            score -= 10.0;
        }
    }
    // Next item cannot fit here: penalize dead space creation
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
        // Worse if the dead space is tiny (wasted) but not zero
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Reward using a bin that is nearly full after placement (tight packing)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (i.e., fuller bins) so emptier bins stay flexible
    let residual_diff = bin_residual as f64 - mean_residual;
    score += residual_diff * 0.3;

    // Penalize the brand-new empty bin candidate mildly, unless no good fit exists
    if bin_residual == bin_capacity {
        let has_good_fit = next_item_size > 0 && post_residual == next_item_size;
        if !has_good_fit && fitting_bins_count > 0 && fitting_bins_count <= 2 {
            // Opening a new bin is fine if existing fits are poor
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

    // Early in stream: be slightly more conservative with open bins (keep flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Tight-fit reward: strongly prefer bins with small post-residual
    score -= (1.0 - post / cap) * (1.0 - post / cap) * 12.0;

    // Penalize dead space that no future item can use (items >= 10 normally, 1 min)
    let min_item = 1.0f64;
    if post > 0.0 && post < min_item {
        score += 25.0;
    }
    // Penalize awkward residuals near common item sizes (fragmentation zones)
    let awkward = (post - 50.0).abs();
    score += (awkward / cap) * 4.0;

    // Lookahead coupling: if next item fits exactly in post-residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() < 0.5 {
            score -= 15.0;
        } else if nxt <= post {
            score -= (nxt / post.max(1.0)) * 6.0;
        } else {
            score += 3.0; // next item won't fit here; wasted capacity
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + item * 0.05;
    }

    // Global state: many open bins with slack -> prefer filling existing bins
    let slack = mean_residual - post;
    if slack > 0.0 {
        score += slack * 0.02;
    }
    score -= (open_bins_count as f64).ln().max(0.0) * 0.8 * (1.0 - post / cap);

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, just close bins out
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * (post / cap) * 5.0;
    score -= t * 2.0;

    // New-bin candidate: make empty bin attractive only when item is large
    // and no open bin fits well
    if bin_residual == bin_capacity {
        let openness = item / cap;
        score -= 6.0 * openness;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if item as u32 >= 51 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with a convex penalty for large leftovers
    let mut score = r + (r / cap).powi(3) * cap * 0.8;

    // Non-linear stream-progress coupling: early on, tolerate loose fits;
    // later, demand tight fits (tightness reward grows smoothly).
    let tightness = 1.0 - (r / cap);
    score -= tightness * tightness * (0.5 + 2.5 * progress) * 10.0;

    // Penalize bins whose residual deviates from the mean (spread control)
    let dev = (r - mean_residual) / cap;
    score += dev * dev * 20.0 * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count <= 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= r {
            let slack_after_next = r - nx;
            score -= (1.0 - slack_after_next / cap) * 6.0;
        } else {
            score += (nx - r) / cap * 8.0;
        }
    }

    // Mild penalty on opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into classes of 10.
    let class = post_residual / 10;
    // Dead-space penalty grows super-linearly for small, awkward leftovers.
    if post_residual > 0 {
        let awkward = match class {
            0 => 30.0, // 1..9 : nearly unusable
            1 => 14.0, // 10..19
            2 => 7.0,  // 20..29
            3 => 3.0,  // 30..39
            4 => 1.0,  // 40..49
            _ => 0.0,
        };
        score += awkward;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Harmonic coupling: does the lookahead item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: the next item can land here too; reward.
            score -= 12.0 + (next_item_size as f64) * 0.1;
        } else {
            // Leftover cannot host the next item: penalize proportionally to waste.
            score += 4.0 + 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: keep it attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if post_residual == bin_capacity as u32 {
            // Opening fresh is good when mean residual is small (bins nearly full)
            // or when many bins are open but none fit well.
            score -= 6.0 * (1.0 - pressure);
            if next_item_size > 0 && next_item_size > mean_residual as u32 {
                score -= 8.0;
            }
        }
    } else {
        // Penalize placing into bins whose residual deviates strongly from mean
        // (keeps a balanced pool of residuals for future items).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Late in the stream, prefer tightening existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for filling fuller bins overall.
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit even the
    // minimum plausible item are essentially wasted — punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fits (small post residual relative to bin capacity) get rewarded.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count,
        // but relax pressure early in the stream when bin count is low.
        score += 8.0 + 2.5 * open_pressure;
    } else {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it;
    // if next item is bigger than post_residual, slightly penalize (dead end).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            score -= 5.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (concentrate filling) when the mean is high.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev;
    }

    // Progression: later in stream, be slightly more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Penalize dead space: post_residual too small for the next item (unusable gap).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Mild reward when post_residual can still fit the next item later.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when decent fitting open bins exist.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // But allow a new bin if it would leave an exact match for the next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 1000.0;
        }
    }

    // Late-stream consolidation: tighten bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // Penalize dead space that can never fit a typical item again.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 5.0; // moderately awkward residual
    }

    // Lookahead: strongly reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // exact complement fit is ideal
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing item here destroys the only space for the next item
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin unless it's genuinely better.
    if bin_residual == bin_capacity {
        score += 20.0;
        // More open bins already -> keep consolidating.
        score += 2.0 * open_bins_count as f64;
        // Early in stream, allow more bins (flexibility); late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If mean residual is large, existing bins have room; new bin wasteful.
        score += 0.3 * mean_residual;
        // If no existing bin fits well (tightness low), new bin more acceptable.
        if tightness < 0.5 {
            score -= 15.0;
        }
    }

    // Mild preference for bins with residuals above average (keep flexible bins available).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0; // use below-average-space bins first
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: penalize large post_residual more as stream progresses
    let pr_norm = pr / cap;
    let prog2 = progress * progress;
    score += 12.0 * pr_norm * pr_norm * (0.4 + 1.6 * prog2) * cap * 0.1;

    // Reward tight fits with smooth cubic term
    let tight = 1.0 - pr_norm;
    score -= 8.0 * tight * tight * tight;

    // Last-chance bonus (smoothly scaled)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Interaction with mean residual: penalize bins far from mean residual (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Lookahead: reward leaving space for next item smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = (pr >= ns) as i32 as f64;
        let slack = (pr - ns).abs() / cap;
        score += -10.0 * fit_next * (1.0 - slack * slack) + 4.0 * slack;
    }

    // Mild pressure against many open bins early, less later
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // Prefer using existing bins vs opening new empty bin smoothly
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress + 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes define "usable" dead space.
    // Residuals that are multiples of small denominations (mod 10) are more reusable.
    let pr = post_residual as i64;
    let class = (pr % 10) as i64;
    // Penalize awkward remainders (1..9 mod 10), reward clean classes (0 mod 10, mod 5)
    score += (10 - class) as f64 * 0.6;
    if pr % 5 == 0 { score -= 2.0; }
    if pr % 10 == 0 && pr > 0 { score -= 3.0; }

    // Integer-division thresholds: a residual that can hold a "half bin" is valuable
    if pr >= bin_capacity / 2 { score -= 4.0; }
    else if pr >= bin_capacity / 4 { score -= 1.5; }
    else if pr > 0 { score += 3.0; } // tiny dead space is nearly worthless

    // Perfect fit is supreme
    if post_residual == 0 { score -= 100.0; }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item's size class aligns with residual class
            score -= 6.0;
            if post_residual % next_item_size.max(1) == 0 { score -= 4.0; }
        } else {
            // Next item won't fit here; residual may become stranded
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate penalty: opening a fresh bin is expensive unless item is huge
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Only attractive when the item occupies most of a bin or nothing else fits
        score += 25.0 - 30.0 * frac;
        if fitting_bins_count == 0 { score -= 40.0; } // no open bin fits: must open
        if next_item_size > 0 && next_item_size >= post_residual { score -= 5.0; }
    }

    // Stream phase: late in the stream, consolidate harder (avoid opening bins)
    let phase = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity { score += 10.0 * phase; }

    // Many open bins with slack: prefer bins that reduce mean residual dispersion
    score -= (bin_residual as f64 - mean_residual) * 0.08;

    // Mild preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (items are >= 1, but small gaps rarely match future demand).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward residual that can still host a mid/large item.
    if post_residual >= 50 {
        score -= 12.0;
    } else if post_residual >= 30 {
        score -= 6.0;
    } else if post_residual >= 10 {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(20.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into bins that leave large residuals; encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item (tight fit relative to fleet state).
    let fit_gap = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.15 * fit_gap;

    // New empty bin candidate: only attractive when no open bin fits well
    // or the fleet is saturated / residual is huge.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let fleet_full = (open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0)) * 0.1;
        score = 140.0 - 90.0 * desperation - fleet_full - 20.0 * progress;
        // If the next item is large, a fresh bin keeps flexibility.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 2.0 * (100.0 - gap.min(100.0)); // exact match for next item => big bonus
        // Bonus if next item fits exactly after this one (perfect 2-chain).
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize leaving residual that no future item can use well.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0; // dead space under min item size
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless all open bins leave huge waste.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let best_possible = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 40.0 };
        score += 45.0 + best_possible;
    }

    // Late in stream, be more conservative (tighten preference for existing tight bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.3 * post_residual as f64;

    // Small penalty for very loose fits (large leftover waste).
    if post_residual > 50 {
        score += 0.4 * (post_residual as f64 - 50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward small residuals (dead space) after placement.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score -= 8.0 * (1.0 - dead / 0.12); // tiny leftovers are fine (near-perfect fit)
        } else if dead < 0.35 {
            score += 6.0 * (0.35 - dead) / 0.23 * 0.0 + 4.0; // moderate waste is bad
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mildly penalize large post residuals that strand space
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state coupling: with many open bins, prefer consolidation into fullest bins.
    let openness = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += 3.0 * openness * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (denser bins) as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // New-bin candidate: only attractive when current item is huge or no good fit exists.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 25.0 - 30.0 * big_item - 20.0 * desperation - 10.0 * progress * (1.0 - big_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling: tight fits rewarded more as stream progresses
    let tight = 1.0 - norm_pr;
    score -= 40.0 * tight * tight * (0.5 + progress);
    // Penalize dead space non-linearly
    score += 30.0 * norm_pr * norm_pr * (1.0 + progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }
    // Lookahead coupling: if next item fits smoothly, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 - ((pr - nxt) / cap).abs() } else { -1.0 };
        score -= 10.0 * fit_next * (0.3 + 0.7 * progress);
    }
    // Mean residual interaction
    let mr = mean_residual / cap;
    score += 8.0 * (norm_pr - mr) * (norm_pr - mr);
    // New-bin candidate: penalize mildly unless current residual very small
    if bin_residual == bin_capacity {
        score += 15.0 - 20.0 * (1.0 - norm_pr);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fraction = post / cap; // 0..1

    // Penalize residuals in "awkward" harmonic bands (just above small item sizes).
    // Residuals in (0,10] are nearly dead; (10,20] semi-dead, etc.
    if post_residual == 0 {
        score -= 30.0; // perfect fit, ideal closure
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 25 {
        score += 8.0;
    } else if post_residual <= 50 {
        score += 3.0;
    } else {
        score -= 4.0; // large residual still flexible
    }

    // Modulo-style classification: residual mod 10 (item granularity hint)
    let class = post_residual % 10;
    score += class as f64 * 0.4;

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0; // chains a perfect fit
        } else {
            score -= 10.0 - (slack as f64).min(10.0) * 0.8;
        }
    } else if next_item_size > 0 {
        score += 6.0; // next item cannot go here; bin becomes dead-ish
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score = cap - pressure - 8.0 * (1.0 - fraction);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin good for a large incoming pair
        }
    }

    // Progression: late in stream, prefer tightening bins (less waste spread).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post) * 0.15 * (1.0 - progress);

    // Prefer filling bins with higher residual when few bins open (consolidation).
    if open_bins_count > 4 {
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    } else {
        score -= 5.0; // roomy leftover is fine
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin before opening a new one: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing bins, avoid spreading.
    let pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += pressure + 30.0;
        // But allow opening a new bin early in the stream or when the fit would be poor.
        if post_residual < 20 && open_bins_count > 0 {
            score -= 55.0;
        }
        if step_index as f64 / (total_items.max(1) as f64) < 0.2 {
            score -= 20.0;
        }
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: if next item could use the leftover, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Penalize creating residual far below the mean residual (fragmentation).
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chained packing).
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - lookahead_gap / (bin_capacity as f64));

        // If next item fits exactly or nearly in the post residual, strong bonus.
        if next_item_size <= post_residual {
            score -= 20.0 + 0.5 * next_item_size as f64;
        }
    } else {
        // Last item: simply minimize post residual.
        score -= 10.0;
    }

    // Penalize dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - pr);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a brand-new bin when decent fits exist, unless the
    // current item would leave a very small, unusable residual.
    if bin_residual == bin_capacity {
        let tight_fit = post_residual <= 10;
        if !tight_fit && fitting_bins_count > 1 {
            score += 60.0;
        }
        // Slight preference for new bins early in the stream (more future value).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Mild penalty for very small dead space that wastes capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer tighter fits overall (small normalized slack).
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize unusable dead space: if post_residual is small but nonzero,
    // it is unlikely to fit future items (min item size ~1, but small scraps waste).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly; reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty if we leave a very snug gap.
            score += 5.0;
        }
    }

    // Global state: prefer filling bins when many bins are open
    // (consolidation pressure), less so when few bins are open.
    let consolidation = (open_bins_count as f64).ln().max(0.0);
    score -= 6.0 * consolidation * tightness;

    // Time horizon: early in the stream, be more selective (keep bins flexible);
    // late in the stream, just pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier worth closing out; reward using it.
    let residual_diff = mean_residual - bin_residual as f64;
    if residual_diff > 0.0 {
        score -= 8.0 * residual_diff / bin_capacity as f64;
    } else {
        score += 4.0 * (-residual_diff) / bin_capacity as f64;
    }

    // New-bin candidate adjustment: opening a new bin is only attractive when
    // no good fit exists; make the empty bin moderately costly so tight fits win.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = norm_post * (1.0 + 0.8 * progress * norm_post + 0.35 * norm_post * norm_post);

    // Penalize dead space more as the stream matures.
    let mut score = base * (1.0 + 0.6 * progress);

    // Reward tight fits (small post_residual) with a smooth saturating term.
    score -= 2.5 * (1.0 - norm_post) * (1.0 - norm_post);

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 1.5 * (1.0 - (post - nxt) / cap);
        } else {
            score += 0.8 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2;
    }

    // Mild penalty for spreading across too many open bins vs mean residual.
    score += 0.05 * ((open_bins_count as f64).ln() * (mean_residual / cap - norm_post).abs());

    // New-bin candidate: prefer it only when it beats tight fits late in stream.
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual), especially perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class penalty: residuals divisible by small classes are more usable.
        let pr = post_residual;
        let mut class_bonus = 0.0;
        if pr % 10 == 0 { class_bonus += 8.0; }
        if pr % 20 == 0 { class_bonus += 4.0; }
        if pr % 25 == 0 { class_bonus += 3.0; }
        if pr % 5 == 0 { class_bonus += 2.0; }
        // Medium residuals are most reusable (items are 1..=100).
        if pr >= 10 && pr <= 60 { class_bonus += 5.0; }
        if pr > 80 { class_bonus += 3.0; } // large leftover still flexible
        score -= class_bonus;

        // Penalize tiny dead space (5..=9) which is nearly unusable.
        if pr < 10 { score += 15.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 { score -= 12.0; }
            else if gap > 50 { score += 4.0; }
        }
        // If next item won't fit anywhere else, prefer keeping space for it.
        if next_item_size > post_residual && post_residual < 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 70.0 - 15.0 * progress;
        // If current item is large and would leave bad residual in existing bins,
        // new bin becomes attractive: large items pair well with small ones.
        if item_size >= 60 && post_residual <= 40 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && open_bins_count > 0 {
            score += 10.0; // don't waste fresh bin when next item is also big
        }
    } else {
        // Mild preference for filling bins that are already partially used.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fill;
        // Penalize scattering across many bins when mean residual is high.
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (residual < 10 is waste)
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: prefer consolidating into fewer bins
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residual close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Slight preference for existing bins over new bin (new bin has full residual)
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 200.0;
            // tighter match gets extra reward
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot fit here: penalize dead space relative to gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Reward bins tighter than the mean residual (more filled bins preferred)
    let residual_f = bin_residual as f64;
    score += (residual_f - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Penalize leaving large unusable slivers (below minimum item size 1..100 range granularity)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Late in the stream: prefer compacting into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 50.0;

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;

    // Penalize leaving dead space that likely can't be used by next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.9 * (next_item_size - post_residual) as f64;
        } else {
            // Next item fits here: reward keeping room for it.
            score -= 0.5 * post_residual as f64 / (next_item_size as f64 + 1.0);
        }
    } else {
        // Last item: prefer tightest packing.
        score -= 2.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor for this item.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity as f64 - item_size as f64) - post_residual as f64;
        // Penalize new bin slightly; more when many bins already open.
        score += 3.0 + 0.15 * open_bins_count as f64;
        // But if mean residual is large and item is large, new bin may be better.
        let poor_fit = (mean_residual - item_size as f64).abs();
        if poor_fit > 25.0 {
            score -= 0.4 * poor_fit;
        }
        let _ = waste;
    }

    // Mild penalty for very small post_residual fragments below typical item size,
    // unless it's an exact/perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 2.0;
    }
    if post_residual == 0 {
        score -= 8.0; // perfect fill
    }

    // Time-horizon modulation: early in stream, be more conservative about
    // fragmenting bins; later, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    // Prefer bins with residual close to item size (good global fit).
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * residual_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_norm = post / cap;

    // Base: quadratic penalty on wasted space, amplified late in the stream
    let mut score = post * (1.0 + 1.5 * progress) + 2.0 * fit_norm * fit_norm * cap * (0.5 + progress);

    // Reward tight fits: subtract when post_residual is small relative to capacity
    score -= 30.0 * (1.0 - fit_norm).powi(3) * (1.0 + progress);

    // Penalize opening a new bin when existing bins fit (new-bin candidate has residual == capacity)
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 40.0 + 10.0 * openness * (1.0 - progress);
        // But allow new bin if remaining bins are few and item is large
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Deviation from mean residual: prefer bins that reduce residual dispersion
    score += 3.0 * (post - mean_residual).abs() / cap;

    // Mild preference for fuller bins among many open bins
    score += (open_bins_count as f64).sqrt() * fit_norm * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.96;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 8.0;
    } else if dead > 0.0 && dead < 20.0 {
        score += (20.0 - dead) * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0 + progress * 20.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 5.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        }
    }

    // Prefer bins tighter than the mean residual (better packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: exact / near-exact fill reward (dead space minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item fits perfectly in this bin afterward
            if diff < 1.0 {
                score -= 200.0;
            } else if diff <= 10.0 {
                score -= 40.0 - 2.0 * diff;
            } else {
                score -= 10.0;
            }
        } else {
            // next item would NOT fit here after placement: penalize proportionally
            score += (nxt - post_residual as f64) * 0.8;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Late in stream: tighten packing further
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 { 60.0 } else { 0.0 };
        score += 40.0 + desperation + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small waste relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that can never be reused by typical items (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin unless
    // current open bins have poor residuals (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - (bin_capacity as f64 * 0.5)).abs() / (bin_capacity as f64 * 0.5);
        score += 30.0 - 15.0 * fragmentation - 10.0 * progress;
        // If next item is large, opening a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Prefer filling bins with larger residuals less when many bins are open
    // (consolidation pressure scales with open bin count).
    score += (open_bins_count as f64).ln().max(0.0) * fit_ratio * 5.0;

    // Global state: when mean residual is high, tolerate looser fits;
    // when mean residual is low, tighten selection.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Time horizon: early in the stream, be pickier (long future to regret waste);
    // late in the stream, just fill bins.
    let urgency = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * urgency * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = item_size as f64 / cap;
    let pr_frac = pr / cap;

    // Base: post-residual, with non-linear penalty on dead space
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, waste is punished more (dead space harder to reuse)
    let progress_waste = pr_frac * pr_frac * (0.5 + 1.5 * progress) * cap;
    score += 0.8 * progress_waste;

    // Reward tight fits (low relative post-residual) increasingly over time
    score -= 12.0 * fit_frac * (1.0 - pr_frac) * (0.4 + 0.6 * progress);

    // Lookahead: bonus if next item fits exactly into the new post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let nx_frac = nx / cap;
            // smooth reward, stronger when the next item nearly fills post space
            let tight = 1.0 - ((pr - nx) / cap).abs();
            score -= 10.0 * nx_frac * (0.5 + tight) * (0.5 + 0.5 * progress);
        } else {
            // penalize leaving a residual too small for the next item late in stream
            score += 6.0 * (1.0 - progress) * (pr_frac / (nx / cap));
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_frac) * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize mildly, more early when open bins exist and are roomy
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let mean_frac = mean_residual / cap;
        score += 4.0 + 10.0 * openness * mean_frac * (1.0 - progress);
        // allow new bin late if residuals are tiny (little room left anywhere)
        score -= 8.0 * progress * (1.0 - mean_frac);
    }

    // Slight preference for fuller bins vs mean residual (balance consolidation)
    score += 2.0 * ((mean_residual - pr) / cap).max(0.0) * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify by capacity fractions
    let cap_f = bin_capacity as f64;
    let frac = post_residual as f64 / cap_f; // fraction of capacity left

    // Penalize dead space: small non-zero post_residuals are wasted
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic classes via integer division thresholds on post_residual
    let class = post_residual / 10; // 0..=10
    match class {
        0 => score += 60.0,          // nearly full: great if exactly 0, bad if tiny leftover
        1 => score += 8.0,
        2 => score += 3.0,
        3 => score += 0.0,
        4 => score += 2.0,
        5 => score -= 4.0,           // half-full: flexible, mildly favored
        6 => score += 1.0,
        7 => score -= 2.0,
        8 => score += 0.0,
        9 => score -= 1.0,
        _ => score -= 5.0,           // nearly empty bin: plenty of room
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: slight penalty proportional to overflow
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it is
    // chosen only when no open bin offers a good fit
    if bin_residual == bin_capacity {
        score += 30.0;
        // late in the stream, prefer reusing open bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild tie-break toward tighter bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        }
        // penalize leaving residual that neither fits next item nor is useful
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0 * (1.0 - post_residual as f64 / 100.0);
        }
    } else {
        // last item: prefer tightest fit
        score += 50.0;
    }

    // Relative-to-mean coupling: bins with residual near mean are "typical" targets
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins early when decent fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 15.0; // new bin can chain with next item
        }
    }

    // Reward tight fits generally
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.08;
    score
