pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling: waste grows quadratically with normalized post residual,
    // amplified as the stream progresses (dead space late is more costly).
    let late_amp = 0.5 + 2.0 * progress;
    score += late_amp * 40.0 * pr_norm * pr_norm;

    // Cubic term: strongly penalize very tight-but-unusable slivers vs. perfect fits.
    let sliver = pr_norm * (1.0 - pr_norm);
    score -= 15.0 * sliver * (1.0 - 0.5 * progress);

    // Interaction: item size vs residual — prefer bins where item fills a large
    // fraction of the residual; smooth polynomial coupling.
    let fill = item_norm / (pr_norm + item_norm + 1e-9);
    score -= 20.0 * fill * fill;

    // Lookahead: reward if next item fits in post residual (smooth kernel).
    if next_item_size > 0 {
        let fits = (post_residual as f64 - next_item_size as f64).max(0.0) / cap;
        let fit_kernel = 1.0 - (pr_norm - next_item_size as f64 / cap).abs();
        score -= 8.0 * fits.max(0.0) * fit_kernel.max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, discourage opening a new one.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - pr_norm * pr_norm);
    }

    // Mean residual deviation: prefer bins whose residual is near the mean
    // (keeps the bin population homogeneous), smooth Gaussian-like term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Crowding: many open bins -> favor filling existing ones.
    let crowd = 1.0 - (-(open_bins_count as f64) / 10.0).exp();
    score -= 6.0 * crowd * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // residue classes mod 10 and capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: leftover below the smallest possible item is pure waste.
    if post_residual < 1 {
        score -= 1000.0; // perfect fill, strongly favored
    } else if post_residual < 10 {
        score += 60.0; // unusable sliver (min item is 10 in classic streams)
    }

    // Modulo-10 harmonic class: leftovers that are multiples of 10 are
    // "harmonic" — likely to be exactly filled by future items.
    let r10 = post_residual % 10;
    if r10 == 0 && post_residual > 0 {
        score -= 12.0; // harmonic leftover, reusable
    } else {
        score += (r10 as f64) * 1.5; // off-harmonic waste
    }

    // Compatibility with lookahead item: does next_item_size fit exactly
    // or harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // exact future fill
        } else if next_item_size < post_residual {
            let diff = post_residual - next_item_size;
            score -= 8.0;
            if diff % 10 == 0 {
                score -= 10.0; // harmonic chain continues
            }
        } else {
            score += 6.0; // next item cannot use this bin's leftover
        }
    }

    // Fraction-of-capacity class of the filled bin.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 0.9 {
        score -= 25.0;
    } else if fill_frac >= 0.7 {
        score -= 8.0;
    } else if fill_frac < 0.5 {
        score += 10.0; // half-empty bins are poor targets unless last chance
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
        if post_residual < 10 {
            score -= 20.0; // nearly-perfect last-chance fit
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual;
    // penalize it mildly so good fits into existing bins win, but keep it
    // attractive when existing bins would waste badly.
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 30.0; // open bins are nearly full; fresh bin is fine
        }
    }

    // Slight stream-position modulation: later in the stream, consolidation
    // matters more (fewer bins opened).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // Tie-break toward bins tighter than the mean residual.
    score -= (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized (unusable gaps).
    let dead_threshold = 10.0 + 0.25 * (mean_residual.max(0.0)).min(60.0);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + 0.8 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (small post_residual) super-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins, but only if the fit is decent.
    let pressure = (open_bins_count as f64) * 0.6;
    if post_residual > 0 {
        score += pressure * (post_residual as f64) / (bin_capacity as f64);
    } else {
        // Perfect fill is always great, offset bin pressure entirely.
        score -= pressure + 10.0;
    }

    // Lookahead: if the next item fits into the resulting residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * (next_item_size as f64);
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement destroys room needed by the next item: penalize.
        score += 6.0;
    }

    // New-bin candidate: opening a new bin should only win when this is a
    // poor fit into existing bins (large post_residual or dead-space risk).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 25.0;
        // As the stream progresses, opening bins early is worse (longer horizon).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
        // But if existing bins are all tightly packed (low mean residual),
        // a new bin is more acceptable.
        score -= 0.3 * (mean_residual.max(0.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post_residual) is better.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual > 0 {
        let next_f = next_item_size as f64;
        let post_f = post_residual as f64;
        if next_item_size == post_residual {
            // Perfect chaining: subtract heavily to strongly favor this bin.
            score -= 45.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportionally to how well it fills leftover.
            let fill_ratio = next_f / post_f;
            score -= 25.0 * fill_ratio;
            // Penalize large unusable remainder after the next item.
            let after = post_f - next_f;
            if after > 0.0 {
                score += 0.25 * after;
            }
        } else {
            // Next item does NOT fit: penalize wasted post_residual as dead space,
            // scaled by how much of the bin is left empty.
            let waste = post_f / bin_capacity as f64;
            score += 18.0 * waste;
            // Extra penalty if the leftover is small but nonzero (unusable sliver).
            if post_residual < 10 {
                score += 12.0;
            }
        }
    } else if next_item_size == 0 && post_residual > 0 {
        // Last item: just prefer minimal leftover.
        score += 0.1 * post_residual as f64;
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably.
    // A bin with residual above mean that fits well is a good consolidation target.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when no open bin
    // offers a reasonable fit. Make the empty bin moderately expensive.
    if bin_residual == bin_capacity {
        // Scale cost with stream progression: late in the stream, consolidation matters more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 + 25.0 * progress;
        // If many bins are open, discourage adding more.
        score += 2.0 * open_bins_count as f64;
        // But if the next item is large, a fresh bin can be attractive.
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Mild penalty for leaving exactly awkward remainders that few item sizes can use.
    let r = post_residual;
    if r > 0 && r < 10 {
        score += 8.0; // sliver
    }
    if (81..=89).contains(&r) {
        score += 3.0; // large but awkward band relative to 10..80 items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize large dead space beyond what's needed.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small residual is valuable
    }
    if post_residual >= 30 && post_residual <= 60 {
        score += 4.0; // mid-range leftovers are awkward
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 6.0;
        } else if next_item_size as f64 > post_residual as f64
            && next_item_size as f64 <= post_residual as f64 + 12.0 {
            score += 5.0; // next item nearly fits but won't — bad pairing
        }
    }

    // Global state coupling: many open bins with high mean residual
    // suggests we should consolidate rather than spread.
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early in stream, be more open to new bins;
    // late in stream, prefer packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // New-bin candidate handling: empty bin gets a dynamic penalty
    // that shrinks as the stream progresses or when few bins fit the item.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(1.0);
        score += 18.0 + 8.0 * (1.0 - progress) - 12.0 * (1.0 - progress) * (fitting_bins_count as f64).min(4.0) / 4.0;
        score += 2.0 * open_pressure.min(6.0);
    }

    // Mild penalty on opening many bins early.
    score += (open_bins_count as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr * (0.7 + 0.6 * progress) + 40.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space that cannot fit the average upcoming item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (1.0 + progress);
        } else {
            score -= 5.0 * (1.0 - (pr - ni) / cap);
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && !is_new {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize early, allow late or when open bins are crowded
    if is_new {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 60.0 - 35.0 * progress - 8.0 * crowding.min(4.0);
    }

    // Slight penalty for many open bins with high mean residual (fragmentation)
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod classes capture "perfect" residual sizes
    // that are likely reusable by future items (multiples of common sizes).
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit: zero waste, strongly favored
    } else {
        // Reward residuals that are multiples of 10 or 25 (reusable sizes)
        if post % 10 == 0 {
            score -= 12.0;
            if post % 25 == 0 { score -= 6.0; }
        }
        // Penalize awkward dead space classes: residual < 10 is nearly unusable
        if post < 10 {
            score += 40.0;
        } else if post < 20 {
            score += 15.0;
        }
        // Integer-division harmonic: residual in [1..9] is dead; [10..19] marginal.
        // Reward residual that exactly matches next item or a divisor class.
        if next_item_size > 0 {
            if post == next_item_size {
                score -= 30.0; // next item fills this bin exactly
            } else if post >= next_item_size && post - next_item_size < 10 {
                score -= 8.0; // next item leaves a tiny but class-consistent remainder
            } else if post < next_item_size {
                score += 10.0; // next item won't fit here
            }
            // harmonic coupling: next_item_size mod 10 == post mod 10 -> same class
            if post % 10 == (next_item_size % 10) && post >= next_item_size {
                score -= 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has max residual; make it slightly
    // unattractive unless open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64).sqrt() * 2.0;
        if post_residual >= 80 {
            score -= 10.0; // large item benefits from fresh bin
        }
    }

    // Tightness reward: fraction of bin filled by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Progression: later in stream, prefer tighter packing (favor low post_residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Prefer bins below mean residual (consolidate waste)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize tiny unusable gaps nonlinearly.
    let dead_zone = 3.0; // gaps <= 3 are effectively dead space
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 40.0;
    }
    // Nonlinear penalty for small-but-not-zero post residuals (hard to reuse)
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * (11.0 - post_residual as f64) * 0.8;
    }

    // Reward tight fits (low post residual relative to item size)
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += tightness * 15.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (raise score of everything except the new-bin candidate, which is identified
    // by bin_residual == bin_capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        score -= open_bins_count as f64 * 2.0;
    } else {
        // Opening a new bin is only attractive when current bins are crowded
        score += open_bins_count as f64 * 1.5;
        score += mean_residual * 0.3; // if mean residual is high, avoid new bin
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }
    // If next item would leave this bin's remainder dead, mild penalty
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 6.0;
    }

    // Early in the stream, be more willing to open bins (spread items);
    // later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if !is_new_bin {
        score -= (1.0 - progress) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: exact match between post_residual and next item
    // is a perfect chain -> heavily favored.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            // next item fits after this placement: reward closeness of fit
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would NOT fit: penalize proportionally to wasted potential
            let overflow = diff;
            score += 10.0 + 0.5 * overflow;
        }

        // Two-step sum check: item + next exactly fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 40.0;
        }
    } else {
        // Last item: just minimize residual waste
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter,
    // prefer filling them (less fragmentation across the fleet).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving tiny unusable slivers (dead space)
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size.min(10) {
        score += 12.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mild preference for keeping the number of open bins low as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make an empty bin attractive only when the fit into
    // existing bins would be poor (large post_residual or next item won't chain).
    if bin_residual == bin_capacity {
        // baseline cost of opening a fresh bin
        score += 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // still allow fresh bin when it enables a clean 2-item packing
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= (item_size as f64) * (1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0));
    }

    // Penalize dead space: post_residual too small to ever be useful (< 10)
    if post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    }
    // Penalize bins that will strand the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }
    // Many fitting bins: mild penalty to prefer diversification of residual sizes
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state coupling: when mean residual is high, prefer filling existing bins
    score -= 0.15 * (mean_residual - (post_residual as f64));

    // Time horizon: early in the stream, opening bins is cheaper; late, conserve bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (open_bins_count as f64).powf(0.5) * 0.1;

    // New-bin candidate handling: make fresh bins attractive only when fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when current options look bad
        let poor_fit_penalty = if post_residual >= 0 && bin_residual == bin_capacity {
            0.0
        } else { 0.0 };
        let _ = poor_fit_penalty;
        score = (bin_capacity as f64) * 0.55
            - 20.0 * progress
            + (open_bins_count as f64) * 2.0
            - (fitting_bins_count as f64) * 6.0;
        if next_item_size > 0 && item_size >= 50 {
            score -= 15.0; // big items pair well in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_norm = post / cap; // 0..1 fraction of wasted space after placement

    // Core: minimize leftover space, with a non-linear (quadratic) penalty on waste.
    let mut score = post + 30.0 * fit_norm * fit_norm;

    // Smooth interaction: as the stream progresses, tighter packing matters more.
    score += 40.0 * progress * fit_norm * fit_norm;

    // Dead-space penalty: leftover too small to ever fit the smallest plausible item.
    // Smoothly penalize residuals below ~15% of capacity using a smooth ramp.
    let dead = (0.15 - fit_norm).max(0.0) / 0.15;
    score += 25.0 * dead * dead;

    // Lookahead coupling: reward if the next item could fit the post-residual
    // (keeps chains alive), penalize otherwise, smoothly scaled by lookahead size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let fits_next = post >= next;
        let gap = (next - post).abs() / cap;
        if fits_next {
            score -= 12.0 * (1.0 - gap) * (1.0 + progress);
        } else {
            score += 10.0 * gap * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (smoothly weighted by number of fitting bins).
    if fitting_bins_count >= 1 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 20.0 * scarcity;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin when open bins already exist, scaled by progress.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 35.0 + 40.0 * progress;
    }

    // Mild preference toward consolidating into bins near the mean residual
    // (keeps bin population balanced, smooth coupling).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: reward residuals that "tile" well ---
    // Residuals divisible by small size classes (10/20/25/50) are reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 10.0; }
        // Dead-space penalty: tiny unusable slivers
        if pr < 10 { score += 45.0; }
        else if pr <= 15 { score += 18.0; }
    }

    // Integer-division thresholds: classify residual into harmonic bands
    let band = (pr / 25).min(4);
    score += band as f64 * 2.0; // prefer smaller residual bands

    // --- Lookahead coupling: does post_residual fit next_item_size exactly? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            let nx = next_item_size;
            if nx == pr {
                score -= 55.0; // next item exactly consumes residual
            } else if pr % nx == 0 {
                score -= 14.0; // harmonic divisibility: multiple future fits
            } else {
                let npr = pr - nx;
                if npr % 10 == 0 { score -= 5.0; }
                if npr < 10 { score += 12.0; }
            }
        } else {
            // next item cannot use this residual at all -> residual likely wasted
            score += 10.0;
            if pr < next_item_size && pr >= 10 { score += 8.0; }
        }
    }

    // --- Last-chance bonus: if this is the only fitting bin, avoid new bin ---
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: be pickier, penalize mediocre fits
        score += 4.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin: attractive when current open bins are tightly packed
        // or when item is large (would leave big residual in a used bin).
        score = 40.0
            - (item_size as f64 / bin_capacity as f64) * 25.0
            + mean_residual * 0.35;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 5.0; // next item needs a fresh bin anyway
        }
        if open_bins_count == 0 { score -= 50.0; }
        return score;
    }

    // --- Tightness reward: fraction of bin used by this placement ---
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // --- Stream progression: late in stream, consolidate aggressively ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.05; // squeeze residual usage late
    }

    // --- Mean residual context: prefer bins below mean residual (tighter bins) ---
    score += (mean_residual - bin_residual as f64) * 0.12;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A post_residual that cannot accommodate even the smallest plausible item
    // (or the lookahead item) is wasted capacity.
    if post_residual > 0 {
        let unusable = post_residual < 10 || (next_item_size > 0 && post_residual < next_item_size);
        if unusable {
            score += (bin_capacity as f64) * 0.75 + post_residual as f64 * 2.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= bin_capacity as f64 * 0.9;
    }

    // Reward tight fits generally (small post_residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than proliferating; a new-bin candidate (residual == capacity)
    // gets penalized proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 6.0 + 12.0;
    } else {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement for enabling a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., already well-filled), reducing fragmentation across bins.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Slight late-stream tightening: as the stream progresses, be less willing
    // to leave dead space behind.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but keep some usable slack.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Two-step lookahead: reward when the NEXT item fits into the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post residual exactly matches next item -> big reward.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 + (bin_capacity as f64 * 0.25 - slack).abs() * 0.2;
            if slack == 0.0 {
                score -= 25.0; // exact 2-step match: ideal packing
            }
        } else {
            // Next item cannot use this residual: penalize dead space creation,
            // scaled by how much of the capacity is wasted.
            let dead = post_residual as f64;
            score += dead * 0.35;
            if dead < 10.0 {
                score += 15.0; // tiny unusable sliver
            }
        }
    } else {
        // Last item: just minimize residual.
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (tighter bins get filled first), keep roomier bins for larger items.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 3.0;
    }

    // New-bin candidate: make it moderately attractive only when it's
    // genuinely better (e.g., current item is large and no good fit exists).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > bin_capacity as f64 * 0.6;
        let poor_fits = fitting_bins_count == 1 && post_residual as f64 > 0.0;
        if large_item && poor_fits {
            score -= 35.0; // opening fresh bin for a big item is fine
        } else {
            score += 60.0 + item_size as f64 * 0.3; // discourage wasting fresh bins
        }
    }

    // Mild stream-progression pressure: later in the stream, be greedier
    // about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.15);

    // Penalize very large post-residuals (wasted space) non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * tightness * tightness * (post_residual as f64);

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if next item can use this bin's post-residual.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0;
        } else if next_item_size as f64 > post_residual as f64 && post_residual > 0 {
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
        // If next item fits exactly with current item, big bonus.
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // Time horizon: early in stream, be pickier (penalize loose fits);
    // late in stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * tightness * 10.0;
    score -= progress * 5.0 * (bin_residual != bin_capacity) as i32 as f64;

    // Global state: many open bins with high mean residual -> discourage new bins,
    // encourage filling existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate score: base penalty grows with open bins.
        score += 15.0 + 2.0 * open_bins_count as f64;
        if open_bins_count > 0 {
            score += mean_residual * 0.5;
        }
        // Late in the stream, opening a bin is cheaper than wasting space.
        score -= 20.0 * progress;
    } else {
        // Reward bins whose residual is close to the mean (balanced usage).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 2.0 / (1.0 + dev);
    }

    // Prefer bins with small absolute residual overall.
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; later, strongly prefer small post_residual.
    let poly = x * x * (1.0 - progress) + x * x * x * (2.0 * progress + 0.5);
    score += poly * cap * 0.35;

    // Penalize dead space that is too small to fit the next item (smoothly).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = (nxt - pr).max(0.0) / cap;
        score += slack * slack * nxt * 0.8;
        // Reward when post_residual still accommodates the next item.
        let fit_bonus = (pr / nxt).min(1.0);
        score -= fit_bonus * fit_bonus * 6.0 * (1.0 - progress);
    }

    // Last-chance bin: reward strongly to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Smooth coupling with mean residual across open bins:
    // prefer bins whose residual deviates from the mean (consolidate slack).
    let mean_norm = mean_residual / cap;
    let dev = x - mean_norm;
    score += dev * dev * cap * 0.15 * (0.5 + progress);

    // Mild penalty for many open bins (encourage consolidation), scaled by progress.
    score += (open_bins_count as f64) * 0.05 * (0.3 + progress);

    // Slight preference for larger fill (smaller post_residual) as stream progresses.
    score -= (1.0 - x) * (1.0 - x) * 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify leftover space into
    // capacity-fraction bands. Residuals in (0, 10) are near-perfect fits.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect / near-perfect fit reward (strong).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 45.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    } else {
        // Large leftover: dead-space penalty growing with size.
        score += 0.15 * (pr - 30.0);
    }

    // Dead space: residual too small for the smallest possible item (1..10)
    // is wasted space; penalize proportionally.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // still better to fill than leave >10 unusable? no: reward
        // Actually unusable dead space should be penalized relative to usable:
        score += 25.0 * (1.0 - pr / 10.0);
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if it cannot fit, mildly penalize (bin becomes dead).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = pr - n;
            if slack == 0.0 {
                score -= 40.0;
            } else if slack <= 10.0 {
                score -= 18.0;
            } else {
                score -= 3.0;
            }
        } else {
            score += 8.0 * (n - pr) / cap_f * 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // New-bin candidate: empty bin. Base cost so we only open when fits are bad.
    if bin_residual == bin_capacity {
        let base = 55.0
            + 0.05 * open_bins_count as f64
            + 0.10 * mean_residual;
        score = base
            // opening is more attractive later in the stream? slightly less
            - 5.0 * (step_index as f64 / (total_items.max(1) as f64))
            // if next item is huge and current fit is poor, opening helps
            + if next_item_size > 70 { 10.0 } else { 0.0 };
    }

    // Modulo harmonic nudge on post_residual: multiples of 5 tend to combine
    // better with typical item sizes; reward divisibility classes.
    let m = post_residual % 10;
    score -= match m {
        0 => 6.0,
        5 => 3.0,
        1 | 9 => 1.5,
        _ => 0.0,
    };

    // Slight preference for filling fuller bins overall (tight packing).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Dead-space avoidance: small leftover gaps are nearly unusable.
        // Estimate the minimum plausible future item size adaptively from the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let min_gap = (8.0 * (1.0 - 0.5 * progress)).max(3.0);
        let pr = post_residual as f64;
        if pr < min_gap {
            // Unusable sliver: penalize heavily, worse the smaller it is.
            score += (min_gap - pr) * 8.0;
        } else if pr < item_size as f64 {
            // Gap too small for the current-size class but not tiny: moderate penalty.
            score += 5.0;
        }
        // Reward leaving gaps that could still fit typical items.
        if pr >= 20.0 {
            score -= 3.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use this bin's leftover: slight dead-space penalty.
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good existing option,
    // or when open-bin pressure is low. Penalize opening a new bin when
    // alternatives exist and mean residual is still healthy.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let pressure = (open_bins_count as f64).ln().max(1.0);
            let healthy = (mean_residual / bin_capacity as f64).min(1.0);
            score += 10.0 * pressure * (0.3 + healthy);
            // If current item would leave a big usable gap in an existing bin,
            // opening a new bin wastes that space: extra penalty.
            if post_residual >= 30 {
                score += 5.0;
            }
        } else {
            // Forced new bin (or only poor fits): make it neutral-attractive.
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate into fewer bins as open-bin count grows.
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Near-perfect match: next item fits into post_residual with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.5;
    }

    // Dead space: post_residual too small for the next item (waste potential).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize residuals that no typical item (>= 10) could ever fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer filling bins with below-average residual (tighter bins first),
    // keeping loose bins available for future large items.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Early in the stream, be more willing to keep bins open (spread items);
    // later in the stream, close bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.15;

    // Mild penalty for using a brand-new bin when the stream is early.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small unusable dead space (residual too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward large usable residuals after placement
    if post_residual >= next_item_size && next_item_size > 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong bonus
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Next item nearly fits: mild penalty for wasting the slot
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins fit the item (tight fits exist)
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins
        score += 15.0 + (open_bins_count as f64 * 2.0);
        // If the item fits poorly anywhere else, opening a bin is more attractive:
        if post_residual == item_size || (item_size > bin_capacity / 2) {
            score -= 12.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins with residual above the mean (keeps balance, avoids fragmenting small bins)
    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.3;
    }

    // Mild preference for filling bins that are already quite full
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    // Large items: prefer biggest available space unless it's a near-perfect fit
    if item_size > 60 && post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress
    let mut score = pr * (1.0 + 1.5 * norm_pr * (0.5 + progress));

    // Smooth polynomial coupling of post_residual with progress
    score += 20.0 * norm_pr * norm_pr * (1.0 - progress) * (1.0 - progress);

    // Dead-space avoidance: residuals too small to ever be useful
    let useless = (20.0f64 - pr).max(0.0) / 20.0;
    score += 60.0 * useless * useless;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 15.0 * fit_ratio * (1.0 - fit_ratio) * 4.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: open fresh bins early, discourage late waste
    if bin_residual == bin_capacity {
        let early_bias = 1.0 - progress;
        score = 25.0 + 70.0 * early_bias * early_bias
            + (open_bins_count as f64) * 2.0
            - (mean_residual / cap) * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for bin congestion relative to mean residual
    score += (pr - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: mod classes on capacity
        let pr = post_residual;
        let class = pr % 10;
        // Residuals that are "useful" harmonic slots (multiples of 10, especially
        // ones matching typical item sizes 10..80) are more acceptable.
        let useful = (10..=80).step_by(10).any(|v| v == pr);
        if useful {
            score -= 30.0;
        } else if class == 0 {
            score -= 10.0;
        } else if pr < 10 {
            // tiny dead space is fine
            score -= 25.0;
        } else {
            // awkward dead space penalty grows with distance from multiple of 10
            score += (class as f64) * 1.5;
        }

        // Penalize large residual that no typical item could fill well
        if pr > 80 {
            score += 15.0;
        }

        // Lookahead coupling: if next item fits exactly in post_residual, big reward
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 500.0;
            } else if next_item_size <= pr {
                // next item still fits here: mild reward
                score -= 20.0;
                let slack = pr - next_item_size;
                if slack % 10 == 0 && slack <= 80 {
                    score -= 15.0;
                }
            } else {
                // next item won't fit here: penalize small residuals more
                score += (next_item_size - pr) as f64 * 0.5;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin
        if fitting_bins_count == 1 {
            score -= 40.0;
        } else if fitting_bins_count > 1 {
            // among many fitting bins, prefer tighter fits (already via post_residual)
            score += (fitting_bins_count as f64) * 2.0;
        }

        // Mean residual coupling: if this bin is far below mean residual (already tight),
        // reward it; loose bins get penalized.
        score += (mean_residual - bin_residual as f64) * 0.3;

        // Early stream: be more willing to spread into new bins; late stream: consolidate
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;

        // Too many open bins: discourage adding load to fresh bins, encourage consolidation
        if open_bins_count > 4 {
            score += (open_bins_count as f64) * 0.5;
        }
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit
    if bin_residual == bin_capacity {
        let decent = post_residual == 0 || (next_item_size > 0 && next_item_size == post_residual);
        if decent {
            score -= 20.0;
        } else {
            score += 120.0 + (open_bins_count as f64) * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // any plausible item are pure waste. Penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below minimum item size
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit, zero waste
    }

    // Penalize moderately small gaps that few item sizes can use.
    if post_residual > 0 && post_residual < 20 {
        score += 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit post residual and post residual is small, penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Prefer bins with residuals below the mean residual (tighter bins first).
    score += 0.3 * ((mean_residual - bin_residual as f64).abs());

    // Mild preference for keeping large residual bins for large future items.
    if post_residual > 60 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
