pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    score -= (bin_residual as f64 - post_residual as f64).powi(2) / bin_capacity as f64;

    // Penalize large dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.7;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + next_item_size as f64 * 0.1;
        } else if post_residual > 0 && post_residual < 10 {
            // Small dead space that likely can't fit anything: penalize.
            score += 6.0;
        }
    }

    // New-bin candidate handling: neutral baseline, penalize unless open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (fitting_bins_count == 0) as f64 * 30.0;
        // Opening new bins is fine early, discouraged late if any bin fits.
        score = 55.0 + progress * 15.0 - crowded;
        if item_size > 60 {
            score -= 10.0; // big items benefit from fresh bins
        }
    }

    // Mild preference to fill bins with many open bins (consolidation).
    score += open_bins_count as f64 * 0.15 * (post_residual as f64 / bin_capacity as f64);

    // Time-horizon adaptation: later in stream, prioritize exact fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, residual space is worth more (penalize waste more).
    let progress_weight = 1.0 + progress * progress * (1.0 - progress) * 4.0;
    score *= progress_weight;

    // Reward tight fits: subtract a smooth function of fill ratio.
    let fill = 1.0 - pr / cap;
    score -= (fill * fill * fill) * cap * 0.5;

    // Penalize leaving residuals that are hard to fill (small post_residual bands
    // relative to typical item sizes) via smooth bell-like term.
    let dead = (pr / cap - 0.5) * (pr / cap - 0.5);
    score += dead * cap * 0.25;

    // Lookahead coupling: if next item fits the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (1.0 - (pr - nxt) / cap) * cap * 0.3;
        } else {
            let over = (nxt - pr) / cap;
            score += over * over * cap * 0.2;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.6;
    }

    // New-bin candidate: mildly penalize opening new bins when many bins are open,
    // unless it's early in the stream where consolidation matters less.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += cap * (0.1 + 0.05 * open_pressure) * (0.5 + progress);
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * cap * 0.1 - dev * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small residue classes is worse.
    let pr = post_residual as u32;
    let class: f64 = if pr == 0 {
        -40.0 // perfect fit: strong reward
    } else if pr < 10 {
        25.0 // tiny dead space, nearly unusable
    } else if pr % 10 == 0 {
        -10.0 // clean decade residue: highly reusable
    } else if pr % 5 == 0 {
        -4.0
    } else {
        3.0 * ((pr % 5) as f64)
    };
    score += class;

    // Integer-division threshold: residue usable by typical next items
    let usable_quotient = pr / 20; // how many 20-sized items still fit
    score -= 6.0 * usable_quotient as f64;

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // harmonic bonus when next item exactly divides residue
            if pr % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: penalize leaving awkward residue
            let overshoot = (next_item_size - pr) as f64;
            score += 0.15 * overshoot;
        }
    }

    // Capacity fraction of current item: large items prefer tight fits
    let item_frac = item_size as f64 / cap;
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_frac * (0.5 + 0.5 * item_frac);

    // Last-chance bin: avoid forcing a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bin is very full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) / (total_items.max(1) as f64 * 0.05);
        score += 18.0 - 10.0 * progress - 5.0 * pressure.min(2.0);
        // but prefer new bin if item is huge and mean residual is small
        if item_frac > 0.7 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Slight preference for bins deviating from mean residual (diversity of classes)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be usable
    // later are heavily penalized. Anything below the minimum item size (1)
    // is perfect; residuals in a "dead zone" (too small for typical items)
    // are punished super-linearly.
    let dead_threshold = 10.0; // smallest historical item size
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Non-linear penalty on mid-range dead space: residuals that few item
    // sizes can fill are worse than large residuals that remain flexible.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 30.0 {
        score += (30.0 - pr) * (30.0 - pr) * 0.05;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Open-bins pressure: discourage spreading across many bins when
        // alternatives exist.
        score += open_bins_count as f64 * 0.8;
    }

    // Prefer bins whose residual is below the mean (consolidating fullness).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward leaving that gap; otherwise penalize blocking the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: an empty bin has high residual; make it
    // moderately attractive only when the current fit would create large
    // dead space or when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
        score = pr + 20.0 - congestion * 2.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // pairing lookahead items in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: squash post_residual advantage when it is tiny.
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        if nxt <= post {
            // Next item fits exactly in the leftover space: strong reward.
            if gap <= 2.0 {
                score -= 30.0;
            } else if gap <= 8.0 {
                score -= 15.0;
            } else {
                score -= 10.0 * (1.0 - gap / post.max(1.0));
            }
        } else {
            // Next item won't fit here; penalize proportionally to overshoot.
            score += 5.0 + 0.15 * (nxt - post);
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize leaving very small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 8.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste * waste;

    // Strongly reward perfect or near-perfect closure of a bin.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward leaving that space; otherwise penalize unusable dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            // Dead space the next item cannot use: penalize more if residual is small.
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate handling: opening a new bin is expensive early,
    // cheaper late when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64).ln().max(0.0);
        let mean_gap = (mean_residual - post_residual as f64).abs();
        let penalty = 35.0 - 20.0 * progress + 4.0 * fragmentation - 0.15 * mean_gap;
        score += penalty.max(0.0);
    }

    // Prefer bins whose residual is close to the mean (balance load),
    // slightly stronger as the stream progresses.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev * (0.5 + progress);

    // Mild preference for fuller bins as stream nears its end.
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let post_norm = post / cap;
    let p2 = post_norm * post_norm;
    let p3 = p2 * post_norm;
    // Early stream: favor tight fits (low post_residual); late stream: tolerate larger residuals.
    let coupling = p3 - 1.5 * p2 * progress + 0.6 * post_norm * progress * progress;
    score += 20.0 * coupling;

    // Penalize residuals that no plausible next item can use (dead space), smoothly.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let waste = ((nxt - post).max(0.0)) / cap;
        score += 15.0 * waste * waste;
        // Reward leaving room exactly for the lookahead item.
        let match_gap = (post - nxt).abs() / cap;
        score -= 10.0 * (1.0 - match_gap).max(0.0) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild preference toward consolidating into fuller bins relative to mean residual.
    score -= 5.0 * (mean_residual - post) / cap;

    // Penalize opening new bins as stream progresses (smooth term).
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (8.0 + 12.0 * progress * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo structure of the capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residuals that are multiples of common item sizes
    // (or near-harmonic fractions of capacity) are more reusable.
    let mut harmonic_bonus = 0.0;
    for &h in &[10u32, 20, 25, 50] {
        if post_residual % h == 0 && post_residual > 0 {
            harmonic_bonus += 15.0;
        }
    }
    score -= harmonic_bonus;

    // Fractional capacity thresholds: small residuals (< 10) are dead space
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Coupling with next item: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            // reward proportional to tightness of the follow-up fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += 0.1 * pr;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer bins tighter than average (best-fit style, modulated by progress)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * (pr - mean_residual) * (0.5 + 0.5 * progress);

    // Slight preference for reusing open bins vs opening new ones
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    }

    // Integer-division threshold: residuals in [50, 99] keep half-bin utility
    if post_residual >= bin_capacity / 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual below ~10 cannot hold any item (sizes >= 1, but typical min 10);
    // treat residuals in the "dead zone" as wasted capacity.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Soft penalty for awkward mid-range gaps that few items can fill.
    if post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    // Reward tight fits (low post residual relative to item size).
    let tightness = (post_residual as f64) / (item_size.max(1) as f64);
    score += tightness * 4.0;

    // Open-bin pressure: penalize placements that leave bins open with large residuals,
    // encourage consolidation when many bins are open.
    let pressure = open_bins_count as f64 / 10.0;
    score += mean_residual * 0.05 * pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when open bins fit poorly.
        score += 25.0;
        // If the item leaves a good usable gap for the lookahead item, discount slightly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // Late in the stream, avoid opening new bins unnecessarily.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 10.0;
        }
    }

    // Lookahead synergy: reward placements where the post residual accommodates
    // the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else if post_residual > 0 {
            // post residual too small for next item: mild dead-space penalty
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit wins (post_residual already small => good).
    // Normalize dead space relative to capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.5 * (pr * pr) / cap;

    // Aggressive 2-step lookahead: strongly reward if the next item fits
    // exactly into the post-residual (perfect chain), mildly if it fits at all.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - pr).abs() < 1.0 {
            score -= 40.0; // perfect chained fit
        } else if ni <= pr {
            score -= 12.0 * (1.0 - (pr - ni) / cap); // fits with small slack
        } else {
            // next item cannot use the leftover: dead space penalty grows
            score += 6.0 * (pr / cap);
        }
    } else {
        // Last item: prefer zero-waste placements
        score += 0.0;
    }

    // Compare bin residual to mean residual across open bins:
    // prefer bins whose residual is below-average (use up scarce space)
    // but avoid leaving a tiny unusable residual.
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // near-unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, slightly discourage scattering into many bins
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large relative to typical residuals (poor fit elsewhere likely).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64) > mean_residual.max(20.0);
        if large_item {
            score -= 20.0 + 10.0 * progress; // open fresh bin for big items
        } else {
            score += 35.0; // discourage opening bins for small items
        }
    }

    // Mild encouragement to keep bin count low: favor already-open bins
    // slightly more as stream progresses.
    score -= 2.0 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = if item_size > 0 {
        (item_size as f64) / (bin_residual as f64)
    } else {
        1.0
    };
    score -= tightness * 12.0;

    // Penalize dead space: post_residual too small to ever be useful
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // next item would need a new bin anyway; slight penalty for wasting chain
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins among many open bins (first-fit-like bias)
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * 10.0;

    // Time horizon: early in stream, be more willing to open new bins (exploration);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 15.0 + 25.0 * progress;
        // But early on, if item is large and mean residual is low, opening is fine
        if (item_size as f64) > mean_residual * 0.8 && progress < 0.3 {
            score -= 20.0;
        }
    } else {
        // Existing bin: reward more heavily late in the stream
        score -= 8.0 * progress;
    }

    // Many open bins: encourage consolidation
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    // Mean residual coupling: if this bin's residual is below mean, it's a good target
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // on dead space that grows as the stream progresses.
    let mut score = pr + (pr / cap).powi(2) * (cap * (0.25 + 1.25 * progress));

    // Tight fits (small post_residual relative to item) are rewarded more later.
    let tightness = 1.0 - pr / bin_residual.max(1) as f64;
    score -= tightness * fit * cap * (0.3 + 0.7 * progress);

    // Lookahead: reward leaving room for the next item; penalize when the
    // leftover space is just slightly too small (wasted near-miss).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= (pr - nx) / cap * cap * 0.15 * (1.0 - progress);
        } else {
            score += (nx - pr) / cap * cap * 0.25 * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 0.6 * (0.5 + 0.5 * progress);
    }

    // Crowding: with many open bins, prefer consolidating into low-residual bins.
    let crowd = (open_bins_count as f64 / (total_items.max(1) as f64)).min(1.0);
    score += (pr / cap) * cap * 0.2 * crowd;

    // Mean residual coupling: bins far below mean residual are better targets
    // for large items; bins above mean are better for small items.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * fit * cap * 0.3;

    // New-bin candidate: keep it attractive only when the item is large
    // relative to typical residuals or early in the stream.
    if bin_residual == bin_capacity {
        let openness = (1.0 - progress) * 0.4 + fit * 0.5 + crowd * 0.3;
        score = cap * (1.0 - openness.min(1.0)) + pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 classes capture "clean" fits.
    let post_class = post_residual % 10;
    let class_bonus = match post_class {
        0 => 25.0,           // perfect harmonic fit, dead space is reusable
        5 => 12.0,           // half-class, still flexible
        1 | 9 => 6.0,
        2 | 8 => 3.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: residual buckets by quarters of capacity.
    let quarter = bin_capacity / 4;
    let bucket = post_residual / quarter;
    score -= match bucket {
        0 => 18.0,  // residual < 25: nearly full bin, good
        1 => 8.0,
        2 => 0.0,
        3 => -4.0,  // large residual left: mild penalty for wasting space
        _ => 0.0,
    };

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; if this is the last fitting bin, keep it open cheaply
            score += 5.0;
        }
        // harmonic pairing: post_residual + next item leaves a mod-10 clean class
        if next_item_size <= post_residual && (post_residual - next_item_size) % 10 == 0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * 0.6 + mean_residual / 10.0;
        let poor_fit = if post_residual == 0 { 0.0 } else { 0.0 };
        score += 15.0 - crowded.min(15.0) + poor_fit;
        // early stream: opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Slight pressure to reduce open-bin count spread.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly unusable
    // dead space, penalize them hard; large gaps are still useful.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 - 3.0 * post_residual as f64;
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 50.0;
    }

    // Reward tight fits (item occupies most of the residual)
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can exactly fill this bin's post_residual,
    // reward placing the current item here; if next item would waste the gap, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 12.0;
        }
    }

    // Slight preference for bins tighter than average (consolidate small residuals)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer closing out with tight packing
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect 2-step fill bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Penalize large post-residual relative to mean residual (wasting usable space)
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.8 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize tiny dead space that can't fit typical items
    if pr > 0.0 && pr < 10.0 {
        score += 12.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for tighter bins overall
    score += 0.1 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: mildly reward leaving usable room
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize proportionally to leftover waste
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // When many bins are open, prefer consolidating into bins below mean residual
    // (i.e., fill fuller-than-average bins first).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 10.0 * dev;
    }

    // Time horizon: early in stream, be picky (penalize mediocre fits);
    // late in stream, accept fits more readily to close bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * (1.0 - progress);
    score -= 5.0 * progress * tightness;

    // New-bin candidate: make it moderately attractive only when the item is large
    // and no open bin offers a good fit; otherwise keep it expensive.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_alternatives = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = (bin_capacity as f64 - item_size as f64) * (1.2 - 0.4 * large_item)
            - 15.0 * poor_alternatives
            + 10.0 * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;

    // Base: post residual, non-linearly shaped by stream progress.
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.8 * progress * pr_norm);

    // Smooth quadratic coupling of post_residual with progress: late in the
    // stream, small residuals are penalized more (dead space matters more).
    score += 12.0 * (pr_norm * pr_norm) * (0.5 + progress);

    // Reward tight fits: sigmoid-like smooth term on fill ratio.
    let fill = 1.0 - pr_norm;
    score -= 10.0 * fill * fill * (1.0 - progress * 0.5);

    // Lookahead: if next item fits the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0);
        let compat = 1.0 - (fits_next / cap);
        score -= 6.0 * compat * compat;
    }

    // Last-chance bin: smooth reward scaled by how crowded the bin set is.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual slightly (balance residuals smoothly).
    score += 0.05 * (res - mean_residual) * (1.0 + progress);

    // Mild penalty for opening many bins: new empty bin gets a smooth offset.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition residual space into residue classes mod 10.
    // Small post_residuals in "awkward" classes (not multiples of 10/5) are dead space.
    let class = post_residual % 10;
    let awkward = match class {
        0 => 0.0,
        5 => 0.4,
        _ => 0.8, // residues 1-4, 6-9 are hardest to fill later
    };
    score += awkward * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Perfect fit reward: post_residual exactly 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Class-aligned fit: post_residual divisible by 5 is a "harmonic" leftover.
    else if class == 5 {
        score -= 5.0;
    }

    // Penalize leaving residual smaller than the smallest plausible item (1..100 stream,
    // but tiny slivers under ~10 are near-dead).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // harmonic class of the gap after the lookahead placement
            let gap_class = gap % 10;
            score += match gap_class {
                0 => gap as f64 * 0.1,
                5 => gap as f64 * 0.3,
                _ => gap as f64 * 0.6,
            };
        } else {
            // next item cannot use this bin's leftover; penalize proportional leftover
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a bin wastes its full capacity potential;
    // only attractive when current bin would leave an awkward class and next item
    // would fit a fresh bin's harmonic structure better.
    if bin_residual == bin_capacity {
        // base cost of a new bin, discounted early in the stream and when open bins are fragmented
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 70.0 - 30.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin leaves (100 - item) which is fine if item is harmonic (multiple of 10)
            if item_size % 10 == 0 {
                new_bin_score -= 20.0;
            }
        }
        // if many bins already fit the item, opening another is wasteful
        new_bin_score += (fitting_bins_count as f64) * 8.0;
        score = new_bin_score + score * 0.05;
    }

    // Mild penalty for spreading across many bins when mean residual is high (fragmentation).
    if open_bins_count > 1 {
        let frag = (mean_residual - post_residual as f64).abs();
        score += frag * 0.05;
    }

    // Integer-division threshold: bins whose residual after placement falls in the
    // 10..=20 band (one more small item fits) are valuable.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 15.0;
    }

    // Reward residuals that can still host a typical next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.2;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 - open_bins_count as f64 * 0.3 - progress * 3.0;
    } else {
        // New-bin candidate: only attractive if mean residual across open bins is small.
        score += 20.0 + mean_residual * 0.5;
    }

    // Prefer bins tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 120.0 * fill;
        } else {
            // next item won't fit here; penalize leaving large dead space
            let dead = post_residual as f64;
            if dead > next_item_size as f64 {
                score += 0.5 * (dead - next_item_size as f64);
            }
        }
    }

    // Compare post_residual relative to mean residual: leaving below-average
    // residual means we consumed more of the bin's usefulness -> reward.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless item is huge.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 && item_size <= 70 {
            score += 80.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // late in stream, prefer packing into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress;
    }

    // Slight preference for tighter bins overall.
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64).sqrt();

    // Penalize wasteful dead space: small but nonzero post_residual is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // Next item still fits: mild reward proportional to slack left after.
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // Placing here breaks the next item's fit in this bin: mild penalty.
            score += 8.0;
        }
    }

    // New-bin candidate handling: empty bin should lose unless current fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 45.0;
        // More open bins -> cheaper to reuse existing ones relative to new bin.
        score += open_bins_count as f64 * 2.0;
        // Late in stream, opening new bins is less costly (fewer future items to strand).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * progress;
        // If mean residual is high, open bins have room; discourage new bin.
        score += 0.2 * mean_residual;
        // If item is large relative to capacity, new bin gives flexibility.
        score -= 0.1 * item_size as f64;
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor).
        score += 0.15 * (bin_residual - item_size) as f64;
        // Prefer using bins with lower residual overall (fill nearly-full bins first).
        score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Mild global regularization: keep score comparable across bins.
    score += 0.001 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer small post residual, softly damped as stream progresses
    let mut score = pr * (1.0 - 0.35 * progress);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, larger post residuals become increasingly costly
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Penalize post residual that cannot fit the (normalized) next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (nx - pr_norm).max(0.0);
        score += 25.0 * gap * gap;
        // Reward bins whose post residual still fits the next item
        if pr_norm >= nx {
            score -= 12.0 * (1.0 - (pr_norm - nx).abs());
        }
    } else {
        // Last item: minimize post residual strongly
        score += 30.0 * pr_norm * pr_norm;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - item_norm);
    }

    // Mild penalty proportional to crowdedness of the bin pool
    score += 0.15 * (open_bins_count as f64).ln();

    // Deviation from mean residual: prefer bins tighter than the average
    score += 0.2 * (pr - mean_residual);

    // Dead-space term: unusable slivers (< 10% capacity) get quadratic penalty
    if pr_norm < 0.10 && pr_norm > 0.0 {
        score += 15.0 * (0.10 - pr_norm) * (0.10 - pr_norm) * 100.0;
    }

    // New-bin candidate: neutral baseline, slightly worse than good fits but
    // better than terrible ones, so a fresh bin is chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small" residue classes are more likely to become dead space.
    let pr = post_residual;
    let class = pr / 10; // integer division: 0..10 harmonic bands
    match class {
        0 => score -= 30.0,                     // near-perfect fit, strongly reward
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        4 => score += 2.0,
        5 => score += 6.0,                      // half-full leftover: mediocre
        6 => score += 8.0,
        7 => score += 10.0,
        8 => score += 12.0,
        9 => score += 6.0,                      // large residual still fairly usable
        _ => score -= 25.0,                     // untouched bin (new-bin candidate)
    }

    // Modulo-2 coupling: even post_residuals pair better with typical even items.
    if pr % 2 == 0 { score -= 1.5; }

    // Lookahead: does next item fit exactly into post_residual? Big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // how well the next item divides the leftover (harmonic fit)
            let slack = pr - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / cap);
            if slack % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this leftover at all: penalize large leftovers
            score += (pr as f64) * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item is huge relative to residual.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let big_item = item_size as f64 / cap;
        score = cap * (0.35 + 0.65 * crowd) - 20.0 * big_item;
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0; // item + next won't share anyway; fresh bin ok
        }
    }

    // Stream-phase modulation: late in the stream, prefer closing bins tight.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * phase * (post_residual as f64 / cap);

    // Mean-residual anchor: penalize bins far from the mean residual (outliers).
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose leftover can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > 0 {
        // leftover unusable for the next item: penalize proportionally
        score += 0.25 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        // But if the fit creates a tiny dead gap, soften the bonus.
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        score += 40.0 - pressure.min(40.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        }
    }

    // Open-bin pressure: mild penalty scaling with number of open bins to consolidate.
    score += 0.15 * open_bins_count as f64;

    // Slight preference for tighter fits relative to bin residual.
    score -= 0.10 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-item match: nearly zero waste after next step.
            score -= 40.0;
        } else if post_residual > next_item_size {
            let slack_after_next = (post_residual - next_item_size) as f64;
            // Small slack after next item is good; large slack is dead space.
            score -= 25.0 * (-slack_after_next / 15.0).exp();
            score += 0.3 * slack_after_next;
        } else {
            // Next item won't fit: penalize proportional to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot;
        }
    }

    // Relative-to-mean coupling: bins tighter than mean are good targets.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is truly dead.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in stream, be more willing to open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 30.0 * (1.0 - progress);
        }
        // If next item is large and current item small, a fresh bin can be attractive.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 25.0;
        }
    }

    // Slight preference to fill tighter bins harder (small post_residual).
    score += 0.1 * (post_residual as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize creating dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly prefer using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate logic: only attractive when existing fit is poor
    // and the lookahead item may benefit from a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fit_ratio < 0.5;
        let lookahead_benefit = next_item_size > 0 && (bin_residual - item_size) >= next_item_size;
        if poor_fit {
            score -= 20.0 + 15.0 * progress;
        }
        if lookahead_benefit {
            score -= 18.0;
        }
        // Discard new-bin option when plenty of bins fit the item well.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        // Early stream: opening bins is cheaper; late stream: consolidate.
        score += 20.0 * (1.0 - progress);
    }

    // Prefer bins with residual close to the item (best-fit flavor).
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * residual_gap;

    // Mean-residual coupling: when average residual is large, waste matters less;
    // when small, be frugal and avoid fragmenting scarce space.
    score += 0.2 * (mean_residual - post_residual as f64).abs();

    // Lookahead synergy: reward leaving exactly room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // stranded space relative to lookahead
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    let coupling = norm_pr * (1.0 + 2.0 * progress) + 3.0 * poly * (0.5 + progress);

    let mut score = pr + coupling * cap * 0.1;

    // Penalize tight fits when lookahead item won't use the space
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0);
        score += waste * (0.05 + 0.1 * progress);
    }

    // Last-chance bonus: only one bin fits -> strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mild penalty for opening a new bin when alternatives exist
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    // Reward bins deviating from mean residual (consolidate slack)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    // Reward residuals that sit just above harmonic thresholds (usable by mid-size items)
    if class == 0 && post_residual > 0 {
        score -= 8.0;
    } else if class < 10 {
        score += 4.0; // dead-space band: small unusable sliver
    }

    // Lookahead: strongly reward if next item fits exactly or well in post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 15.0 - (slack as f64).min(15.0);
        if slack == 0 {
            score -= 25.0; // perfect two-item packing
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize wasting tight residual
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Tight fit reward: item nearly fills the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 12.0;
    } else if fill_ratio < 0.3 && bin_residual < bin_capacity {
        score += 5.0; // poor use of an already-open bin
    }

    // Integer-division threshold on post_residual: residuals in [10,30] are prime dead space
    if post_residual >= 10 && post_residual <= 30 {
        score += 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or mean residual is low
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = bin_capacity as f64 * 0.5 + pressure * 5.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // room for pairing in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than large ones.
    // A residual that cannot fit even the smallest plausible item (or the lookahead item)
    // is "dead space" — penalize it super-linearly.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(20) } else { 12 };
    if (post_residual as f64) < dead_threshold as f64 {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }
    // Bonus for residuals that can still host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Perfect fit for the next item is highly desirable.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // Exact fit now is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many bins fit, to prefer tighter fits among them.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Open-bin pressure: discourage spreading across too many bins when residuals
    // are still large; encourage using existing bins when they are nearly full.
    let mean_frac = mean_residual / bin_capacity as f64;
    if mean_frac < 0.25 {
        score += open_bins_count as f64 * 2.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: only open a new bin when the item is large and
    // existing residuals are poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let post = (bin_capacity - item_size) as f64;
        // Opening a new bin is attractive if it leaves a large, flexible residual
        // and current bins are fragmented.
        score = post * 0.9 + open_bins_count as f64 * 3.0;
        if item_size >= 50 {
            score -= 10.0;
        }
        if post < 20.0 {
            score += 40.0; // avoid new bins that immediately become dead space
        }
    }

    // Stream progression: early on, be more willing to open bins / keep flexibility;
    // later, squeeze into existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item won't fit here afterwards; mild penalty for creating dead space
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: minimize leftover
        score += post_residual as f64 * 0.2;
    }

    // Penalize unusable dead space (small residual that likely fits nothing)
    if post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than average (better packing density)
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference to fill existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // New-bin candidate: make empty bins less attractive unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: tighter fit preferred (already via post_residual).

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that is hard to reuse for typical items (>= ~10)
        if post_residual < 10 {
            score += 25.0;
        }
        // Reward residual that could still fit a plausible future item
        score -= (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead need
        score += 8.0;
    }

    // Last chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate logic: prefer opening a fresh bin when current fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Fresh bin baseline: attractive if existing fit is very loose
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio < 0.55 {
            score -= 55.0 * (0.55 - fit_ratio);
        } else {
            // Discard new bin when a decent fit exists elsewhere
            score += 30.0 + fit_ratio * 40.0;
        }
        // Early in stream, new bins are cheap; late, prefer consolidation
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += t * 15.0;
    }

    // Prefer bins below mean residual (keeps residuals balanced, avoids fragmentation)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.35;

    // Slight preference for using already-open bins over creating more
    if !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: strong preference for tight fits (small post_residual), non-linear
    let mut score = 4.0 * x - 6.0 * x * x + 3.0 * x * x * x;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits (keep bins flexible); late, demand tightness.
    let coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += (1.0 - progress) * 2.0 * x * x - progress * 3.0 * x * x;

    // Dead-space penalty: post_residual too small to be useful for typical items
    let dead = if post_residual > 0 && post_residual < 10 { 5.0 } else { 0.0 };
    score += dead;

    // Waste term relative to mean residual of open bins
    score += 0.5 * (post - mean_residual / open_bins_count.max(1) as f64).abs() / cap;

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 1.5 * (1.0 - (post - nx) / cap);
        } else {
            score += 0.5 * (nx - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin, but relax when no good fit exists
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let worst_open = if open_bins_count > 0 { mean_residual / open_bins_count as f64 } else { cap };
        let slack = (worst_open - item_size as f64).max(0.0) / cap;
        score += cap * pressure * (1.0 - 0.8 * slack) * (0.5 + 0.5 * (1.0 - progress));
        // early stream: opening bins is cheaper to keep flexibility
        score -= (1.0 - progress) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // granularities are more reusable than odd "dead" remainders.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus -= 40.0; // perfect closure
    } else if pr % 10 == 0 {
        class_bonus -= 12.0;
    } else if pr % 5 == 0 {
        class_bonus -= 6.0;
    } else if pr < 10 {
        class_bonus += 25.0; // dead space: nothing can ever fit
    } else {
        class_bonus += (pr % 5) as f64 * 2.0; // odd remainders penalized
    }
    score += class_bonus;

    // Lookahead coupling: does post_residual exactly host the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize so it's only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    // Tight fit reward.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Late in stream: consolidate, avoid spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Dead-space penalty: residuals that are too small for typical future items
    // (below the minimum plausible item size region) are "dead space".
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if the lookahead item cannot fit the post residual (wasted potential),
    // but only mildly, since the item after next may differ.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward if lookahead fits comfortably after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when the item
    // is large or existing bins would leave very fragmented space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Mild baseline cost so we prefer reusing open bins with good fits.
        score += 10.0;
        // Pressure grows with number of open bins: discourage opening more bins
        // when many are already open.
        score += open_bins_count as f64 * 1.5;
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
        // If no open bin fits well (this is the only fitter and it is empty),
        // opening is natural; reduce penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Reusing an open bin reduces open-bin pressure slightly.
        score -= 2.0;
        // Slight penalty for using bins whose residual is far above the mean
        // (keeps a portfolio of diverse residuals for future items).
        if (bin_residual as f64 - mean_residual).abs() > 30.0 {
            score += 3.0;
        }
    }

    // Late-stream effect: as the stream progresses, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= progress * 5.0;
    } else {
        score += progress * 8.0;
    }

    // Fragmentation guard: placing into a bin leaving residual in the awkward
    // 1..=9 zone is worse than a moderately sized residual.
    if post_residual >= 1 && post_residual <= 9 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly matches next item -> strong reward
            let gap = (post_residual - next_item_size) as f64;
            let perfect = if gap == 0.0 { 60.0 } else { 25.0 };
            score -= perfect - 0.15 * gap; // smaller gap => bigger reward
        } else {
            // Dead space: next item cannot use the remainder
            score += 20.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize leftover
        score += 0.0;
    }

    // Penalize very small unusable leftovers (< 10, min item size)
    if post_residual < 10 {
        score += 15.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Relative-to-mean adjustment: bins tighter than average are more valuable
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Slight late-stream preference to consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: keep it neutral-to-slightly-penalized so it only wins
    // when open bins would create dead space (large scores above)
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: item fills most of the bin's remaining space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Strong reward for near-perfect packing (post_residual very small).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.15 * slack.min(50.0);
        } else {
            // Dead space for the lookahead item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.2 * gap.min(80.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins far below the mean residual (wasteful choice when other
    // bins are emptier), mildly weighted by how many bins are open.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.1 * dev * (1.0 + open_bins_count as f64 * 0.05);
    }

    // Early in the stream, be more conservative about filling bins deeply
    // (keep flexibility); late in the stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio;

    // New-bin candidate: bin_residual == bin_capacity means an empty bin.
    // Make opening a new bin expensive unless it yields a very tight fit
    // (large items nearly filling a fresh bin) or no other bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 60.0 + 0.5 * open_bins_count as f64;
        let tight_gain = if item_size as f64 / bin_capacity as f64 > 0.85 { 70.0 } else { 0.0 };
        score += base_penalty - tight_gain;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: reward tight fits (small post residual), smoothed polynomial decay
    let mut score = x * x * (3.0 - 2.0 * x) * 20.0 + pr * 0.5;

    // Non-linear interaction between post-residual and stream progress:
    // later in stream, penalize waste more strongly
    score += 30.0 * x * x * progress;

    // Penalize dead space unusable by next item (smooth coupling)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 10.0 * (gap / cap) * (gap / cap) * (1.0 - progress);
    } else {
        // last item: strongly reward filling existing bins
        score -= 50.0 * (1.0 - x);
    }

    // Last-chance bin bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: neutral-ish, slightly favored early, penalized late
    if bin_residual == bin_capacity {
        score = 40.0 + 60.0 * progress - 10.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "dead space classes".
    let r = post_residual % 10;
    // Residue 0 is perfect packing; small residues are wasteful.
    let residue_penalty = match r {
        0 => -12.0,
        1 | 9 => 6.0,
        2 | 8 => 4.0,
        3 | 7 => 2.5,
        4 | 6 => 1.5,
        _ => 0.0,
    };
    score += residue_penalty;

    // Integer-division thresholds: how many "next item" slots fit in post_residual.
    if next_item_size > 0 && next_item_size <= bin_capacity {
        let slots = post_residual / next_item_size;
        if slots >= 1 {
            // Reward bins that can host the next item too (chain-friendly).
            score -= 5.0 + 2.0 * (slots.min(3) as f64);
        } else {
            // Post-residual cannot host next item: dead space unless it's tiny.
            score += 4.0;
        }
        // Exact fit for next item: strong reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins when existing mean residual is generous.
        score += 10.0 + 30.0 * pressure;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Tight-fit bonus: near-exhausting the bin is excellent.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    if fill_frac > 0.9 {
        score -= 8.0;
    } else if fill_frac < 0.3 {
        score += 3.0;
    }

    // Harmonic coupling: capacity fraction classes of item size.
    let cap_class = item_size / (bin_capacity / 4); // quarter classes
    score -= match cap_class {
        0 => 1.0,
        1 => 2.0,
        2 => 3.0,
        _ => 4.0,
    };

    // Penalize leaving residuals in the awkward 1..=9 band beyond residue penalty.
    if post_residual >= 1 && post_residual <= 9 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        // Dead space: penalize strongly, worse the closer to a perfect fill it "wasted"
        let waste = (dead_threshold - post_residual) as f64;
        score += 40.0 + 6.0 * waste;
    } else if post_residual == 0 {
        // Perfect fill: big reward
        score -= 60.0;
    } else {
        // Usable residual: mildly reward leaving room for likely future items
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 15.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit creates dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual == 0 || post_residual >= dead_threshold {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: make a fresh bin attractive only when the
    // item fits poorly everywhere else (large item, many open bins with high mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) < 15.0; // item barely fits in a fresh bin => huge item
        if poor_fit {
            score -= 30.0; // must open a new bin anyway
        } else {
            // Pressure: penalize opening new bins as open bin count grows
            score += 10.0 + 1.5 * open_bins_count as f64 * (0.5 + progress);
            // If mean residual across open bins is large, prefer reusing them
            score += 0.3 * mean_residual;
        }
    }

    // Mild global pressure: with many open bins, favor consolidation into existing bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual slightly larger than next item: still good, reward proximity.
        let gap = (post_residual - next_item_size) as f64;
        score -= (30.0 * (-gap / 25.0).exp()).max(0.0);
    } else if next_item_size > 0 {
        // Post residual too small for next item: dead space penalty scaled by waste.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.35 * waste;
    }

    // Penalize tiny unusable remainders (dead space < 10).
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (good fits cluster).
    score += 0.2 * (post_residual as f64 - mean_residual);

    // Slight bias toward filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += if fitting_bins_count == 0 { 0.0 } else { 40.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that likely can't be used by future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 {
        let waste = post_residual as f64;
        score += 0.5 * waste * (1.0 - 0.5 * progress);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item would fit the post residual exactly, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use leftover; penalize proportional waste.
            score += 0.3 * (post_residual as f64) * (1.0 - progress);
        }
    }

    // Prefer bins with residual below mean residual (tighter bins get priority),
    // unless this bin is nearly full.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Mild penalty for spreading across many open bins; encourage consolidation
    // early, allow more bins late.
    score += (open_bins_count as f64).sqrt() * 0.4 * (1.0 - progress);

    // New empty bin candidate: penalize unless no good fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If nothing else fits, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in stream, opening new bins is cheaper than fragmenting.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr * norm_pr)
                  - 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic coupling)
    let dead = (pr - mean_residual) / cap;
    score += 5.0 * dead * dead.abs();

    // Lookahead coupling: reward if next item fits in post residual (smooth logistic)
    if next_item_size > 0 {
        let fits = (post_residual as f64 - next_item_size as f64).max(0.0) / cap;
        score -= 10.0 * (1.0 - (-fits * 4.0).exp());
    }

    // Last-chance bin bonus: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight penalty for many open bins (encourage consolidation early)
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: neutral-ish baseline with progress-dependent bias
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) - 5.0 * (1.0 - norm_pr);
        if fitting_bins_count == 1 {
            score += 20.0; // discourage new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that partition nicely
    // into the common small-item classes (multiples of 10, and small primes).
    let pr = post_residual;
    if pr > 0 {
        // Perfect zero-waste fit is heavily rewarded.
        if pr == 0 {
            score -= 1000.0;
        }
        // Dead-space penalty: residuals in awkward classes (1..10) are nearly unusable.
        if pr < 10 {
            score += 60.0 * (10 - pr) as f64;
        }
        // Harmonic bonus: residuals divisible by 10 or 5 can host future standard items.
        if pr % 10 == 0 {
            score -= 25.0;
        } else if pr % 5 == 0 {
            score -= 12.0;
        }
        // Integer-division thresholds: classify residual by decile; prefer small deciles.
        let decile = pr / 10;
        score += decile as f64 * 4.0;

        // Modulo-3 style coupling with item size: residuals matching item's harmonic
        // complement are more likely to be filled later.
        if pr % item_size.max(1) == 0 {
            score -= 8.0;
        }
    } else {
        // Exact fill: perfect packing.
        score -= 1000.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves another residual: mild reward scaled by tightness.
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder: penalize dead space.
            score += 10.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins are very full or none fit well.
    if bin_residual == bin_capacity {
        // Base penalty to prefer reusing open bins; relax as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 55.0 - 20.0 * progress;
        // If the item would leave a bad residual in existing bins, new bin looks better.
        if post_residual < 15 {
            new_bin_score -= 30.0;
        }
        // If mean residual across open bins is small, reuse is hard; new bin cheaper.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 25.0;
        // Many open bins: discourage opening more.
        new_bin_score += open_bins_count as f64 * 2.0;
        score += new_bin_score;
    }

    // Tight fit reward: item fills a large fraction of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Mean-residual coupling: placing into a bin whose residual is far from the mean
    // helps rebalance the pool of open bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the smallest
    // plausible item are pure waste; penalize them quadratically.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 500.0;
    } else if post_residual <= 10 {
        // tiny gap likely unusable: strong penalty
        score += (11 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        score += (21 - post_residual) as f64 * 2.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 40.0;
    }
    // Penalize if placing here leaves a gap that blocks the next item while
    // other slack exists elsewhere.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (penalize the empty-bin candidate implicitly by rewarding reuse).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure term, softened when
        // the item is large relative to typical residual space.
        score += 150.0 + bin_pressure * 20.0 - (item_size as f64 * 0.3);
        // Opening a new bin is fine if it would leave a huge usable gap
        // elsewhere but this bin would be wasted anyway.
        if mean_residual < item_size as f64 {
            score -= 60.0;
        }
    } else {
        // Reuse reward scaled by how well residual matches item.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 30.0;
        // Mild bias toward bins with lower residual (fill fullest bins first).
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Exact match for the next item is very desirable
        if post_residual == next_item_size {
            score -= 120.0;
        }
        // Penalize leaving dead space that the next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.8 * post_residual as f64;
        }
    } else {
        // Last item: prefer minimal waste
        score += 0.5 * post_residual as f64;
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins could reasonably fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0;
    }

    // Slight preference to fill older bins as the stream progresses
    score += 0.05 * (step_index as f64 / (total_items.max(1) as f64)) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty (dead space grows quadratically bad).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize mildly, unless current bin fit is terrible
    // or the next item pairs well with a fresh bin.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 18.0;
        // If item leaves large unusable residue in any open bin anyway, new bin is fine.
        if post_residual == 0 {
            new_bin_penalty -= 20.0;
        }
        // Lookahead: if next item fits exactly in a fresh bin alongside this one, encourage opening.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover < 10 {
                new_bin_penalty -= 22.0;
            }
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty += 15.0 * progress;
        // Many open bins: discourage one more.
        new_bin_penalty += (open_bins_count as f64).ln().max(0.0) * 3.0;
        score += new_bin_penalty;
    }

    // Lookahead synergy: favor bins whose post-residual fits the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < 10 {
            score -= 10.0;
        }
    }

    // Penalize bins whose residual deviates far from the mean (keeps residual profile balanced).
    score += ((post_residual as f64 - mean_residual) / (bin_capacity as f64)).abs() * 10.0;

    // Prefer fuller bins (small residual) in general.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 30.0 * coupling;

    // Penalize tight fits less as stream advances (favor filling old bins)
    let tight_fit = 1.0 - norm_pr;
    score -= tight_fit * tight_fit * (20.0 + 40.0 * progress);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: penalize leaving residual close to next item size
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        score -= 15.0 * (1.0 - gap / cap);
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / cap;
    score += 40.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: residues mod small moduli reveal
    // "dead zones" of leftover space that few item sizes can reuse.
    let pr = post_residual;
    let mod5 = (pr % 5) as f64;
    let mod10 = (pr % 10) as f64;
    let mod20 = (pr % 20) as f64;

    // Residues near 0 mod 5/10 mean leftover divisible into common chunks -> reward.
    score -= 6.0 * (1.0 - mod5 / 4.0).max(0.0);
    score -= 4.0 * (1.0 - mod10 / 9.0).max(0.0);

    // Integer-division thresholds on post_residual: leftover that can host
    // medium items (>=20) is valuable; tiny leftover (<10) is dead space.
    let can_host = pr / 20;
    score -= 8.0 * can_host.min(3) as f64;
    if pr < 10 && pr > 0 {
        score += 12.0; // penalize creating unusable slivers
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
            // Harmonic class of slack after hypothetical next placement
            let s_mod10 = ((pr - next_item_size) % 10) as f64;
            score -= 3.0 * (1.0 - s_mod10 / 9.0).max(0.0);
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or all fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        // Penalize new bins mildly; relax penalty for big items / poor fits elsewhere.
        let mut nb = 55.0 - 45.0 * item_frac;
        if fitting_bins_count == 0 { nb -= 60.0; } // no open bin fits -> must open
        if next_item_size > 0 && next_item_size as f64 / cap > 0.8 { nb += 10.0; }
        nb -= 10.0 * progress; // late in stream, consolidation matters more
        score += nb.max(-50.0);
    }

    // Mean residual context: if this bin is far below mean residual, it is
    // "closable" debris; using it up is good.
    let dev = mean_residual - post_residual as f64;
    score -= 2.0 * dev.max(0.0).min(30.0) / 10.0;

    // Progress modulation: early on, keep bins flexible (favor mid residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let ideal_residual = cap * (0.35 + 0.15 * progress);
    score += 0.3 * (post_residual as f64 - ideal_residual).abs() / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover; dead space penalty grows.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 2.0;
    } else {
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Progression: later in the stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when leftover space matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect chain: this item's leftover exactly fits the next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a sliver that nothing useful can occupy.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative fullness coupling with mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 10.0; // tighter than average: good consolidation
    }

    // Last-chance bin before opening a new one: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize large dead space (unusable residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size == item_size {
            score += 20.0; // avoid opening bin for a chain we could keep together
        }
        score += 15.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild late-stream consolidation pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is much larger than the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that future items (10..80) can't use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0 * (20 - post_residual) as f64 / 10.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + next_fit);
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // Next item won't fit here afterwards; slight penalty if it could have fit now.
        if next_item_size <= bin_residual {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more open to spreading load (keep flexibility);
    // late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    // Many open bins: encourage closing them out by filling them (reduce fragmentation).
    if open_bins_count > 3 {
        score -= 2.5 * (open_bins_count as f64).ln() * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average) to
    // preserve large average residuals for big future items.
    if mean_residual > 0.0 {
        score += 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // New-bin candidate (empty bin): only attractive when nothing fits well elsewhere.
    if bin_residual == bin_capacity {
        score += 14.0 + 6.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize leftover space, scaled by stream progress (later waste matters more)
    let mut score = post * (1.0 + 0.8 * progress);

    // Non-linear polynomial coupling of post_residual with progress:
    // mid-stream, strongly prefer tight fits (quadratic bowl on normalized fill)
    let fill = 1.0 - post / cap;
    let fill_curve = fill * fill * (3.0 - 2.0 * fill); // smoothstep-like
    score -= 12.0 * fill_curve * (0.4 + 0.6 * progress);

    // Penalize large dead space quadratically
    let dead = post / cap;
    score += 20.0 * dead * dead * (0.5 + progress);

    // Last-chance bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, less when item is large or stream is early
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 * (1.0 - item / cap) + 10.0 * progress;
        // encourage new bin if next item would benefit from fresh space
        if next_item_size > 0 && next_item_size > item {
            score -= 6.0 * (next_item_size as f64 / cap);
        }
    }

    // Lookahead: reward residual that still fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 4.0;
        }
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "useful"
    // residue classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // Reward post-residuals divisible by small harmonic steps (5,10,20,25)
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Penalize dead-space classes: tiny unusable leftovers
        if pr < 10 {
            score += (10 - pr) as f64 * 1.5;
        }
        // Integer-division threshold: leftover in [10, 25] can host small items
        if pr >= 10 && pr <= 25 {
            score -= 4.0;
        }
    } else {
        // Perfect fit
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let gap = (pr - next_item_size) as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        if pr == next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // New-bin candidate handling: make fresh bins attractive only when the
    // item fills a large harmonic fraction of the bin.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill >= 0.5 {
            score -= 10.0 + 10.0 * fill;
        } else {
            score += 15.0 * (1.0 - fill);
        }
        // Fewer open bins -> fresh bin cheaper
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer tighter bins relative to mean residual
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // Late in the stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Treat gaps that cannot fit the smallest plausible item as dead space.
        let dead = if post_residual < 10 { gap * 4.0 } else { 0.0 };
        // Slight super-linear penalty on any leftover to prefer tight fits.
        score += 0.6 * gap * gap / bin_capacity as f64;
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 10.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bins have poor fits.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // Base penalty so new bins are chosen only when open bins are wasteful.
        score += 18.0;
        // If mean residual is small (bins are tight), a new bin is reasonable.
        score -= 0.25 * mean_residual;
        // Lookahead: if next item is large, having fresh capacity helps.
        if next_item_size >= 50 {
            score -= 8.0;
        }
        // Early in stream, allow opening bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    } else {
        // Prefer bins whose residual aligns with the next item's size (lookahead fit).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Penalize if this bin's post-residual is awkward relative to mean residual.
        if (post_residual as f64 - mean_residual).abs() > 40.0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, but weight it more as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual and next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain fit (item i+1 exactly fills the leftover of item i).
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item can also land here: reward proportionally to closeness of fit.
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space relative to next size.
            score += 0.3 * gap;
        }
    } else {
        // Last item: pure tightness fit.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" bins;
    // placing into them wastes scarce capacity, so penalize; loose bins get a mild reward.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = residual_f / mean_residual;
        if rel < 1.0 {
            score += 4.0 * (1.0 - rel);
        } else {
            score -= 1.5 * (rel - 1.0).min(2.0);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent open bins exist: make the empty-bin candidate
    // less attractive unless the fit into open bins would be terrible.
    if bin_residual == bin_capacity {
        score += 12.0;
        // New bin is acceptable early in the stream (spread load) or when few bins are open.
        if progress < 0.2 || open_bins_count < 2 {
            score -= 10.0;
        }
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 6.0;
        }
    }

    // Slight penalty for leaving extremely small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later on, waste becomes more costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.5;

    // Reward tight fits strongly (waste penalty is super-linear).
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Partial reward scaled by how well next item uses leftover space.
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * use_ratio;
        } else {
            // Next item won't fit here; slight penalty for leaving awkward gap.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or no reasonable alternative exists.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 60.0 * (1.0 - size_ratio);
        if next_item_size > 0 && next_item_size >= post_residual {
            new_bin_score -= 10.0; // fresh bin gives room for the next item too
        }
        if fitting_bins_count == 0 {
            new_bin_score = -100.0; // nothing else fits, must open
        }
        score += new_bin_score;
    }

    // Prefer bins whose residual is already below average (consolidating waste).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= diff * 0.3;
    }

    // Mild pressure to fill existing bins when many are open.
    if open_bins_count > 2 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: quadratic post-residual penalty scaled by progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize bins whose residual is near mean residual (redundant choice)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bonus: strong smooth reward when only one bin fits
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 60.0 * last_chance * (0.5 + 0.5 * progress);

    // Lookahead: reward if next item fits the post residual (smooth coupling)
    let n = next_item_size as f64;
    if n > 0.0 {
        let fits_next = (cap - (item_size as f64 + n)).max(0.0) - pr.max(0.0);
        let slack_after_next = pr - n;
        let smooth = (slack_after_next / cap).tanh();
        score += 15.0 * (1.0 - smooth) * (0.5 + 0.5 * progress);
        let _ = fits_next;
    }

    // Mild penalty for opening new bins early; relax as stream progresses
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (30.0 - 20.0 * progress) * (1.0 - 0.3 * (open_bins_count as f64 / 10.0).tanh());

    // Cubic dead-space penalty for very small residuals
    score += 20.0 * norm_pr.powi(3) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 and capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: post residuals in small harmonic classes (near multiples of 10).
    let residue = post_residual % 10;
    let residue_penalty = match residue {
        0 => -18.0,                       // perfectly harmonic leftover
        1 | 2 => -6.0,                    // nearly harmonic
        8 | 9 => 4.0,                     // awkward sliver
        _ => 0.0,
    };
    score += residue_penalty;

    // Dead-space threshold: residuals too small for the smallest item (<=10) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Reward using a bin whose leftover can host the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            score += 6.0;
        }
        // Harmonic pairing: next item completing this bin to a multiple of 20.
        if (post_residual as i64 - next_item_size as i64) % 20 == 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bonus: only one open bin fits, prefer using it over opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // New-bin candidate handling: prefer opening a fresh bin when item is huge
    // and would leave a large awkward gap elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 70 {
            score -= 15.0 + 10.0 * progress;
        } else if post_residual >= 30 {
            score += 10.0; // opening a new bin for a small item wastes capacity
        } else {
            score += 2.0;
        }
    }

    // Mild preference for bins below the mean residual (keeps distribution balanced).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Integer-division threshold on post_residual quartiles of capacity.
    let quart = post_residual / (bin_capacity / 4);
    score += match quart {
        0 => -5.0,           // nearly full bin, great packing
        1 => -2.0,
        2 => 1.0,
        _ => 3.0,            // mostly empty, deprioritize
    };

    // Small fraction coupling: penalize residuals in (0.6C, 0.9C) band lightly.
    if frac > 0.6 && frac < 0.9 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest item (1) are pure waste; gaps below a "danger band" (< 15)
    // are nearly unusable and get a strong penalty.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: best possible outcome
    } else if post_residual < 15 {
        score += 35.0; // near-dead space, heavily penalize
    } else if post_residual < 30 {
        score += 12.0; // awkward gap
    }

    // Reward tight fits relative to item size (relative waste).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * (post_residual == 0) as i32 as f64;
    score -= 8.0 * fill_ratio;

    // Open-bin pressure: discourage opening new bins when decent options exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only attractive if no other bin fits, or the only fit is terrible.
        if fitting_bins_count > 0 {
            score += 30.0 + 2.0 * open_bins_count as f64;
        } else {
            score -= 10.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward this placement (creates a perfect follow-up slot).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 15 {
            score += 15.0; // would create dead space for the next item
        }
    }

    // Mean-residual coupling: prefer bins that are tighter than average
    // (keeps large residuals available for large future items).
    if !is_new_bin {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Late-stream pressure: as the stream progresses, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (low post_residual) relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Extra reward when the leftover is a near-perfect match for next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 10.0;
        } else {
            // Penalize dead space that cannot fit the next item.
            score += 15.0;
            // Dead space penalty grows with how far off the fit is.
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / bin_capacity as f64) * 20.0;
        }
    }

    // Compare post_residual against mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many fitting bins -> this is a commodity placement; slight penalty unless tight.
    if fitting_bins_count > 1 {
        score += 5.0;
    }

    // Penalize opening a brand-new empty bin when open bins exist and fit well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0;
        // But if this is a big item and few bins fit it, new bin is acceptable.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Late in the stream, avoid leaving fragmented residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (wasted sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if next item fits into the post residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            // Next item won't fit here; slight penalty proportional to leftover gap.
            score += 0.08 * (post_residual as f64).max(0.0);
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor relative to the item.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        // If open bins are mostly tight, opening a new bin is fine.
        score -= 5.0 * mean_gap / bin_capacity as f64;
        // Early in stream, be more willing to open bins (build diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
        // Many open bins with slack: discourage spreading.
        score += 0.05 * open_bins_count as f64;
    } else {
        // Using an existing bin reduces open-bin growth: small reward.
        score -= 1.0;
        // Prefer bins whose residual is below mean (consume the tightest side).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    // Late-stream consolidation: as stream ends, avoid opening new bins hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.9 && bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, quadratically (dead space is superlinearly bad).
    let mut score = post * post / cap;

    // Smooth coupling: as the stream progresses, waste becomes more costly
    // (less opportunity to fill gaps later).
    let progress_waste = post * (0.5 + 1.5 * progress);
    score += 0.8 * progress_waste;

    // Reward tight fits: item_size close to bin_residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Penalize when this bin is the only fitting bin (last chance) -> favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer bins where the item fits snugly relative to others.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin has large post_residual, which
    // already scores high; add a mild bonus only when existing bins fit poorly
    // (post_residual large relative to capacity) and lookahead is big.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        // Opening a new bin is attractive if the lookahead item is large and
        // current mean residual is small (existing bins nearly full).
        let lookahead_pressure = next_item_size as f64 / cap;
        let residual_pressure = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 25.0 * lookahead_pressure * residual_pressure * (0.5 + progress);
        // Slight early-stream bias toward opening bins to build diversity.
        score -= 5.0 * (1.0 - progress);
    } else {
        // Placing into an open bin: reward if next item fits the post_residual well.
        if next_item_size > 0 && (next_item_size as f64) <= post {
            let next_fit = next_item_size as f64 / post.max(1.0);
            score -= 10.0 * next_fit * (1.0 - progress);
        }
        // Penalize leaving residuals that no plausible item (>=1) can use well.
        if post > 0.0 && post < 10.0 {
            score += 8.0 * (10.0 - post) / 10.0;
        }
    }

    // Mild penalty for bin proliferation late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "coarse"
    // residue classes (mod 10) are less reusable; penalize dead zones.
    let post = post_residual as i64;
    let cls = post % 10;
    if post > 0 {
        // small leftovers (<10) are dead space -> strongly penalize
        if post < 10 {
            score += 25.0;
        } else {
            // reward leftovers in friendly classes (multiples of 5 or 10)
            if cls == 0 {
                score -= 6.0;
            } else if cls == 5 {
                score -= 3.0;
            } else {
                score += (cls as f64) * 0.4;
            }
        }
    }

    // Integer-division thresholds: leftover usable by next item?
    if next_item_size > 0 && post >= next_item_size as i64 {
        // exact harmonic fit: post_residual is an integer multiple of next size
        if post % (next_item_size as i64) == 0 {
            score -= 8.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize proportional waste
        score += (next_item_size as f64).min(post.max(0) as f64 + 10.0) * 0.15;
    }

    // Capacity-fraction coupling: favor filling bins past 50%, 75% marks
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill >= 0.75 {
        score -= 5.0;
    } else if fill >= 0.5 {
        score -= 2.5;
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current item is large relative
    // to capacity or no good harmonic fit exists elsewhere.
    if bin_residual == bin_capacity {
        let base = 20.0 + 0.3 * (open_bins_count as f64);
        if next_item_size > 0 && (next_item_size as u32).saturating_add(item_size) <= bin_capacity {
            // keep pair-packing in existing bins when possible
            score += base;
        } else {
            score += base * 0.5;
        }
        // empty-bin score anchored near mean residual to compete fairly
        score += mean_residual * 0.2;
    }

    // Late-stream consolidation: prefer tightest bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below ~min item size 10)
    // are heavily penalized; a perfect or near-perfect fill is rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 400.0;
    } else if post_residual < 20 {
        score += 120.0; // awkward gap: neither full nor usable by small items
    } else {
        // Usable residual: mild reward proportional to how well it matches
        // typical item granularity, slightly favoring larger usable space.
        score -= (post_residual as f64 / bin_capacity as f64) * 30.0;
    }

    // Reward tight fits: item filling a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 80.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but relax as the stream progresses (early consolidation matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (6.0 - 4.0 * progress);

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably (below mean) so we drain smaller leftover spaces first.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: penalize creating stranded space.
        score += 60.0 + post_residual as f64 * 0.5;
    }

    // New-bin candidate bias: only prefer a fresh bin when all open bins
    // would create bad dead space (handled above); otherwise make the new bin
    // slightly unattractive to promote packing into open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post-residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness;

    // 2-step lookahead: strongly reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = if diff == 0.0 {
            60.0
        } else if next_item_size as u32 <= post_residual {
            35.0 - diff * 0.9
        } else {
            // next item won't fit here; mild penalty for small post-residual
            -0.05 * post_residual as f64
        };
        score -= match_bonus;
    } else {
        // Last item: prefer minimal waste, strongly.
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: bins with residual near/below mean are good targets.
    let rel = post_residual as f64 - mean_residual;
    score += 0.25 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny unusable dead space (waste) unless lookahead matches.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 12.0;
    }

    // Early in stream: slightly discourage opening many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if it looks better than poor fits.
        score += 8.0 * (1.0 - progress) + 0.15 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize creating dead space that few future items could use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // small unusable gap
    }
    if post_residual > 50 {
        score += 0.05 * (post_residual as f64 - 50.0); // large leftover is fine-ish
    }

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // chain potential: residual after both
            let r2 = post_residual - next_item_size;
            score -= 0.3 * (r2 as f64);
        } else {
            // next item can't follow here; slightly penalize if post_residual
            // is a size that rarely occurs (between 11 and 20 dead zone)
            if post_residual >= 11 && post_residual <= 20 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.1);
    score -= 4.0 * open_pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (fill emptier gaps)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: only attractive early in stream or when
    // the item fits terribly everywhere (post_residual near capacity means
    // item is small relative to residual... for a fresh bin residual==capacity)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // base penalty so existing bins usually win
        score += 18.0;
        // early stream: opening bins is cheap
        score -= 25.0 * (1.0 - progress) * (1.0 - progress);
        // large item in fresh bin is fine
        score -= 0.1 * item_size as f64;
        // if the only fitting option, new bin is necessary
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // mild time-horizon scaling: later in stream, be greedier about tight fits
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Smooth polynomial coupling: penalize mid-range waste more as stream progresses
    let waste_curve = x * (1.0 - x) * 4.0; // peaks at x=0.5
    score += waste_curve * (1.0 + 3.0 * progress) * 12.0;

    // Reward tight fits (small post residual) increasingly late in the stream
    score -= (1.0 - x).powi(3) * (2.0 + 8.0 * progress);

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let snug = 1.0 - ((pr - nx) / cap);
            score -= snug * (4.0 + 6.0 * progress);
        } else {
            // post residual can't host next item -> penalize proportionally
            score += (nx / cap) * (2.0 + 4.0 * progress);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Many open bins: encourage consolidation (favor bins with low residual)
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += openness * x * 6.0;

    // New empty bin candidate: penalize unless it's a good deal (item large relative to cap)
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 10.0 - fill * 12.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: small residues are golden, exact zeros are perfect.
    let pr = post_residual;
    let class: f64 = match pr {
        0 => -40.0,
        1..=5 => -25.0,
        6..=10 => -12.0,
        11..=20 => -5.0,
        21..=30 => 3.0,
        _ => 10.0,
    };
    score += class;

    // Modulo arithmetic: residuals that are multiples of common small sizes are reusable.
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 5 == 0 { score -= 4.0; }
        if pr % 3 == 0 { score -= 1.5; }
        if pr % 7 == 0 { score -= 1.0; }
    }

    // Lookahead harmony: if next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if pr >= next_item_size {
            // next item still fits here: mild bonus scaled by tightness
            score -= 6.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item cannot use this residue: penalize proportionally to wasted space
            score += 4.0 * (next_item_size as f64 / bin_capacity as f64) * (pr as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // New-bin candidate: only attractive when open bins are crowded and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) / (open_bins_count as f64 + 4.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        let new_bin_bonus = 18.0 * crowded * (0.3 + 0.7 * big_item) * (0.5 + 0.5 * progress);
        score -= new_bin_bonus;
        // Discourage opening new bins for small items late when mean residual is large.
        score += 0.25 * mean_residual * (1.0 - big_item);
    }

    // Prefer bins that are already partially filled (avoid fragmenting many bins).
    let used = (bin_capacity - bin_residual) as f64;
    score -= 6.0 * (used / bin_capacity as f64);

    // Penalize leaving a residue just below the smallest plausible item (dead space band).
    if pr >= 1 && pr < 10 {
        score += 12.0 * (1.0 - pr as f64 / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Penalize gaps too small for the minimum item size (1..100 stream: dead space < next item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward a gap that exactly accommodates the lookahead item (smooth packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bins pressure: mildly discourage spreading across many bins unless residual is large.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins with residual tighter than the mean (good fits), discourage outliers.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when nothing fits well (large item, poor fits elsewhere).
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (bin_residual as f64 - item_size as f64) > mean_residual + 20.0;
        if poor_fit {
            score -= 120.0;
        } else {
            score += 200.0;
        }
    }

    // Slight late-stream tightening: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits (wasted space minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else {
        // Non-linear penalty on dead space, amplified for small leftovers
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: strong reward, scaled by tightness of that follow-up fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack * 0.5;
            // Perfect 2-chain: item + next item fills bin exactly
            if post_residual == next_item_size {
                score -= 500.0;
            }
        } else {
            // Next item won't fit: penalize, worse if the leftover is small and useless
            let dead = post_residual as f64;
            score += dead * 0.8;
            // Extra penalty if leftover is too small for any plausible item (min size 1..10 range)
            if post_residual < 10 {
                score += 120.0;
            }
        }
    } else {
        // Last item: just prefer tightest fit
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Compare against mean residual: prefer bins below-average residual (tighter bins)
    // to preserve large-residual bins for larger future items
    score += (mean_residual - bin_residual as f64) * 1.5;

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when open bins are nearly full on average
    if bin_residual == bin_capacity {
        // New empty bin: score = its full residual, adjusted by stream phase and congestion
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64;
        score += 40.0 * progress + 5.0 * congestion;
        // If no open bin fits at all, opening new bin is necessary (handled naturally),
        // but if many bins fit, discourage spreading
        if fitting_bins_count > 2 {
            score += 150.0;
        }
    }

    // Mild penalty for bins that would be left with awkward mid-range residuals
    let pr = post_residual;
    if pr >= 20 && pr <= 40 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
