    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins moderately unattractive
    // unless the fit is poor elsewhere or many bins are open.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
        // but if item is large relative to capacity, new bin is fine
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Prefer filling bins whose residual deviates from mean (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for bins with larger residual early (keep small holes for small items later).
    score -= 0.02 * (bin_residual as f64) * (1.0 - progress);

    // Discourage opening many bins when few fit.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * progress;
    score += poly * (1.0 + 0.5 * progress);

    // Penalize last-chance bins less (favor using them)
    if fitting_bins_count == 1 {
        score -= 0.4 * (1.0 + progress);
    }

    // Favor bins whose residual is tighter than the mean
    let mean_norm = mean_residual / cap;
    score += 0.3 * (norm_post - mean_norm).abs();

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.25 * (nxt / cap);
        } else {
            score += 0.15 * (nxt - post) / cap;
        }
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 0.2 + 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    match class {
        0 => score -= 12.0,                 // tiny leftover: excellent fit
        1 => score -= 4.0,                  // decent leftover
        2 => score += 3.0,                  // half-ish leftover: ok
        _ => score += 10.0,                 // large leftover: wasteful
    }

    // Dead-space trap: leftover too small for any plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead harmonic coupling: leftover divisible-friendly to next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            if post_residual % next_item_size.max(1) == 0 { score -= 6.0; }
        } else {
            score += 5.0;
        }
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening unless this bin would waste a lot
    if bin_residual == bin_capacity {
        let waste_now = (post_residual as f64) / cap;
        score += 15.0 + 30.0 * (1.0 - waste_now);
        if next_item_size > 0 && post_residual >= next_item_size { score -= 10.0; }
    }

    // Prefer tighter bins relative to current mean residual
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Late in stream: consolidate, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity { score += 10.0 * progress; }
    else { score -= 5.0 * progress; }

    // Mild penalty per open bin to encourage filling existing bins
    if bin_residual != bin_capacity { score -= 0.5 * open_bins_count as f64; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it cannot hold even the smallest plausible item (>=1),
    // or is too small for the lookahead item while other bins could.
    if post_residual < 10 {
        // Tiny unusable sliver -> heavy penalty proportional to wasted capacity.
        score += (10 - post_residual) as f64 * 25.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }

    // If the lookahead item would fit exactly in the resulting residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 300.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0; // residual still usable for next item
    } else if next_item_size > 0 && post_residual > 0 {
        // residual smaller than next item: penalize proportionally to how close it was
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bins pressure: when many bins are open, favor consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 2.0 * progress);
    if bin_residual < bin_capacity {
        score -= pressure;
    } else {
        // Brand-new bin candidate: penalize mildly, more when many bins are open or late in stream.
        score += 30.0 + pressure;
        // But if current bin residual is a bad fit (item leaves big dead space vs mean residual),
        // allow new bin to win.
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 120.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit) beyond raw post_residual.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= 25.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // 2-step lookahead: strong reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining
        } else if post_residual >= next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - leftover / (bin_capacity as f64));
        } else {
            // next item cannot follow here; penalize wasted residual
            score += 0.15 * (post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.1 * ((post_residual as f64) - mean_residual);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but allow new bin if no open bin fits (fitting_bins_count == 0 means only new bin)
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // late in stream, prefer closing out existing bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    }

    // Dead-space penalty: residuals below the minimum item size are useless.
    if post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill of the bin by this item: reward tight fits.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 18.0 * fill * fill;

    // Penalize small post-residuals that are "dead space" (too small for the
    // smallest plausible item, but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack = post_residual as f64 - nxt;
            score -= 12.0 / (1.0 + slack);
        } else {
            // Next item won't fit here; mild penalty proportional to waste.
            score += 4.0 * (nxt - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> encourage
    // consolidating into existing bins; few open bins -> new bins are cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln_1p();
    if bin_residual < bin_capacity {
        score -= 6.0 * consolidation * (0.5 + progress);
    }

    // New-bin candidate handling: neutral-ish base, but attractive when the
    // item is large (poor fit elsewhere likely) or open bins are crowded.
    if bin_residual == bin_capacity {
        score = 0.35 * bin_capacity as f64
            - 20.0 * fill
            - 5.0 * (open_bins_count as f64).ln_1p()
            - 10.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // If only the new bin fits, opening is mandatory anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight time-horizon shaping: early on, be conservative (favor existing
    // bins); late, accept tight fits aggressively.
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let norm_post = pr / cap;

    let mut score = norm_post * (1.0 + 0.8 * progress * progress);

    // reward tight fits via smooth polynomial coupling
    score -= (1.0 - norm_post).powi(3) * (0.5 + 1.5 * progress) * 10.0;

    // penalize dead space that cannot fit the next item (smooth term)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += gap * gap * 25.0 * (1.0 - progress);
        // reward residual that fits next item
        let fits_next = ((pr - nxt).max(0.0)) / cap;
        score -= fits_next * fits_next * 8.0;
    }

    // last-chance bonus, smooth
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - fit_frac) * (0.5 + progress);
    }

    // mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    // penalize when bin residual deviates strongly from mean residual (smooth coupling)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 4.0 * (1.0 - progress);

    // new-bin candidate handling: keep it competitive only for large items / poor fits
    if bin_residual == bin_capacity {
        score = 30.0 + 40.0 * fit_frac - 20.0 * (1.0 - norm_post) * progress;
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt <= pr {
                score -= 10.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "usable slots"
    // (multiples of common size classes) and penalize awkward remainders.
    let pr = post_residual as i64;
    let mod10 = pr % 10;
    let mod25 = pr % 25;
    let mod50 = pr % 50;

    // Reward residuals aligned to harmonic classes (0 mod 10 best, then mod 25, mod 50).
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else {
        if mod10 == 0 {
            score -= 8.0;
        } else if mod10 <= 2 || mod10 >= 8 {
            score += 4.0; // near-dead sliver
        }
        if mod25 == 0 {
            score -= 5.0;
        }
        if mod50 == 0 {
            score -= 3.0;
        }
        // Dead-space penalty: residuals too small for the smallest plausible item.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }
    }

    // Integer-division threshold classes on post_residual relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 15.0;
    } else if frac < 0.3 {
        score += 4.0;
    } else if frac > 0.8 {
        score -= 6.0; // big residual: keep bins roomy
    }

    // Lookahead coupling: if the next item can use this bin's post_residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // exact harmonic match for next item
            if post_residual % next_item_size.max(1) == 0 && post_residual == next_item_size {
                score -= 12.0;
            }
        } else {
            score += 6.0;
        }
    } else {
        // Last item: prefer filling as tightly as possible.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or the stream is early and we want many open bins (diversity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 55.0 - 25.0 * progress; // early stream: more tolerant of new bins
        score += base;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 20.0;
        }
        if post_residual == bin_capacity {
            // still a new bin; score stays as base penalty
        }
    }

    // Many open bins with high mean residual: prefer consolidating into emptier bins.
    if open_bins_count > 3 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev; // favor bins below mean residual (tighter bins)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable sliver penalty
    } else if post_residual > 0 && post_residual < item_size / 2 {
        score += 12.0; // awkward half-gap penalty
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Lookahead coupling: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 8.0; // next item won't fit here; de-prioritize this bin slightly
        }
    }

    // Last-chance bonus: only one open bin can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins with residuals below the mean (compact the dense bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Mild stream progression tilt: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits but penalize unusable dead space (< smallest item ~1).
    let dead = if post_residual == 0 { 0.0 } else if post_residual < 10 { 25.0 } else { 0.0 };
    score += dead;

    // 2-step lookahead: reward when next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how much it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 6.0 * (miss / bin_capacity as f64);
    }

    // Compare post_residual against mean residual of open bins.
    let cap = bin_capacity as f64;
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when residuals are all poor.
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - mean_residual / cap;
        score += 30.0 * mean_tightness; // penalize new bin if existing bins are tight
        score -= 10.0 * (1.0 - mean_tightness); // reward new bin when open bins are loose
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0; // fresh bin guarantees room for lookahead
        }
    }

    // Early in stream: encourage consolidation; late: be more tolerant of new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (1.0 - progress) * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post-residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for likely future items (typical item sizes 1..100,
    // mid-range items ~10..80): residual below ~30 is nearly unusable.
    if post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.9;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it attractive only
    // when the fit here would be poor or the lookahead suggests a better use of open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin mildly; it must beat genuinely bad fits only.
        score += 12.0;
        // If the item would leave a very small unusable residue in an open bin,
        // opening a fresh bin becomes more attractive.
        if post_residual < 15 && !false {
            score -= 20.0;
        }
        // Lookahead: if next item is large and current fit is loose, a fresh bin is fine.
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 + 20.0 {
            score -= 6.0;
        }
    } else {
        // Reward using existing bins, more so as the stream progresses (consolidation).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 + 6.0 * progress;

        // Lookahead synergy: if the post-residual can exactly/comfortably host the next item,
        // reward this placement strongly.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 22.0;
            } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
                score -= 10.0;
            } else if post_residual < next_item_size && post_residual > 0 {
                // post-residual too small for the next item: penalize proportionally.
                score += 0.35 * (next_item_size - post_residual) as f64;
            }
        }

        // Prefer bins whose residual is close to the mean residual (keep the pool uniform),
        // slightly favoring bins with more space when many bins are open.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
        if open_bins_count > 6 && bin_residual as f64 > mean_residual {
            score -= 2.0;
        }
    }

    // Mild global pressure: when many bins are open, discourage creating new ones.
    if open_bins_count > 4 && !is_new_bin {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: favor tight fits, with non-linear polynomial shaping of post_residual
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: later in the stream, dead space matters more
    let progress_coupling = 1.0 + 1.2 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= progress_coupling;

    // Non-linear interaction: post_residual vs mean residual (avoid bins much worse than average)
    let mr = mean_residual / cap;
    score += 8.0 * (norm_pr - mr) * (norm_pr - mr);

    // Penalize creating residual that is too small to be useful for next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let usable = (pr - ns).max(0.0);
        let waste = (pr - ns - usable) as f64; // 0 if next fits
        if pr < ns {
            score += 6.0 * (ns - pr) / cap * 10.0;
        } else {
            // reward leaving exactly enough for next item (smooth)
            score -= 4.0 * (1.0 - (usable / cap).min(1.0)) * (1.0 - progress);
        }
        let _ = waste;
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty when many bins open and this one is nearly empty (fragmentation)
    let frag = 1.0 - (pr / cap);
    score += 2.0 * open_bins_count as f64 * frag * frag * 0.1;

    // New-bin candidate: neutral-ish, slightly penalized so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Dead-space classes: tiny leftovers (< 10, min item size) are unusable.
    if post_residual < 10 {
        score -= 250.0; // small dead space is fine, bin essentially full
    } else if post_residual <= 20 {
        // awkward zone: only small items fit; penalize mildly
        score += 30.0;
    } else if post_residual <= 50 {
        score += 60.0; // mid residual: risky, may strand
    }

    // Modulo-10 harmonic class: residuals divisible by 10 align with item grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; large residual wasted on this step
            score += 0.5 * (next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Many open bins: encourage consolidation (prefer tighter fits).
    if open_bins_count > 4 {
        score += frac * 50.0;
    }

    // Prefer bins with below-mean residual (fill emptier-space efficiently).
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.6 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base penalty so new bins are used sparingly
        score += 150.0;
        // but if item is large relative to residual of others, allow opening
        score -= pressure * (item_size as f64) * (1.0 + 0.5 * progress);
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 40.0; // big next item: fresh bin may serve both
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space avoidance: small unusable gaps are costly.
    // Items range 1..=100, so residual < 10 can never be filled again.
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Partially unusable zone: residual < 25 is hard to fill with typical items
    if post_residual > 0 && post_residual < 25 {
        score += 80.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward bins whose residual tightly matches the item (low slack ratio)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage new bins only for good fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 4.0 * (1.0 - progress);

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 100.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual < 10 {
            // next item can't use this tiny gap anyway; soften dead-space penalty
            score -= 40.0;
        }
    }

    // New empty bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else {
            // discourage opening new bin when existing bins can fit
            score += 120.0 + mean_residual * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: keep residual as small as possible (best-fit core).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when the next item exactly matches
    // the post_residual (perfect chain), punish near-misses that strand space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect two-step match: extremely strong reward.
            score -= 1000.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward partial match, but decay quickly as slack grows.
            score -= 300.0 / (1.0 + slack * 0.15);
            // Penalize unusable dead space after the next item would fit.
            if slack > 0.0 && slack < 10.0 {
                score += slack * 8.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how much space gets stranded relative to mean residual.
            let stranded = post_residual as f64 - mean_residual.max(0.0);
            if stranded > 0.0 {
                score += stranded * 2.0;
            }
            score += 40.0;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are already tight;
    // prefer filling them rather than spreading load.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 1.5;
    } else {
        score += (resid - mean_residual) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to capacity and no tight chaining opportunity exists.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Large items start fresh bins happily; small items should reuse.
        score += 500.0 * (1.0 - frac) * (1.0 - frac);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // A fresh bin with a good lookahead match is fine.
            let slack = (bin_capacity - item_size - next_item_size) as f64;
            score -= 200.0 / (1.0 + slack * 0.2);
        }
        // Late in the stream, avoid spawning extra bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 300.0;
    }

    // Mild penalty for too many open bins to encourage consolidation.
    score += open_bins_count as f64 * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // small but nearly unusable gap: acceptable end-state
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0; // awkward mid gap
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // no open bin fits well or lookahead suggests a large future item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_fit_exists = fitting_bins_count > 0 && (bin_residual as f64 - item_size as f64) < 15.0;
        if good_fit_exists {
            score += 25.0; // keep filling existing bins
        }
        // Open a new bin if lookahead item won't fit the post-residual anyway
        // and current post-residual is large (wasteful placement).
        if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
            score -= 12.0 * (post_residual as f64 / bin_capacity as f64);
        }
        // Late in the stream, avoid proliferating bins.
        score += 20.0 * progress;
        // Many open bins already: discourage new bins.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Prefer bins whose residual is above mean (balance across bins).
        score -= 0.3 * (bin_residual as f64 - mean_residual);
        // Prefer filling bins that can no longer host the next item.
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score -= 6.0;
        }
        // Perfect fill reward.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + progress) + norm_post * (1.0 - progress);

    // Penalize dead space more strongly later in the stream
    let dead = (norm_post * norm_post * norm_post) * (1.0 + 2.0 * progress);

    // Reward tight fits (low post residual) especially when few alternatives
    let tight = -2.5 * (1.0 - norm_post) * (1.0 - norm_post) / (fitting_bins_count as f64 + 1.0);

    // Lookahead: favor bins whose post residual can host the next item
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if pr >= next_item_size as f64 { -1.5 * nx * (1.0 - norm_post) } else { 1.5 * nx }
    } else { 0.0 };

    // New-bin candidate: mild penalty so we prefer filling open bins unless fit is poor
    let new_bin = if bin_residual == bin_capacity {
        0.8 + 1.5 * norm_item + 1.2 * progress
    } else {
        0.0
    };

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let mean_dev = (pr - mean_residual).abs() / cap;

    let mut score = pr + 3.0 * poly + 4.0 * dead + tight + lookahead + new_bin + 0.5 * mean_dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: modulo-10 classes relative to capacity
    let pr = post_residual;
    let class = pr % 10;
    // Residuals in {0,1,2} are near-perfect fits -> strong reward
    if pr == 0 {
        score -= 1000.0; // perfect closure, always take
    } else if class <= 2 {
        score -= 60.0;
    } else if class >= 8 {
        // residual close to next multiple of 10: dead space likely unusable
        score += 25.0;
    }

    // Integer-division thresholds: can a typical next item (<= 80) ever fit?
    if pr > 0 && pr < 10 {
        score += 40.0; // guaranteed dead space for items >= 10
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0; // perfect two-item chain
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.8;
        } else {
            // next item cannot fit here: penalize large leftover less strongly
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are bad
    if bin_residual == bin_capacity {
        // new empty bin: attractive if all open residuals are fragmented
        let frag = (mean_residual - post_residual as f64).abs();
        score -= 90.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 40.0; // big next item: fresh bin is valuable
        }
        if frag < 8.0 && mean_residual > 40.0 {
            score += 150.0; // open bins still roomy -> don't open new one
        }
        // discourage hoarding bins late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild penalty for wasting a very roomy bin on a tiny item
    if item_size * 4 < bin_residual {
        score += 10.0;
    }

    // Prefer filling bins with larger mean residual (balance across bins)
    score -= mean_residual * 0.05;

    score
}

