    if post_residual as f64 > mean_residual * 1.5 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post_residual (tight fit), non-linearly scaled.
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Smooth polynomial coupling: post_residual^2 weighted by stream progress.
    // Early on, tight packing matters slightly less; late, dead space is costly.
    score += 0.9 * (pr / cap).powi(2) * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = 1.0 - pr / cap;
    score -= 6.0 * tightness * tightness * tightness;

    // Lookahead: bonus if the leftover space can host the next item exactly-ish.
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        let ratio = pr / nxt;
        if ratio >= 1.0 {
