            let closeness = 1.0 - ((ratio - 1.0).ln()).abs().min(2.0) / 2.0;
            score -= 4.0 * closeness * (0.5 + progress);
        } else {
            // Leftover too small for next item: penalize dead space smoothly.
            score += 3.0 * (1.0 - ratio) * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * tightness;

    // Prefer bins whose residual is already near the mean (balanced packing).
    score += 0.4 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make it moderately attractive only when it beats a bad fit.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) + 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space zones: residuals below smallest item (1..=3) are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic class logic on post_residual: residuals that are multiples of
    // common item sizes are more reusable. Classify by mod 10.
    let pr = post_residual as i64;
    let class_bonus: f64 = match pr % 10 {
        0 => 25.0,                      // reusable by any decade item
        5 => 12.0,                      // half-decade
        2 | 4 | 6 | 8 => 6.0,           // even residuals
        _ => -8.0,                      // odd residuals, awkward
    };
    score -= class_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size <= post_residual {
            // next fits: mild bonus scaled by tightness
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize leaving large residual we can't chain
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += 0.05 * waste;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // base penalty so full bins usually win
        score += 60.0;
        // but if many bins are open with fragmented residuals, opening fresh is fine
        score -= (open_bins_count as f64).min(10.0) * 3.0;
        // if the current item is large relative to capacity, fresh bin is attractive
        score -= (item_size as f64 / bin_capacity as f64) * 40.0;
        // late in stream, prefer closing out with new bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * progress;
    }

    // Prefer placing into bins whose residual is far below mean (consolidating slack)
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Integer-division threshold: bins whose residual can hold a "half item" pair
    if (bin_residual / 2) >= item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
