    if dead > 0.0 {
        // gaps below ~12 are hard to fill; penalize quadratically there
        if dead < 12.0 {
            score += (12.0 - dead) * (12.0 - dead) * 4.0;
        }
        // also mildly penalize mid-range gaps that can't fit the known next item
        if next_item_size > 0 && dead < next_item_size as f64 {
            score += (next_item_size as f64 - dead) * 1.5;
        }
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 20 {
        score -= 25.0;
    }

    // New-bin candidate handling: brand-new empty bin should only win when the
    // current bin's fit would create large dead space, or bins are scarce.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, softened by open-bin pressure
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score = bin_capacity as f64 * 0.9 + pressure * 8.0;
        // but if next item is large, a fresh bin is more attractive
        if next_item_size >= 70 {
            score -= 20.0;
        }
        // late in stream, prefer reusing open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into bins
    // that already exist (penalize spreading), scaled by mean residual.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(1.0) * 2.0;
        // prefer bins tighter than average (they're nearly full, less fragmented)
        let res = bin_residual as f64;
        if res < mean_residual {
            score -= (mean_residual - res) * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional waste relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Strong reward for near-perfect packing (small post_residual).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize creating dead space too small for the smallest plausible item (1..100 range):
    // residuals below 10 are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains well — reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = post_residual - next_item_size;
        if chain_waste <= 5 {
            score -= 18.0;
        } else {
            score -= (chain_waste as f64).ln() * 4.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // Next item can't use this bin and residual is dead space — penalize.
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate logic: an empty bin should win only when the current item
    // is large and fits poorly in existing bins, or when open bins are fragmented.
    if bin_residual == bin_capacity {
        // Base preference for new bin scaled by fragmentation of open bins.
        score += mean_residual * 0.35;
        score += open_bins_count as f64 * 1.5;
        // Large items (>= 60) prefer fresh bins slightly.
        if item_size >= 60 {
            score -= 8.0;
        }
        // Late in the stream, avoid opening new bins (less time to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // Favor filling bins whose residual is close to the item (best-fit flavor).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.2;
        // Prefer bins with residual below the mean (consolidate fragmented space).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Global pressure: when many bins are open, prefer filling existing ones.
    score += open_bins_count as f64 * 0.8;

    // Early stream: slight preference for keeping bins balanced (spread items),
    // late stream: pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit = item_size as f64 / cap;
    let tightness = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * tightness);

    // Reward tight fits more strongly as the stream progresses
    score -= 18.0 * fit * fit * (0.4 + progress);

    // Penalize large dead space non-linearly
    score += 0.02 * pr * pr / cap;

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 6.0 * (-gap / 25.0) * (1.0 - progress);
    } else {
        score += 2.0 * pr / cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Mild penalty for spreading across many bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residues are dead space
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Penalize residues that fall into "unusable" classes (too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Modulo classes: residues divisible by common item sizes are more reusable
    let mut reuse_bonus = 0.0;
    for &d in &[10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            reuse_bonus += 15.0;
        }
    }
    score -= reuse_bonus;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit here: mild penalty proportional to waste
            score += 0.2 * post_f;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = mean_residual / cap;
        // open new bin only if mean residual is low (bins nearly full) late in stream
        score += 200.0 - 150.0 * crowd - 50.0 * progress;
    }

    // Prefer tighter bins generally
    score += 0.1 * (bin_residual as f64 - post_f);

    // Slight preference for bins below mean residual (balance load)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (small post_residual that
    // nothing can realistically fit) are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead gap: worst outcome
        } else if post_residual < 20 {
            score += 35.0;
        } else if post_residual < 30 {
            score += 15.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 50.0;
    }

    // Reward leaving a gap that the lookahead item can still use.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward for a tight-but-fitting lookahead match.
        if post_residual < next_item_size * 2 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap that the next item cannot use: mild penalty scaled by gap size.
        score += 6.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: penalize adding to bins when many bins are open,
    // unless the fit is good (post_residual small).
    let open_pressure = open_bins_count as f64 * 1.5;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Favor bins whose residual deviates from the mean (consolidate leftovers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Progression: later in the stream, be slightly more conservative with
    // large leftover gaps (less time to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    // New-bin candidate calibration: an empty bin has post_residual == capacity.
    // Make it attractive only when the current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by its full flexibility.
        score += 20.0;
        score -= progress * 10.0;
        if post_residual == bin_capacity {
            // Opening a fresh bin leaves full usable space; mild discount.
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: penalize tight fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 - (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here; penalize proportionally to wasted slack.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize leaving large dead space relative to mean residual.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - pr) * 0.1;
    }

    // Penalize creating very small unusable residuals (< 10, the min item size),
    // scaled by how early in the stream we are.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - pr) * (1.5 - progress);
    }

    // Mild pressure against opening new bins when many are open with slack.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty scaled by capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * tightness * tightness * (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Crowding: if many bins fit the item, mildly prefer bins with less residual
    // (natural via post_residual), but penalize wasting a very full bin's identity.
    if bin_residual >= bin_capacity {
        // New-bin candidate: only attractive when item is large or nothing fits well.
        let large_item = item_size as f64 > 0.7 * bin_capacity as f64;
        let no_good_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual > 30);
        if large_item || no_good_fit {
            score -= 15.0;
        } else {
            score += 30.0;
        }
        // Early in stream, opening bins is cheap; late, expensive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Few open bins -> new bin less costly.
        score -= 3.0 * (open_bins_count as f64).min(10.0);
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            // Dead space unusable by next item: penalize.
            score += 6.0;
        }
    }

    // Global residual coupling: prefer bins close to mean residual (balance pool),
    // unless this is a last-chance placement.
    if bin_residual != bin_capacity && fitting_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 12.0 * poly;

    // Penalize large dead space late in the stream
    score += progress * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - norm_pr) * (1.0 - progress) * 8.0;

    // Lookahead: bonus if next item fits in post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong reward to avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty tied to crowding of open bins
    score += (open_bins_count as f64).ln() * norm_pr * 2.0;

    // Deviation from mean residual: prefer bins near mean
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    // (residuals that typical items can still fill: multiples / near-multiples of small sizes)
    let pr = post_residual;
    let class_bonus = match pr {
        0 => -60.0,                       // perfect fit: best possible outcome
        r if r % 10 == 0 => -18.0,        // round residual, easy to fill later
        r if r % 5 == 0 => -9.0,
        r if r <= 15 => 25.0,             // tiny dead space: nearly unusable
        r if r >= 90 => 12.0,             // almost-empty bin: wasteful placement
        _ => 0.0,
    };
    score += class_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // reward proportional to how tight the follow-up fit is
            if slack <= 15.0 {
                score -= (15.0 - slack) * 1.2;
            }
        } else {
            // next item cannot use this bin's remainder; slight penalty if remainder small
            if pr < 20 {
                score += 8.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // unless current open bins are very fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        // open a new bin only when existing bins are highly fragmented or full-ish
        if fragmentation < 0.35 && open_bins_count > 0 {
            score += 30.0;
        } else {
            score += 10.0;
        }
        // late in stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild preference for tighter fits overall: normalized post-residual penalty
    score += (post_residual as f64 / cap) * 10.0;

    // Small bonus for bins with below-average residual (already well-packed)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

