    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64)) * (0.5 + progress);
    score += pressure * 2.0;

    // New-bin candidate: make it attractive only when current bins create dead space.
    if bin_residual == bin_capacity {
        let dead_space_bias = if post_residual > 0 && post_residual < 10 { 30.0 } else { 0.0 };
        score -= 8.0 + dead_space_bias;
        // Discourage opening new bins early when open bins fit well.
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 5.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
