    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as f64 >= next_item_size as f64 {
            // Next item can also fit here: reward tight chains.
            score -= 300.0 / (1.0 + gap);
            score -= gap * 0.5;
        } else {
            // Next item won't fit: penalize leaving dead space relative to gap.
            score += gap * 0.3;
        }
