    // Compare post_residual to mean residual: prefer leaving residuals near the mean
    // (balanced bins) unless it's a near-perfect fit.
    let mean_dev = (post_residual as f64 - mean_residual).abs();
    score += mean_dev * 0.2;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Allow new bin early in stream or when lookahead chains well.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 * 0.5 {
            score -= 40.0;
        }
    }

    // Mild preference for tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 50.0 * progress;

    // Tie-break: slightly favor bins with fewer alternatives.
    score += fitting_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is a small fraction of capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: bonus if this bin's post-residual fits the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 15.0 / (1.0 + chain_fit);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty for blocking a chain.
        score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: discourage spreading across bins; prefer consolidation.
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64 - mean_residual / bin_capacity as f64).abs();
    }

    // New-bin candidate logic: only attractive when the item is large and fit elsewhere is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for large items, bad for small ones.
        score += 45.0 - 60.0 * fill_ratio;
        // Later in the stream, slightly prefer reusing existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty proportional to leftover relative to mean residual (avoid outliers).
    score += 0.2 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: reward tight fits (low post residual), with quadratic smoothing
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space matters more
    let late = progress * progress;
    score += 30.0 * late * norm_pr;

    // Penalize post residual that can't fit the lookahead item (smooth logistic gate)
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        let gate = 1.0 / (1.0 + (-gap / 10.0).exp());
        score += 8.0 * gate * (0.5 + progress);
    }

    // Last-chance bin bonus (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when bin residual deviates from mean residual (spread control)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Slight preference to consolidate into fewer bins when many are open
    score += 0.5 * (open_bins_count as f64).ln() * norm_pr;

    // New-bin candidate: neutral-ish baseline so it wins only when open bins are poor
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.96;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item size (1)
    // are only "dead" if they can't fit the lookahead item or typical items.
    // Penalize small unusable gaps heavily.
    let min_useful = 1u32;
    if post_residual < min_useful {
        score += 1000.0; // perfect fit, extremely desirable (post_residual == 0)
    } else {
        // Gap smaller than next item and smaller than a mid-size item = likely dead space
        let next = if next_item_size == 0 { 30 } else { next_item_size };
        if post_residual < next {
            score += (next - post_residual) as f64 * 2.0;
        }
        // Very small gaps (<10) are almost always dead
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 5.0;
        }
    }

    // Reward tight fits (small waste relative to item)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over opening new ones; when few bins are open, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 0.5;

    // New-bin candidate: make it moderately attractive only when residuals
    // across open bins are large (existing bins are wasteful targets) or
    // the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let huge_item = (item_size as f64) > mean_r * 0.85;
        if huge_item {
            score -= 10.0;
        } else {
            score += 12.0 + mean_r * 0.1;
        }
    }

    // Slight preference for bins whose residual is close to item (best-fit core)
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a slight superlinear penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = (post_residual as f64) - nxt;
            // Perfect chain fit gets a strong discount.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to how close it came (dead space risk).
            let miss = nxt - post_residual as f64;
            score += 4.0 * (miss / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving a residual near the mean keeps flexibility; extremes are penalized.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current bin fits are very poor.
    if bin_residual == bin_capacity {
        // Opening a new bin costs; make it unattractive by default.
        score += 25.0;
        // But if the next item is huge and post_residual here is full capacity (perfect for next), soften.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt as u32 >= item_size {
                score -= 10.0;
            }
        }
        // Early in the stream, opening bins is cheaper (more future to use them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Many open bins: slightly discourage spreading items too thin.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 range, use 10 as anchor).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste = post_residual - next_item_size;
        score -= 8.0 * (1.0 - waste as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize proportionally.
        score += 4.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Many fitting bins: mild penalty to encourage consolidation among few bins.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: prefer filling bins when many bins are open (consolidation pressure).
    score -= (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64) * 0.3;

    // Mean residual deviation: favor bins whose residual deviates from mean (specialization).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Time horizon: early in stream, be conservative (favor new bins for large items);
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (item_size as f64 / bin_capacity as f64) * 6.0;
    score -= progress * 3.0;

    // New-bin candidate handling: make empty bin attractive only when item is large
    // or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_options = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score += 10.0 - 18.0 * large_item - 10.0 * poor_options - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with non-linear shrinkage
    let mut score = pr_norm.powf(1.6) * cap;

    // Smooth stream-progress coupling: late in stream, tighten bins more aggressively
    let progress_coupling = 1.0 + 0.9 * progress * (1.0 - progress * 0.5);
    score *= progress_coupling;

    // Reward bins that leave residual close to mean residual (harmonious packing)
    let mean_gap = (pr - mean_residual).abs();
    score += 0.25 * mean_gap * (0.5 + progress);

    // Lookahead: bonus if post_residual can fit next item (smooth kernel)
    if next_item_size > 0 {
        let nis = next_item_size as f64;
        let fits_next = (pr >= nis) as i32 as f64;
        let tightness = 1.0 - ((pr - nis) / cap).abs();
        score -= 6.0 * fits_next * tightness * (1.0 + 0.5 * progress);
    }

    // Penalize creating unusable dead space (post residual too small for typical items)
    let dead_zone = (1.0 - (pr / 10.0).min(1.0)).max(0.0);
    score += 8.0 * dead_zone * (1.0 + progress);

    // Last-chance bin: strong reward to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr_norm);
    }

    // Many open bins: slight preference to fill existing ones rather than open more
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // New-bin candidate: neutral-ish baseline with mild late-stream penalty
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.4 * progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality classes mod 10.
    let pr = post_residual as i64;
    let class = pr % 10;
    // Perfect fit -> huge reward
    if pr == 0 {
        score -= 500.0;
    }
    // Small unusable-ish residues get penalized, but class 0 residues (multiples of 10)
    // are more reusable given the item-size grid.
    match class {
        0 => score -= 30.0,
        1 | 2 => score += 25.0,
        3 | 4 | 6 | 7 | 8 => score += 8.0,
        5 | 9 => score += 15.0,
        _ => {}
    }

    // Harmonic bucketing of post_residual via integer division thresholds.
    let bucket = pr / 25; // 0..4
    score -= bucket as f64 * 20.0; // prefer bins leaving large usable space

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if (next_item_size as u64) <= pr as u64 {
            // harmonic compatibility classes: residue mod gcd-ish of sizes
            let compat = (pr % 10) == (next_item_size as i64 % 10);
            score -= if compat { 40.0 } else { 20.0 };
        } else {
            // next item won't fit here; penalize leaving this bin as a trap
            let gap = pr - next_item_size as i64;
            score += (gap as f64).min(50.0) * 0.6;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or all open bins fit poorly.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        let open_fitting = fitting_bins_count as f64;
        // penalty for wasting a fresh bin on small items when alternatives exist
        score += 90.0 * (1.0 - load_frac) * (1.0 - load_frac);
        if open_fitting > 0.0 {
            score += 25.0;
        }
        // early stream: keep a couple of bins open for flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Slight preference to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Very tight fits (zero waste) are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward good utilization ratio of this placement.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over spreading; with few bins, mild pressure to consolidate.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, reduced when bins are scarce or
        // the mean residual across open bins is large (fragmented bins).
        let frag = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64 / 8.0).min(1.0);
        score += 45.0 + pressure * 30.0 - frag * 20.0;
        // If the next item would fit into the fresh bin's residual, bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    } else {
        // Existing bin: penalize if post_residual is large but next item
        // cannot use it (wasted capacity), reward if next item fits.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 10.0;
            } else if post_residual > 20 {
                score += (post_residual as f64 - 20.0) * 0.5;
            }
        }
    }

    // Late in the stream, be more conservative: prefer closing bins cleanly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a 2-step lookahead exact/near match:
    // if the next item fits the post-residual, this placement chains perfectly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can follow directly: big discount scaled by tightness
            score -= 30.0 + 20.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item cannot follow: penalize dead space relative to gap
            score += 0.5 * gap;
        }
    }

    // Last-chance bonus: only one bin fits; using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize bins with residuals far from mean (keeps portfolio balanced),
    // but only mildly, so tight fits still dominate.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer placing into nearly-full bins: waste small residuals early.
    score -= 0.2 * (bin_capacity as f64 - bin_residual as f64);

    // Late in the stream, compact harder (favor existing bins over new ones).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when this bin would leave
    // an awkward residual that no next item can use.
    if bin_residual == bin_capacity {
        let awkward = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score = (bin_capacity - item_size) as f64 + 40.0 * awkward - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 20.0; // opening a bin is fine when nothing else fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / (bin_residual as f64 + 1.0);
    score += 40.0 * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if this bin can also hold the next item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    }
    // Penalize if next item would be stranded by this placement.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: early in stream, favor consolidating into existing bins;
    // late in stream, be more permissive about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless item is large and mean residual is low.
        score += 20.0;
        score -= 0.25 * item_size as f64;
        score += 0.3 * mean_residual;
        score += 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 50.0; // next item needs a fresh bin anyway
        }
    } else {
        // Existing bin: reward when open bins are plentiful and residuals are high.
        score -= 0.05 * mean_residual;
        if post_residual as f64 > mean_residual {
            score += 6.0; // leaving above-average waste is bad
        }
    }

    // Mild penalty for very large items going into nearly full bins (fragmentation).
    if item_size > bin_capacity * 3 / 4 && post_residual < 15 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (low post residual), with non-linear polynomial coupling
    // to stream progress: late in the stream, dead space is penalized more strongly.
    let mut score = pr;

    // Non-linear interaction: x^2 term amplified by progress, x^3 term by (1-progress)
    let progress_gain = prog * prog;
    let early_gain = (1.0 - prog) * (1.0 - prog);
    score += 60.0 * progress_gain * x * x;      // late: punish wasted space quadratically
    score -= 40.0 * early_gain * x * x * x;     // early: mildly tolerate larger leftovers

    // Coupling with mean residual: prefer bins whose residual deviates below the mean
    // (consolidating small leftovers), scaled non-linearly by item size fraction.
    let item_frac = item_size as f64 / cap;
    let dev = (mean_residual - bin_residual as f64) / cap;
    score -= 25.0 * dev * (0.5 + item_frac);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 {
        score -= 80.0 + 120.0 * prog;
    } else if fitting_bins_count > 2 {
        score += 10.0 * (fitting_bins_count as f64).ln(); // many alternatives: less urgency
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 30.0 * (1.0 - gap / cap) * (0.5 + prog);
        } else {
            // next item won't fit here: slight penalty proportional to leftover tightness
            score += 8.0 * x * (1.0 - nxt / cap);
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual; make it
    // attractive only when current bin fits are all poor (high x elsewhere) or
    // item is large relative to typical residual.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln_1p();
        score = 55.0 + 45.0 * x - 50.0 * item_frac * (0.3 + prog)
                - 20.0 * openness * (1.0 - item_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse modulo classes mod 25 (quarter-capacity bands)
    let item_class = item_size % 25;
    let next_class = next_item_size % 25;

    // Reward tight fits: post_residual near 0 is ideal
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space that cannot fit the next item (lookahead mismatch)
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // stranded residual
        } else if post_residual >= next_item_size {
            score -= 6.0; // next item can still fit here
        }
        // Harmonic pairing: complementary classes (sums near capacity multiples)
        let pair_sum = (item_size + next_item_size) % bin_capacity;
        if pair_sum == 0 {
            score -= 12.0;
        } else if pair_sum <= 10 {
            score -= 5.0;
        }
        // class-match bonus: same harmonic band stacks predictably
        if item_class == next_class && post_residual >= next_item_size {
            score -= 3.0;
        }
    } else {
        // last item: just minimize waste
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Prefer bins below mean residual (denser bins) when residual is similar
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a fresh bin unless current bin leaves bad residue
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && next_item_size > 0 && post_residual < next_item_size;
        if bad_fit {
            score -= 5.0; // opening fresh bin is reasonable for stranded fits
        } else {
            score += 45.0; // prefer filling existing bins
        }
    }

    // Stream progression: early on, be slightly conservative (keep bins flexible)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Integer-division thresholds on post_residual: dead zones by quarter capacity
    let quarter = bin_capacity / 4;
    if post_residual > 0 && post_residual < quarter / 2 {
        score += 10.0; // tiny unusable slivers
    } else if post_residual >= quarter && post_residual < quarter + 5 {
        score -= 4.0; // fits small harmonic items well
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) + 15.0;
    }

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + open_bins_count as f64 * 3.0 + progress * 10.0;
        // But a new bin is fine if the item would leave a bad gap elsewhere
        let would_fragment = post_residual > 0 && post_residual <= 10 && bin_residual != bin_capacity;
        if would_fragment {
            score -= 30.0;
        }
    } else {
        // Prefer bins with lower residual among open bins (tighter fit)
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0; // next item can't use this tiny gap anyway
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 == next {
            score -= 60.0; // perfect chain: item + next item exactly fills bin
        } else if post_residual >= next_item_size {
            // next item fits here afterwards; reward tightness of chain
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // dead space relative to the lookahead item
            score += 15.0 * (diff / bin_capacity as f64);
        }
        // bonus if chain leaves a small-but-usable remainder
        if post_residual > next_item_size && post_residual <= 2 * next_item_size {
            score -= 8.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize leaving large unusable fragments (below min item size 1..100 heuristic floor ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New empty bin candidate: only attractive when no good fit exists;
    // make it slightly unattractive by default so filling open bins wins
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64;
        // but if lookahead chains perfectly into a fresh bin, allow it
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 55.0;
        }
        // if current item nearly fills a fresh bin, opening is fine
        if item_size * 2 >= bin_capacity {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (low post_residual) are naturally favored.

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize dead space relative to smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Last-chance bonus: only one bin fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty for wasting capacity
            score += 3.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else or open bins are very full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Cost of a fresh bin, discounted when bins are crowded / stream is early.
        let mut new_bin_cost = 60.0;
        new_bin_cost -= 25.0 * avg_fill;
        new_bin_cost -= 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            new_bin_cost -= 100.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_cost -= 10.0; // fresh bin guarantees next item fits too
        }
        score += new_bin_cost;
    }

    // Mild tie-break: prefer bins tighter than average (consolidate fullness).
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    // Slight preference for placing into already-open bins vs leaving many open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping.
    let mut score = r * (1.0 + 0.5 * norm_r * norm_r);

    // Stream-progress coupling: late in the stream, tighten preference for tight fits.
    score -= 30.0 * progress * (1.0 - norm_r) * (1.0 - norm_r);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Penalize bins whose residual deviates from the mean (avoid fragmenting many bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead coupling: reward leaving room for the next item; penalize if next item won't fit.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if r >= nx {
            score -= 12.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (nx - r) / cap;
        }
    }

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // modulo classes (multiples of 10, 20, 25) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 6.0; }

        // Penalize dead-space classes: residuals that few item sizes (10..80)
        // can exactly or closely fill are harmonic dead zones.
        if pr < 10 { score += 40.0; }                       // unusable sliver
        else if pr < 20 { score += 12.0; }                  // hard to fill
        else if pr > 80 { score -= 3.0; }                   // still very roomy
    }

    // Lookahead coupling: if next item fits the post residual exactly,
    // strongly reward (chained harmonic match).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            if slack < 10.0 { score -= 6.0; }               // near-exact chain
        } else {
            // next item cannot follow here; penalize more as post_residual shrinks
            score += 6.0 * (1.0 - pr as f64 / cap);
        }
    }

    // Last-chance bin before opening a new one: reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a fresh bin when the item is large
    // relative to capacity or when open bins are already fragmented.
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        score -= 20.0 * frag;                                // fragmentation favors new bin
        if item_size > bin_capacity / 2 { score -= 10.0; }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score += 8.0;                                    // big pair, don't waste a fresh bin
        }
    }

    // Mild stream-phase modulation: early on, keep bins roomy; late, pack tight.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * phase * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps smaller than the minimum item size (1..100 stream)
    // but too small to be practically reusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 25.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 50.0;
        } else if slack < 10 {
            score -= 20.0;
        }
    }
    // If next item cannot fit here, mild penalty for wasting the gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins;
    // the new-bin candidate gets penalized via its large post_residual already,
    // but add explicit pressure scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * progress;
    }

    // Prefer bins with below-average residual (tighter bins) when fits are comparable.
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild preference to keep filling the same bin as the stream advances.
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is ideal.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - diff / (bin_capacity as f64));
            // bonus if next item still leaves a plausibly reusable remainder
            score -= 5.0 * (post_residual as f64 - nxt) / bin_capacity as f64;
        } else {
            // next item cannot follow into this bin: penalize proportionally to wasted space
            score += 10.0 + 0.5 * (nxt - post_residual as f64);
        }
        // if next item would perfectly fill bin_residual now, prefer leaving that shape
        if bin_residual as u32 == next_item_size && post_residual > 0 {
            score += 25.0;
        }
    } else {
        // last item: strongly prefer tightest fill
        score -= 30.0;
    }

    // Reward fitting into scarce bins (last chance before opening a new bin)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize creating small unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Coupling with mean residual: prefer bins below average residual (tighter bins)
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when few/no good fits or lookahead mismatch is severe
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let early = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 30.0 * pressure - 20.0 * (1.0 - early);
        if next_item_size > 0 && (bin_residual as u32 >= next_item_size + item_size) {
            score -= 10.0; // fresh bin can chain both items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: near-zero post residual is excellent.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tightness * tightness * (item_size as f64 / cap);

    // Penalize small dead space (hard to fill later): residuals 1..~10 are worst.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - (post_residual as f64) / 15.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless it's a great idea.
    if bin_residual == bin_capacity {
        // Opening a bin when many bins could fit is wasteful.
        score += 20.0;
        // But if the item is large relative to capacity and few bins fit, opening may be fine.
        let big_item = item_size as f64 / cap;
        if fitting_bins_count <= 1 {
            score -= 15.0 * big_item;
        }
        // Late in stream, prefer closing out existing bins rather than spawning.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If mean residual is large, existing bins have room; new bin less attractive.
        score += 0.15 * mean_residual;
    }

    // Lookahead coupling: if the next item fits the post-residual, this placement
    // chains nicely; reward it.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0 * (next_item_size as f64 / cap);
        } else if (next_item_size as u32) <= bin_residual {
            // next item would fit the bin as-is; placing current item here may block it.
            score += 5.0;
        }
    }

    // Prefer using bins with lower residual relative to mean (consolidate emptier bins).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Mild preference for fewer open bins early on to keep consolidation pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping (favor tight fits)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr) - 2.0 * norm_pr * (1.0 - norm_pr) * cap;

    // Stream-progress coupling: later in stream, penalize waste more strongly
    score += progress * pr * pr / cap;

    // Perfect fit reward (smooth, quadratic decay of bonus)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.5 * pr;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let lookahead_fit = next_item_size as f64 / pr.max(1.0);
        score -= 8.0 * lookahead_fit;
    } else if next_item_size > 0 {
        // penalize leaving residual that wastes space for the known next item
        score += 3.0 * (1.0 - (next_item_size as f64 - pr).abs() / cap);
    }

    // Mean residual coupling: prefer bins deviating from mean residual (balance diversity)
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: make it attractive only early or when residuals are all tight
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).max(0.0).min(1.0);
        score = pr + 12.0 * (1.0 - progress) - 20.0 * tightness * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect close
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Harmonic class logic on post_residual: penalize dead space that cannot
    // plausibly host small items. Classes based on modulo of capacity fractions.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        // small slivers: strongly penalize unless it was last-chance
        score += 30.0 * (10.0 - dead);
    }

    // Modulo classes on post_residual relative to capacity quarters:
    // residual near a quarter class (25/50/75) is reusable by mid-size items.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    for cls in [quarter, half, 3 * quarter] {
        let d = (post_residual as i64 - cls as i64).unsigned_abs() as f64;
        if d <= 8.0 {
            score -= 25.0 * (8.0 - d);
        }
    }

    // Harmonic penalty: post_residual mod small divisors — odd slivers are worse.
    let pr = post_residual;
    if pr > 0 && pr < 20 {
        if pr % 2 == 1 {
            score += 6.0;
        }
        if pr % 5 != 0 {
            score += 4.0;
        }
    }

    // Lookahead coupling: reward if next item fits the post_residual well.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += ((next_item_size - pr) as f64).sqrt() * 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened late in stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 - 60.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host anything next
        }
        if mean_residual > (bin_capacity as f64) * 0.5 && fitting_bins_count > 0 {
            score += 40.0; // plenty of room in open bins; discourage new bin
        }
    }

    // Slight preference to consolidate: bins with residual below mean are
    // candidates for closing out; reward filling below-average bins.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Mild pressure to keep number of open bins bounded.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible future item (items >= 1) are heavily penalized.
    // A residual below the minimum item size is pure waste.
    if post_residual < 1 {
        score += 1000.0; // impossible, shouldn't happen
    }
    // Dead-space tiers: gaps that can only fit tiny items are punished hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable for typical items
    } else if post_residual < 25 {
        score += 18.0; // barely usable
    } else if post_residual < 50 {
        score += 6.0;
    }

    // Perfect fit reward: closing a bin completely is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next < 10 {
                score += 8.0; // would create dead space next step
            } else {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: mild penalty proportional
            // to how much of the residual it wastes
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 10.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists elsewhere; scale with number of open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + 0.5 * progress);

    // Prefer bins with below-mean residual (tighter bins get priority),
    // keeping residuals balanced toward compactness.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 12.0 * dev;

    // New-bin candidate handling: an empty bin has high residual; only allow
    // it to win when the current fit is poor (large post residual) or the
    // item would leave a big gap in an existing bin.
    if bin_residual == bin_capacity {
        // Baseline score roughly equals capacity; add mild pressure so that
        // good existing fits beat opening a new bin.
        score += 5.0 + 0.5 * open_bins_count as f64;
        // But if the current item is large, a fresh bin is often better.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        if progress > 0.7 {
            score += 15.0 * progress;
        }
    }

    // Slight reward for high fill ratio of the chosen bin.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer post_residual close to next_item_size (2-step lookahead match)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for near-exact match: post_residual leaves room for next item
        let match_bonus = if post_residual >= next_item_size {
            // next item fits exactly-ish in the leftover
            let tight = diff / (bin_capacity as f64);
            40.0 * (1.0 - tight.min(1.0))
        } else {
            // leftover too small for next item: dead space penalty scaled by waste
            -0.35 * (next_item_size as f64 - post_residual as f64)
        };
        score -= match_bonus;
    } else {
        // Last item: pure tight fit preference
        score -= 10.0;
    }

    // Penalize bins whose residual is far above mean (hoarding large residual poorly)
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Reward using bins that are already relatively full (small residual before placement)
    score += 0.25 * (bin_residual as f64 - item_size as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && (bin_capacity as f64 - mean_residual) < item_size as f64 * 0.5;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // opening a fresh bin can host item + next item pair
            score -= 30.0;
        } else if good_fit_exists {
            score += 60.0; // discourage opening when decent fits exist
        } else {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: favor tighter packing as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild pressure against proliferating open bins
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 10.0;
        }
        // Perfect chaining: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    let pressure = mean_residual / bin_capacity as f64;
    score += pressure * 12.0;
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 1.5;
    }

    // New-bin candidate handling: only attractive when current residuals are poor.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual;
        // If open bins are already tight, a fresh bin is fine; otherwise discourage.
        score += 20.0 - avg_waste * 0.3;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Time horizon: early on, keep bins flexible (favor moderate residuals);
    // late, squeeze maximally.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    // Mild penalty for very large items consuming almost the whole bin elsewhere.
    if item_size > bin_capacity * 3 / 4 && bin_residual > item_size {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to stream progress.
    let poly = 1.0 + 0.8 * progress * norm_pr + 0.5 * progress * progress * norm_pr * norm_pr;
    let mut score = pr * poly;

    // Penalize large dead space more than linearly (quadratic waste term).
    score += 0.35 * pr * pr / cap;

    // Reward tight fits: subtract when post_residual is small relative to item size.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 12.0 * tightness * (1.0 - progress);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill_after = 1.0 - ((pr - nx) / cap);
            score -= 8.0 * fill_after * fill_after;
        } else {
            // Next item won't fit here; slight penalty proportional to excess.
            score += 0.05 * (nx - pr);
        }
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers),
    // with a smooth interaction with progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * (0.5 + 0.5 * progress);

    // Mild penalty when many bins are open (encourage consolidation early).
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make empty bins attractive only when item is large
    // relative to residual landscape (avoid wasting fresh capacity on small items).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score += 20.0 * (1.0 - item_frac) * (1.0 - 0.5 * progress);
        score -= 5.0 * item_frac * item_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "friendly"
    // (multiples of common item sizes) are more reusable than odd leftovers.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill = 1.0 - pr / cap; // fraction of bin filled

    // Reward high fill ratio strongly.
    score -= 60.0 * fill * fill;

    // Harmonic class of post_residual modulo 10: class 0 residuals are ideal.
    let class = post_residual % 10;
    score -= match class {
        0 => 18.0,
        5 => 10.0,
        2 | 4 | 6 | 8 => 4.0,
        _ => 0.0,
    };

    // Dead-space penalty: tiny residuals that no item (>=1..100) may use well.
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    }
    // Extremely tight fit: perfect packing reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // harmonic bonus when next item leaves again a class-0 residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0; // bin likely closed after this item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are fragmented or the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        score = 55.0 + 0.35 * open_bins_count as f64
              + 0.5 * mean_residual
              - 40.0 * (item_size as f64 / cap);
        if mean_residual < item_size as f64 {
            score -= 30.0; // open bins too full -> prefer new bin
        }
        if fragmentation < 5.0 && open_bins_count > 0 && item_size <= mean_residual as u32 {
            score += 25.0; // open bins healthy -> discourage new bin
        }
    }

    // Late-stream consolidation: prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * fill;

    // Integer-division threshold: residual buckets via post_residual / 20.
    let bucket = post_residual / 20;
    score += bucket as f64 * 2.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but with a dead-space penalty:
    // gaps that are too small to ever be useful (<= 10) are heavily penalized,
    // while post_residual == 0 is perfectly packed.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        // Unusable dead space: worse than a moderately large gap.
        score += 80.0;
    } else if post_residual <= 20 {
        score += 20.0;
    }

    // Exact-ish fit reward relative to item size (tight packing is good).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Pressure from number of open bins: when many bins are open,
    // prefer filling existing bins over opening new ones.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward this placement strongly (creates a perfect follow-up).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // Next item cannot use the leftover gap: penalize unusable leftovers more.
            score += 10.0;
        }
    }

    // Mean residual coupling: if average residual is small, be extra thrifty
    // (waste is relatively more costly); if large, tolerate looser fits.
    score += (mean_residual - post_residual as f64) * 0.5;

    // Slight stream-progression tilt: later in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; the dead-space penalties above make poor fits
        // in open bins lose against opening a new bin.
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize wasted space quadratically.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly reward post_residual that matches next_item_size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Partial lookahead credit: closeness of post_residual to next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportionally to how much it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.5 * miss;
    }

    // Relative to mean residual: prefer bins whose post_residual deviates favorably
    // (leaving less residual than average means tighter packing).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and when open bins exist; allow it for huge items or very poor fits.
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 60.0; // fresh bin guarantees the next item fits too
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    }

    // Prefer spreading load when many bins are open with slack (avoid fragmentation).
    if open_bins_count > 1 && post_residual > 0 {
        score += 0.05 * (post_residual as f64 / mean_residual.max(1.0) - 1.0).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual with a convex term.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * pr;

    // Reward high fill ratio of this placement.
    score -= 0.6 * (item_size as f64 / bin_residual as f64) * item_size as f64;

    // Lookahead: if the next item fits exactly into the post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits here too; good if it also leaves a usable remainder
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1.0) as f64);
        } else {
            // next item cannot use this bin's remainder; penalize wasted space
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin should only win when alternatives are bad.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin is rarely chosen over decent fits.
        score += 12.0;
        // But late in the stream, or when many bins are open with fragmented space,
        // opening a new bin is cheaper than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        if mean_residual < 0.5 * bin_capacity as f64 && open_bins_count > 2 {
            score -= 6.0;
        }
        // Big items: prefer a fresh bin for them anyway (less fragmentation later).
        score -= 0.05 * item_size as f64;
    }

    // Prefer bins below mean residual (consolidate emptier bins) mildly.
    score += 0.08 * (mean_residual - bin_residual as f64);

    // Encourage closing bins: if post_residual is tiny, reward extra.
    if post_residual <= 5 && post_residual > 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let fit_frac = it / cap;

    // Base: prefer tight fits; non-linear (quadratic-ish) penalty on waste.
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Smooth stream-progress coupling: later in the stream, waste is costlier.
    score += 2.0 * progress * pr;

    // Dead-space penalty: residuals too small for any plausible item (items >= 1).
    let dead = ((40.0 - pr).max(0.0) / 40.0).powi(3);
    score += 25.0 * dead * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 30.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0) * (1.0 - fit_frac);
    }

    // New-bin candidate: penalize opening a new bin, more so when other bins fit well.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - pr).abs();
        score += 35.0 + 40.0 * (1.0 - progress) + 0.3 * open_bins_count as f64 + 0.2 * spread;
    } else {
        // Mild reward for bins with residual close to mean (keeps fleet balanced).
        score -= 3.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));
    }

    // Small fit-quality reward: larger items placed more eagerly.
    score -= 8.0 * fit_frac * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward (harmonic anchor)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: reward post_residuals that are "usable" sizes (small dead space)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Penalize dead space quadratically, scaled by capacity
    score += (pr / cap) * (pr / cap) * 60.0;

    // Modulo-class logic: post_residual divisible by common small item sizes is reusable
    let pr_u = post_residual;
    if pr_u > 0 {
        let mut bonus = 0.0;
        if pr_u % 10 == 0 { bonus += 15.0; }
        if pr_u % 20 == 0 { bonus += 10.0; }
        if pr_u % 25 == 0 { bonus += 8.0; }
        if pr_u % 50 == 0 { bonus += 10.0; }
        score -= bonus;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score += (slack as f64) * 0.5;
        } else {
            // next item won't fit here anyway; slight penalty for wasting big residual
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: only prefer fresh bin when no open bin fits well
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper late in the stream is not allowed,
        // so keep constant but modulated by how many bins already fit the item
        score += 40.0 + (fitting_bins_count as f64) * 25.0;
        // If mean residual across open bins is large, opening new bin is wasteful
        score += mean_residual * 0.3;
    }

    // Mild preference for tighter (smaller residual) bins among open bins
    score += (bin_residual as f64) * 0.05;

    // Stream progression: early on, be slightly more willing to open bins (explore)
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= progress * 10.0;
        }
    }

    // Penalize bins whose residual is awkwardly small relative to mean
    if (bin_residual as f64) < mean_residual * 0.5 && bin_residual >= item_size {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly useless.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // penalize gaps that are too small for the smallest plausible item
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0;
        }
        // penalize gaps that cannot fit the next item (lookahead-aware dead space)
        if next_item_size > 0 && gap < next_item_size as f64 {
            score += 25.0 + 0.5 * (next_item_size as f64 - gap);
        }
        // superlinear penalty on tight fits leaving tiny residue
        score += 8.0 / (1.0 + gap);
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.4 + 0.6 * progress);

    // Prefer bins tighter than the mean residual (compact packing)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it moderately attractive only when current bin
    // would leave a large wasteful gap; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        // base penalty keeps new bins from winning trivially
        score += 15.0;
        // but if this item would leave a big residual in an open bin anyway,
        // a fresh bin is fine (its post_residual is large & usable)
        if post_residual >= 20 {
            score -= 10.0 + 0.2 * post_residual as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // prefer small leftover after chaining next item
            score -= 100.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportional to wasted potential
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.5 * overflow;
        }
    }

    // Compare post_residual against mean residual: keep bins balanced, avoid
    // leaving this bin far below average (dead space) when alternatives exist.
    let post = post_residual as f64;
    if post > mean_residual {
        score += 0.3 * (post - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // A fresh bin is attractive only if the item is large relative to capacity
        // and no tight fit exists; base cost plus mild size discount.
        score += 120.0 - 0.5 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin can also host the next item
        }
    }

    // Late in the stream, tighten packing: penalize loose residuals more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.4 * post;

    // Mild pressure against proliferation of open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits: subtract bonus proportional to fill
    score -= 8.0 * fill * fill;

    // Penalize dead space: residuals that are too small to hold typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // awkward residual band
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Competition among fitting bins: prefer the one that wastes least relative to mean
        score += 0.5 * (mean_residual - bin_residual as f64).abs();
    }

    // New-bin candidate handling: residual == capacity
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when item is small (leaves big residual)
        // and existing fits are poor (many fitting bins means we can be picky elsewhere)
        score -= 10.0 * fill; // small items: residual large, fill small -> big discount
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits anywhere: must open
        }
        if fitting_bins_count == 1 && item_size > bin_capacity / 2 {
            score += 5.0; // big item with a last-chance bin: prefer using it
        }
        // Late in the stream, prefer consolidating into open bins
        score += 10.0 * progress;
    }

    // Global pressure: many open bins with high mean residual -> encourage consolidation
    if open_bins_count > 2 {
        let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        score += 2.0 * consolidation * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr + 40.0 * poly;

    // Penalize waste relative to mean residual (smooth coupling).
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Reward tight fits.
    score -= 25.0 * (1.0 - norm_pr) * norm_pr;

    // Last-chance bonus: strongly favor this bin if it is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space compatible with next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.2 * gap;
        if next_item_size as f64 <= pr {
            score -= 10.0;
        }
    }

    // Mildly discourage bin proliferation early on.
    score += 2.0 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is a "usable"
    // class (multiples of 10 / large enough) are less penalized.
    let class = post_residual % 10;
    if class != 0 {
        score += (10 - class) as f64 * 0.6; // snap penalty toward next multiple of 10
    }

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (small post_residual) superlinearly.
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            score += 8.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // existing residuals are poor or the fit is loose.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - post_residual as f64).abs();
        score += 12.0 - mean_gap * 0.3;
        if item_size > 70 {
            score -= 10.0; // big items deserve fresh bins
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 5.0; // next item won't fit after this placement anyway
        }
    }

    // Prefer filling bins with larger residuals relative to mean (balance).
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are worthless; penalize tiny unusable gaps heavily.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 40.0; // dead space below min item size
    }

    // Reward tight fits (small relative slack).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; discourage opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are open
        // and how much slack already exists.
        score += 20.0 + 4.0 * open_bins_count as f64 + mean_residual * 0.5;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits in post_residual, bonus; if it clearly
    // won't, penalize leaving an awkward gap.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 8.0 * (post_residual as f64 / 100.0);
        }
    }

    // Early in the stream, be slightly more willing to open bins (build diversity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that end up nearly full.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: reward when the next item fits into the post-residual
    // (chain packing), penalize dead space that cannot host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
        } else {
            // Next item cannot fit here: penalize leftover that becomes dead space.
            let dead = (post_residual - (post_residual % next_item_size)) as f64;
            score += dead * 0.1;
            score += 10.0;
        }
    }

    // Relative to mean residual: prefer bins tighter (more filled) than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // but allow it late in the stream or when the fit is poor elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = 100.0 - item_size as f64;
        score += waste * 0.4;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 30.0; // new bin can host the next item too
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if progress > 0.8 {
            score -= 15.0;
        }
    }

    // Mild penalty for creating small unusable residuals (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't chain here; mildly penalize leaving awkward gap
        let gap_waste = (post_residual as f64).min(next_item_size as f64 - 1.0);
        score += 0.2 * gap_waste;
    }

    // Last-chance bonus: only one bin fits the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins below mean residual (keep residuals balanced)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Time horizon: early in stream, be conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax late
        score += 20.0 * (1.0 - progress);
        // If no existing bin fits well, opening new bin may be fine
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
        // Large next item favors a fresh bin
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Many open bins: discourage spreading, favor consolidation
    score += 0.5 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);
    score -= 25.0 * pr_norm * (1.0 - pr_norm) * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 30.0 * (1.0 - pr_norm).powi(3) * (0.3 + 0.7 * progress);

    // Lookahead: reward if next item fits into the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - slack).powi(2) * (0.4 + 0.6 * progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * gap;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 35.0 * (0.5 + 0.5 * progress);
    }

    // Penalize opening new bins when many bins are already open and mean residual is high
    let mean_norm = mean_residual / cap;
    let new_bin = (bin_residual as f64 == cap) as f64;
    score += new_bin * (10.0 + 20.0 * mean_norm * (0.3 + 0.7 * progress));

    // Mild preference for consolidating into bins with below-average residual
    score += 8.0 * ((pr - mean_residual) / cap).clamp(-1.0, 1.0) * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common small item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        // Perfect fit class
        if pr == 0 { harmonic_bonus -= 60.0; }
        // Small usable leftovers (<= 10) are near-perfect: strong reward
        if pr <= 10 { harmonic_bonus -= 45.0; }
        // Modulo classes: leftovers divisible by common item granularities
        if pr % 10 == 0 { harmonic_bonus -= 18.0; }
        if pr % 20 == 0 { harmonic_bonus -= 10.0; }
        if pr % 25 == 0 { harmonic_bonus -= 8.0; }
        // Dead zone: leftovers in (10, 20) are hard to fill with items >= 10
        if pr > 10 && pr < 20 { harmonic_bonus += 30.0; }
        // Leftovers in (50, 60) leave awkward half-space
        if pr > 50 && pr < 60 { harmonic_bonus += 6.0; }
        score += harmonic_bonus;
    }

    // Integer-division threshold on residual fraction: how much of the bin is consumed
    let fill_quarters = (bin_capacity - pr) * 4 / bin_capacity; // 0..4 consumed quarters
    score -= fill_quarters as f64 * 5.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0;
        } else if next_item_size <= pr {
            // next item fits but leaves residue; reward proportional to tightness
            score -= 20.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (pr as f64).min(80.0) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // neutral base for fresh bin, scaled by stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 20.0 * progress;
        // if next item is huge, a fresh bin is more attractive
        if next_item_size >= 60 { score -= 15.0; }
    }

    // Prefer bins tighter than the mean residual (consume fragmented space first)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild exploration noise-free tie-break by open bin count pressure
    if open_bins_count > 8 {
        score -= 2.0; // encourage consolidating into existing bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
