    // Open-bin pressure: discourage proliferating bins when residuals
    // are still healthy; encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual != bin_capacity {
        score += pressure * 0.15;
    }

    // New-bin candidate: default attractiveness based on mean residual state.
    if bin_residual == bin_capacity {
        // Prefer a fresh bin only when existing bins are heavily fragmented
        // (low mean residual) or the item is large and fits nowhere well.
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 30.0 - 45.0 * fragmentation;
        if item_size > 70 {
            score -= 10.0;
        }
    }

    // Prefer filling bins with larger residual gaps when item is large.
    if item_size >= 50 && bin_residual >= item_size {
        score -= 0.05 * (bin_residual - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: only prefer a fresh bin when it is genuinely better.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = (bin_capacity as f64) * 0.6;
        // If the next item would fit perfectly in the residual left here, opening is attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
        // If the item fits very snugly in an existing bin, discourage opening a new one.
        if post_residual <= 5 {
            score += 25.0;
        }
        // Last-chance bin: strongly discourage opening a new bin.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        return score;
    }

    // Perfect 2-step match: post residual exactly equals next item size -> reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item fits into post residual: reward proportionally to how well it fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.35;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space, more so late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (post_residual as f64).min(next_item_size as f64) * 0.25 * (0.5 + progress);
    }

    // Reward tight fits relative to mean residual across open bins.
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 8.0;
    } else if (post_residual as f64) > mean_residual * 1.5 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Small bonus for leaving nothing usable behind (exact fill).
    if post_residual == 0 {
        score -= 15.0;
    }

    // Mild penalty for very small post residuals that no typical item (>=1) can use well
    // unless they are exact matches (already rewarded).
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 60.0;

    // Penalize large dead space quadratically, scaled by how many bins are open.
    let dead = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += dead * 40.0 * (1.0 + open_bins_count as f64 * 0.05);

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a gap that likely becomes dead space.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer new bin only when all open bins fit badly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of opening a new bin, softened late in the stream.
        score = 45.0 + 30.0 * (1.0 - progress);
        if mean_residual > item_size as f64 + 20.0 {
            // Open bins have plenty of room on average; opening new bin is wasteful.
            score += 25.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - 15 {
            // Big item coming; a fresh bin may be useful.
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative anyway
        }
    }

    // Slight preference for filling bins with above-average residual (balance avoidance).
    if bin_residual != bin_capacity {
        score -= (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space, with a convex (quadratic) penalty on small residuals.
    let mut score = pr + 0.9 * (pr / cap) * (pr / cap) * cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - pr / cap;
    score -= progress * 8.0 * tightness * tightness;

    // Interaction: post_residual vs mean residual — avoid making a bin an outlier
    // with unusable dead space relative to the fleet average.
    score += 0.35 * (pr - mean_residual) * (1.0 - progress);

    // Last-chance bonus: if this is the only bin that fits, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 5.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic mismatch).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.25 * gap * gap / cap;
        // Extra reward if the next item exactly fits the post residual.
        score -= 4.0 * (1.0 - (gap / cap).min(1.0)) * (1.0 - progress);
    }

    // Mild penalty for proliferating bins early in the stream.
    score += 0.4 * open_bins_count as f64 * (1.0 - progress) * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless the stream is early
    // or the post residual would be perfectly usable for typical items.
    if bin_residual == bin_capacity {
        let usability = (pr / cap) * (1.0 - (pr / cap - 0.5).abs() * 2.0).max(0.0);
        score += 6.0 * progress - 3.0 * usability;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: reward post_residual divisible into common co-sizes
    let pr = post_residual;
    let harmonic_bonus = |r: u32| -> f64 {
        if r == 0 { return 0.0; }
        // classes: multiples of 10, 25, 50, 20
        if r % 50 == 0 { -60.0 }
        else if r % 25 == 0 { -40.0 }
        else if r % 20 == 0 { -35.0 }
        else if r % 10 == 0 { -25.0 }
        else if r % 5 == 0 { -10.0 }
        else { 0.0 }
    };
    score += harmonic_bonus(pr);

    // Penalize small dead space (unusable for typical items 1..100)
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next fits but not perfectly: mild reward proportional to fill
            score -= 10.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 0.1 * (pr as f64);
        }
    }

    // Last-chance bin: strongly prefer using it over opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (bin_residual.saturating_sub(item_size)) < 20;
        let mut new_bin_score = 0.5 * cap;
        if fitting_bins_count == 0 {
            new_bin_score -= 300.0; // nothing else fits, must open
        } else if good_fit_exists {
            new_bin_score += 150.0; // a tight fit exists elsewhere
        }
        if next_item_size > 0 && next_item_size > bin_residual {
            new_bin_score -= 50.0;
        }
        score = new_bin_score;
    }

    // Mild preference for fuller bins relative to mean residual
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Stream progression: early on, be slightly conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).log2().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps below the minimum item size are unusable.
    let dead_threshold = 10.0;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 40.0;
    }

    // Mild reward for tight fits (small positive post_residual is fine).
    if post <= dead_threshold {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, keep it attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * (open_bins_count as f64);
    } else {
        score -= 2.0;
    }

    // Prefer bins with residual far below mean (consolidate waste).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late-stream bias: prefer tighter packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item still fits after this placement: mild reward
            score -= (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item cannot fit: dead space penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: strongly prefer zero post_residual (already handled)
    }

    // Penalize post_residual below the minimum item size (unusable dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0 * (10 - post_residual) as f64;
    }

    // Relative to mean residual: prefer bins with less residual than average
    score += (mean_residual - post_residual as f64) * -0.1;

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a bad fit
    if fitting_bins_count == 1 {
        let waste = post_residual as f64;
        if waste > 0.0 && next_item_size > 0 && next_item_size > post_residual {
            score += 100.0; // discourage consuming last chance poorly
        }
    }

    // New-bin candidate: make it attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 120.0;
        // If no other bin fits, opening is forced/cheap
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If next item is large, a fresh bin is valuable
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Mild penalty for too many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Dead space if next item cannot use the leftover.
            score += 4.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins would leave large unusable waste or are scarce fits.
    if bin_residual == bin_capacity {
        let waste_if_existing = mean_residual - item_size as f64;
        let pressure = if fitting_bins_count <= 1 { 12.0 } else { 0.0 };
        if post_residual as f64 >= 20.0 {
            // New bin keeps a large residual, useful for future big items.
            score -= 10.0 + pressure;
        } else {
            score += 15.0 + pressure.max(0.0) - waste_if_existing.max(0.0).min(10.0);
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins: discourage another one.
        score += 0.5 * open_bins_count as f64;
    } else {
        // Reusing bins is generally good; slight bonus scaled by fullness.
        let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 3.0 * fill_ratio;
    }

    // Prefer bins below mean residual (keeps spread balanced, avoids many tiny leftovers).
    score += 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pn = post / cap;
    let poly = pn * pn * (1.0 - pn);
    score += 30.0 * (progress - 0.5) * poly;

    // Dead-space penalty grows late in the stream
    let dead = (post / cap).powi(3);
    score += 40.0 * progress * dead;

    // Reward tight fits (small post_residual relative to item)
    let tight = 1.0 - (post / (item_size as f64 + post + 1.0));
    score -= 15.0 * tight;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins below mean residual (fill emptier-ish bins less)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Lookahead: penalize wasting space needed by next item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0) / cap;
        score += 20.0 * gap * gap;
    }

    // Mild preference for existing bins over opening new ones early
    score += (open_bins_count as f64).ln() * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 modulate dead-space penalty.
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.6; // awkward leftovers (1..9 mod 10) are less reusable

    // Integer-division thresholds: post_residual in (0,10] is near-perfect fill.
    if post_residual <= 10 && post_residual > 0 {
        score -= 40.0;
    } else if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Reward tight fit relative to residual (fraction of bin used by this item).
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 12.0;

    // Lookahead coupling: if next item exactly fits post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let next_class = (next_item_size + post_residual) % 10;
            if next_class == 0 {
                score -= 20.0; // pair sums to a harmonic multiple of 10
            }
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.4;

    // New-bin candidate: penalize so it is chosen only when fits are poor.
    if bin_residual == bin_capacity {
        // Opening fresh is attractive late in stream or when many bins open already.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let base = cap * 0.55 + 30.0; // typically worse than any decent fit
        score = base - progress * 25.0 - (open_bins_count as f64) * 0.8;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // large next item benefits from a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (0 < post_residual < 10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a loose fit.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 10.0;
    }

    // Open-bins pressure: penalize spreading across many bins when the fit is loose.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: keep it attractive only when current bins would leave large dead space.
    if bin_residual == bin_capacity {
        let loose_fit_penalty = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        score = 30.0 + 20.0 * loose_fit_penalty;
        if fitting_bins_count <= 2 {
            score += 25.0; // discourage opening new bins when decent options exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-perfect 2-step match: next item fits with small leftover -> scaled reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / 40.0).max(0.0);
    }

    // Penalize dead space that cannot fit the next item (wasted residual).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Favor bins tighter than the mean residual (fill fuller bins first).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Slight preference for fewer open bins (bin consolidation pressure).
    score -= open_bins_count as f64 * 0.1;

    // Late in the stream, tighten packing more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}
